// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"c1-esterase-inhibitor-human":{"wirkmechanismus":"Ersetzt ein Eiweiss im Blut, das beim erblichen (hereditären) Angioödem fehlt oder nicht richtig funktioniert. Der C1-Esterase-Inhibitor hemmt Enzyme des Komplement- und des Kontaktsystems, insbesondere Plasmakallikrein und Faktor XIIa. Fehlt er, entsteht übermässig Bradykinin, das die Gefässe durchlässig macht und die typischen Schwellungen von Haut, Schleimhäuten, Darm und Kehlkopf auslöst. Die Zufuhr hebt die C1-INH-Aktivität an und bremst die Bradykininbildung.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Einstichstelle bei Injektion unter die Haut (Schmerz, Schwellung, Rötung, Bluterguss)"],"haeufig":["Kopfschmerzen","Schwindel","Übelkeit","Hautausschlag","Nasopharyngitis (Erkältungssymptome)"],"gelegentlich":["Venenentzündung (Phlebitis) und Venenthrombose","Fieber","Juckreiz, Hautrötung"],"selten":["Überempfindlichkeitsreaktionen bis Anaphylaxie"]},"schwangerschaft":"Bisherige Erfahrungen ohne Hinweise auf schädliche Wirkungen; Anwendung, wenn klar notwendig (HAE-Attacken können in der Schwangerschaft gefährlich sein).","stillzeit":"Ein Risiko für den Säugling ist nicht zu erwarten; Anwendung nach ärztlicher Abwägung.","hinweise":["Nach Schulung kann das Mittel zu Hause selbst gespritzt werden; die Chargennummer jeder Packung notieren.","Bei Schwellungen im Hals- oder Kehlkopfbereich trotz Injektion sofort den Notfall aufsuchen.","Impfungen gegen Hepatitis A und B mit der Ärztin oder dem Arzt besprechen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (in die Vene)","Pulver und Lösungsmittel zur Injektion unter die Haut"]},"cabazitaxel":{"wirkmechanismus":"Hemmt die Zellteilung von Krebszellen. Cabazitaxel bindet an Tubulin und stabilisiert die Mikrotubuli, sodass sich der Spindelapparat nicht mehr abbauen kann und die Zellteilung blockiert wird. Weil es von der Efflux-Pumpe P-Glykoprotein nur schlecht aus der Zelle befördert wird, wirkt es auch bei Tumoren, die gegen Docetaxel resistent geworden sind.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Anämie, Leukopenie, Thrombozytopenie","Durchfall, Übelkeit, Erbrechen, Verstopfung, Bauchschmerzen","Appetitlosigkeit, Geschmacksstörungen","Müdigkeit, Schwäche","Atemnot, Husten","Rücken- und Gelenkschmerzen"],"haeufig":["Febrile Neutropenie, Harnwegs- und andere Infektionen, Sepsis","Periphere Neuropathie (Kribbeln, Taubheitsgefühl), Schwindel, Kopfschmerzen","Blut im Urin, akutes Nierenversagen","Vorhofflimmern, Herzrasen","Tiefer oder hoher Blutdruck, tiefe Venenthrombose","Haarausfall, trockene Haut","Mundschleimhautentzündung, Hämorrhoiden, Sodbrennen","Fieber, Ödeme, Flüssigkeitsmangel, Hypokaliämie (Kaliummangel)"],"gelegentlich":["Kolitis, neutropenische Enterokolitis (schwere Darmentzündung)","Magen-Darm-Blutungen und -Durchbruch, Darmverschluss"],"unbekannt":["Interstitielle Lungenerkrankung, Pneumonitis","Strahlenerinnerungsreaktion (z. B. Blasenentzündung nach früherer Bestrahlung)"]},"schwangerschaft":"Nicht für Frauen bestimmt. Männer müssen während der Behandlung und mehrere Monate danach Kondome verwenden und sollten sich vor Beginn über eine Spermienkonservierung beraten lassen.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Vor jeder Infusion erfolgt eine Vorbehandlung (Antihistaminikum, Kortikosteroid, H2-Blocker) gegen Überempfindlichkeitsreaktionen.","Prednison oder Prednisolon täglich wie verordnet einnehmen.","Fieber, anhaltenden Durchfall oder Blut im Urin sofort melden; ausreichend trinken.","Die Infusionslösung enthält Alkohol (Ethanol): Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"cabergolin":{"wirkmechanismus":"Senkt die Menge des Hormons Prolaktin, das die Milchbildung anregt und bei Überschuss Zyklusstörungen, Unfruchtbarkeit und Libidoverlust verursacht. Cabergolin ist ein lang wirksamer Agonist an Dopamin-D2-Rezeptoren der prolaktinbildenden Zellen der Hirnanhangdrüse (Hypophyse) und hemmt dort die Prolaktinausschüttung; Prolaktinome können dabei schrumpfen. Wegen der sehr langen Halbwertszeit genügt meist eine Einnahme ein- bis zweimal pro Woche. Als Mutterkorn-(Ergolin-)Abkömmling stimuliert es auch Serotonin-5-HT2B-Rezeptoren, was mit Fibrosen und Herzklappenveränderungen in Verbindung gebracht wird.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Kopfschmerzen","Schwindel","Bauchschmerzen, Verdauungsbeschwerden (Dyspepsie), Magenschleimhautentzündung","Schwäche und Müdigkeit","Herzklappenveränderungen (Valvulopathie) und verwandte Störungen wie Herzbeutelentzündung oder -erguss"],"haeufig":["Depression","Schläfrigkeit (Somnolenz)","Verstopfung, Erbrechen","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Hitzewallungen","Brustschmerzen (Mastodynie)"],"gelegentlich":["Herzklopfen (Palpitationen)","Ohnmacht (Synkope), Kribbeln (Parästhesien)","Vorübergehende Gesichtsfeldausfälle","Atemnot, Pleuraerguss (Flüssigkeit im Brustfellraum), Lungenfibrose","Nasenbluten","Krämpfe der Fingergefässe (Vasospasmus)","Haarausfall, Hautausschlag","Wassereinlagerungen (Ödeme)","Wadenkrämpfe","Überempfindlichkeitsreaktionen, gesteigerte Libido"],"unbekannt":["Impulskontrollstörungen (Spielsucht, Kaufsucht, gesteigerter Sexualtrieb, Essattacken)","Plötzliches Einschlafen im Alltag","Halluzinationen, Wahnvorstellungen, psychotische Störungen, Aggression","Angina pectoris","Zittern (Tremor), Sehstörungen","Erhöhte Leberwerte und CK"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Kinderwunsch Cabergolin vorsorglich etwa einen Monat vor der geplanten Empfängnis absetzen; tritt unter der Behandlung eine Schwangerschaft ein, ärztlich über das Absetzen entscheiden. Die bisherigen Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Cabergolin unterdrückt die Milchbildung. Frauen, die stillen möchten, dürfen es nicht einnehmen; bei Behandlung einer Hyperprolaktinämie nicht stillen.","hinweise":["Mit einer Mahlzeit einnehmen – das vermindert Übelkeit und Schwindel.","Bei Langzeitbehandlung vor Beginn und regelmässig einen Herzultraschall machen lassen; Atemnot, anhaltenden Husten, Brust- oder Flankenschmerzen und Beinödeme ärztlich abklären.","Kann Schläfrigkeit, plötzliches Einschlafen und Blutdruckabfall verursachen – Vorsicht beim Autofahren, besonders in den ersten Tagen.","Auf Spielsucht, Kaufsucht, gesteigerten Sexualtrieb oder Essattacken achten und Angehörige darüber informieren."],"darreichung":["Tabletten"]},"cabotegravir":{"wirkmechanismus":"Verhindert, dass das HI-Virus sein Erbgut in die menschlichen Zellen einbauen kann. Cabotegravir hemmt den Strangtransfer der HIV-Integrase und blockiert so die Integration der viralen DNA in das Erbgut der Wirtszelle. Als Depotspritze in den Gesässmuskel wird der Wirkstoff über Wochen langsam freigesetzt; Restmengen sind noch 12 Monate und länger nach der letzten Injektion nachweisbar. Abgebaut wird Cabotegravir vor allem über UGT1A1.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Einstichstelle (Schmerzen, Unbehagen, Knötchen, Verhärtung)","Kopfschmerzen","Fieber, Hitzegefühl, Schüttelfrost, grippeähnliche Beschwerden"],"haeufig":["Depression, Angst, abnorme Träume, Schlaflosigkeit","Schwindel","Übelkeit, Erbrechen, Bauchschmerzen, Blähungen, Durchfall","Hautausschlag","Muskelschmerzen","Müdigkeit, Schwäche, Unwohlsein","Weitere Reaktionen an der Einstichstelle (Schwellung, Rötung, Juckreiz, Bluterguss, Wärmegefühl)","Gewichtszunahme"],"gelegentlich":["Suizidgedanken, Suizidversuch (v. a. bei psychischer Vorerkrankung)","Lebertoxizität, Anstieg der Leberwerte","Schläfrigkeit, vasovagale Reaktionen (Kreislaufreaktion bis Ohnmacht bei der Injektion)","Abszess oder Entzündung an der Einstichstelle","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Begrenzte Erfahrungen; Anwendung nur, wenn der erwartete Nutzen das mögliche Risiko rechtfertigt. Zu beachten ist, dass Cabotegravir nach der letzten Injektion noch 12 Monate und länger im Körper verbleibt.","stillzeit":"Gemäss Fachinformation soll nicht gestillt werden (Übertragungsrisiko von HIV; Cabotegravir kann noch lange nach der letzten Injektion in die Muttermilch übergehen). Ein Stillwunsch ist mit dem behandelnden HIV-Zentrum zu besprechen.","hinweise":["Die Depotspritze wird von Fachpersonen in den Gesässmuskel gegeben (monatlich oder alle 2 Monate) – Termine unbedingt einhalten und bei geplanter Abwesenheit frühzeitig eine Überbrückung mit Tabletten besprechen.","Nach dem Absetzen spätestens zum nächsten vorgesehenen Injektionstermin eine vollständige andere HIV-Therapie beginnen.","Die Tabletten der Einleitungsphase zusammen mit den Rilpivirin-Tabletten zu einer Mahlzeit einnehmen (Rilpivirin braucht eine Mahlzeit)."],"darreichung":["Filmtabletten","Depot-Injektionssuspension"]},"cabozantinib":{"wirkmechanismus":"Hemmt das Wachstum von Krebszellen und die Bildung neuer Blutgefässe im Tumor. Cabozantinib blockiert mehrere Rezeptor-Tyrosinkinasen, vor allem MET, VEGFR-2, AXL und RET, daneben ROS1, KIT, FLT3 und TIE-2. Die gleichzeitige Hemmung von MET und AXL wirkt Resistenzmechanismen entgegen, die bei einer reinen VEGF-Hemmung auftreten können.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen, Verstopfung, Bauchschmerzen","Stomatitis (Entzündung der Mundschleimhaut), Geschmacksstörungen, Appetitverlust, Gewichtsabnahme","Hand-Fuss-Syndrom, Hautausschlag","Bluthochdruck","Müdigkeit, Ödeme, Muskelkrämpfe, Gelenkschmerzen, Heiserkeit","Hypothyreose (Schilddrüsenunterfunktion)","Blutarmut, Mangel an Blutplättchen und weissen Blutkörperchen","Tiefes Magnesium, Kalium, Calcium und Phosphat; erhöhte Leberwerte"],"haeufig":["Venöse Thrombosen, Lungenembolie","Blutungen","Flüssigkeitsmangel","Periphere Neuropathie (Kribbeln, Taubheit), Tinnitus (Ohrgeräusche)","Eiweiss im Urin (Proteinurie)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Haarausfall, trockene Haut, Juckreiz, Aufhellung der Haare","Abszesse"],"gelegentlich":["Magen-Darm-Durchbruch (Perforation), Fisteln","Kiefernekrose (Absterben von Kieferknochen)","Krampfanfälle","Cholestatische Hepatitis (Leberentzündung mit Gallenstau)"],"unbekannt":["QT-Verlängerung","Arterielle Thromboembolien (z. B. Herzinfarkt, Schlaganfall)","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Aneurysmen und Gefässwandeinrisse (Dissektionen)","Hautvaskulitis (Entzündung kleiner Hautgefässe)"]},"schwangerschaft":"Nicht anwenden, ausser der Zustand erfordert es zwingend – kann das ungeborene Kind schädigen. Frauen und Partnerinnen behandelter Männer müssen während der Behandlung und mindestens 4 Monate danach zuverlässig verhüten (hormonale Verhütung zusätzlich mit Barrieremethode).","stillzeit":"Während der Behandlung und mindestens 4 Monate danach nicht stillen.","hinweise":["Nüchtern einnehmen: mindestens 2 Stunden nach und 1 Stunde vor dem Essen, mit einem Glas Wasser, nicht zerkleinern.","Cabometyx-Tabletten und Cometriq-Kapseln sind nicht gegeneinander austauschbar (unterschiedliche Aufnahme).","Keine Grapefruit, kein Johanniskraut.","Vor Operationen und Zahnbehandlungen nach ärztlicher Anweisung pausieren (Wundheilung, Kiefernekrose); Blutdruck regelmässig messen."],"darreichung":["Filmtabletten","Hartkapseln"]},"calcifediol":{"wirkmechanismus":"Liefert direkt die Speicherform von Vitamin D, sodass der Vitamin-D-Spiegel rascher und verlässlicher ansteigt. Calcifediol ist 25-Hydroxy-Vitamin-D3, das sonst erst in der Leber aus Colecalciferol gebildet wird. In der Niere und anderen Geweben wird es durch die 1-alpha-Hydroxylase (CYP27B1) zum aktiven Hormon Calcitriol umgewandelt. Calcitriol fördert die Aufnahme von Calcium und Phosphat aus dem Darm, unterstützt die Mineralisierung der Knochen und bremst die Ausschüttung von Parathormon. Die Retardform gibt den Wirkstoff langsam ab und vermeidet starke Spiegelspitzen.","nebenwirkungen":{"unbekannt":["Hyperkalzämie (erhöhtes Calcium) mit Übelkeit, Erbrechen, Verstopfung, Durst, vermehrtem Wasserlassen und Müdigkeit","Hyperkalziurie (vermehrt Calcium im Urin), Nierensteine, Nierenverkalkung","Hyperphosphatämie (erhöhtes Phosphat)","Herzrhythmusstörungen bei stark erhöhtem Calcium","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; eine Überdosierung mit erhöhtem Calcium kann dem Kind schaden.","stillzeit":"Geht in die Muttermilch über; nur nach ärztlicher Abwägung und ohne zusätzliche Vitamin-D-Gabe an das Kind ohne Rücksprache.","hinweise":["Calcium-, Phosphat- und Vitamin-D-Werte regelmässig kontrollieren lassen.","Keine weiteren Vitamin-D-Präparate ohne ärztliche Rücksprache einnehmen.","Retardkapseln unzerkaut schlucken.","Anhaltende Übelkeit, starker Durst, vermehrtes Wasserlassen oder Verstopfung ärztlich abklären lassen (Zeichen erhöhter Calciumwerte)."],"darreichung":["Retardkapseln"]},"calcipotriol":{"wirkmechanismus":"Bremst das zu schnelle Wachstum der Hautzellen bei Schuppenflechte und normalisiert ihre Reifung. Calcipotriol ist ein synthetischer Abkömmling des aktiven Vitamin D3 (Calcitriol) und bindet an den Vitamin-D-Rezeptor der Hornzellen (Keratinozyten). Dadurch hemmt es deren Vermehrung, fördert eine normale Verhornung und dämpft entzündliche Signale. Seine Wirkung auf den Calciumhaushalt ist etwa 100-mal schwächer als die von Calcitriol; bei zu grossen Mengen kann der Calciumspiegel im Blut trotzdem steigen.","nebenwirkungen":{"haeufig":["Juckreiz","Hautreizung, Brennen, Stechen oder Schmerzen der Haut","Rötung, trockene Haut, Hautausschlag"],"gelegentlich":["Ekzem, Hautentzündung (Dermatitis)","Verschlechterung der Psoriasis"],"selten":["Hyperkalzämie (erhöhter Calciumspiegel im Blut) und vermehrte Calciumausscheidung im Urin"],"unbekannt":["Überempfindlichkeitsreaktionen wie Nesselsucht, Angioödem, Schwellung um die Augen oder im Gesicht","Lichtempfindlichkeit der Haut","Hautentzündung im Gesicht oder um den Mund (wenn Salbe dorthin gelangt)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung: Erfahrungen beim Menschen fehlen; in Tierversuchen traten nach hohen Dosen zum Einnehmen schädliche Wirkungen auf.","stillzeit":"Nach ärztlicher Abwägung möglich; nicht im Brustbereich auftragen.","hinweise":["Höchstmenge beachten: Erwachsene höchstens 100 g Salbe pro Woche (bei Kombination mit Lösung entsprechend weniger); bei grossflächiger Anwendung kann der Arzt den Calciumspiegel kontrollieren.","Nach dem Auftragen Hände waschen; nicht ins Gesicht oder in die Augen bringen.","Übermässige Sonne und Solarium während der Behandlung meiden."],"darreichung":["Salbe","Lösung zur Anwendung auf der Kopfhaut"]},"calcipotriol-betamethason":{"wirkmechanismus":"Verbindet zwei Wirkprinzipien gegen Schuppenflechte. Calcipotriol, ein Abkömmling von Vitamin D3, bindet an den Vitamin-D-Rezeptor der Hornzellen, bremst deren übermässige Vermehrung und normalisiert die Verhornung. Betamethasondipropionat ist ein stark wirksames Glukokortikoid (Klasse III), das über den Glukokortikoid-Rezeptor Entzündung, Rötung und Juckreiz unterdrückt. Die Kombination wirkt schneller und stärker als jeder Wirkstoff allein, und das Kortison mildert die Hautreizung durch Calcipotriol.","nebenwirkungen":{"haeufig":["Juckreiz"],"gelegentlich":["Brennen, Reizung oder Schmerzen der Haut","Rötung, Ausschlag, Hautentzündung (Dermatitis)","Verschlechterung der Psoriasis","Hautinfektionen (Bakterien, Pilze, Viren), Haarbalgentzündung (Follikulitis)","Pigmentveränderungen an der Anwendungsstelle"],"selten":["Hautatrophie (Verdünnung der Haut), Dehnungsstreifen (Striae)","Pustulöse Psoriasis","Überempfindlichkeitsreaktionen, Nesselsucht","Rebound-Effekt (Wiederaufflammen nach dem Absetzen)","Hyperkalzämie (erhöhter Calciumspiegel im Blut)"],"unbekannt":["Verschwommenes Sehen","Vorübergehende gelbliche Verfärbung weisser oder grauer Haare (Gel auf der Kopfhaut)","Unterdrückung der Nebennierenrinde bei grossflächiger Anwendung"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung: Daten fehlen, und Kortison wirkte in Tierversuchen fruchtschädigend.","stillzeit":"Nach ärztlicher Abwägung möglich; nicht auf die Brust auftragen.","hinweise":["Höchstmengen beachten: höchstens 15 g pro Tag und 100 g pro Woche, nicht mehr als 30 % der Körperoberfläche.","Nach dem Auftragen Hände waschen; nicht ins Gesicht, in die Augen oder auf Schleimhäute bringen und nicht unter luftdichten Verbänden anwenden.","Der Schaum ist leicht entzündlich: beim Auftragen nicht rauchen und offene Flammen meiden."],"darreichung":["Salbe","Gel","Schaum zur Anwendung auf der Haut"]},"calcitonin":{"wirkmechanismus":"Bremst den Abbau von Knochensubstanz und senkt dadurch das Calcium im Blut. Calcitonin bindet an Calcitonin-Rezeptoren der Osteoklasten (knochenabbauende Zellen) und hemmt deren Aktivität. In der Niere steigert es die Ausscheidung von Calcium, Phosphat und Natrium. Lachs-Calcitonin wirkt beim Menschen stärker und länger als das körpereigene Hormon; zusätzlich ist eine schmerzlindernde Wirkung bei Knochenschmerzen beschrieben.","nebenwirkungen":{"haeufig":["Übelkeit, Durchfall, Bauchschmerzen","Flush (Hitzegefühl und Rötung im Gesicht)","Schwindel, Kopfschmerzen","Geschmacksstörungen","Gelenkschmerzen","Müdigkeit"],"gelegentlich":["Erbrechen","Überempfindlichkeitsreaktionen, Hautausschlag","Sehstörungen","Bluthochdruck","Grippeähnliche Beschwerden, Ödeme (Wassereinlagerungen)","Muskel- und Knochenschmerzen","Vermehrtes Wasserlassen (Polyurie)","Reaktionen an der Einstichstelle"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion bis zum Schock)"],"unbekannt":["Hypokalzämie (zu tiefes Calcium) mit Kribbeln oder Muskelkrämpfen","Zittern (Tremor)"]},"schwangerschaft":"Nicht empfohlen: Es fehlen Erfahrungen beim Menschen; im Tierversuch vermindertes Geburtsgewicht.","stillzeit":"Nicht empfohlen: Im Tierversuch geht Calcitonin in die Milch über und hemmt die Milchbildung.","hinweise":["Nur kurzfristig anwenden (bei Ruhigstellung in der Regel 2, höchstens 4 Wochen), da bei längerer Anwendung das Krebsrisiko leicht steigt.","Kribbeln um den Mund, Muskelzuckungen oder -krämpfe (Zeichen eines Calciummangels) sofort ärztlich melden.","Bei Morbus Paget regelmässige Laborkontrollen (Calcium, alkalische Phosphatase)."],"darreichung":["Injektionslösung"]},"calcitriol":{"wirkmechanismus":"Ist die fertige, aktive Form von Vitamin D und muss – anders als gewöhnliches Vitamin D – nicht erst in Leber und Niere umgewandelt werden. Calcitriol (1,25-Dihydroxycholecalciferol) bindet an den Vitamin-D-Rezeptor und steigert dadurch die Aufnahme von Calcium und Phosphat aus dem Darm, die Rückresorption von Calcium in der Niere und die Mineralisierung des Knochens; zudem hemmt es die Bildung von Parathormon. Deshalb wirkt es auch, wenn die kranke Niere selbst kein aktives Vitamin D mehr bilden kann. Auf der Haut hemmt es die übermässige Vermehrung der Hornzellen (Keratinozyten) und fördert deren normale Ausreifung.","nebenwirkungen":{"sehrHaeufig":["Hyperkalzämie (erhöhtes Calcium im Blut) bei Einnahme der Kapseln"],"haeufig":["Kopfschmerzen","Bauchschmerzen, Übelkeit","Hautausschlag","Harnwegsinfekte","Salbe: Hautreizung, Rötung und Juckreiz an der behandelten Stelle"],"gelegentlich":["Appetitlosigkeit, Erbrechen","Anstieg des Kreatinins im Blut"],"unbekannt":["Zeichen einer Hyperkalzämie: Durst, vermehrtes Wasserlassen, Verstopfung, Muskelschwäche, Teilnahmslosigkeit","Kalkablagerungen in Geweben (Calcinose) und Nierensteine bei anhaltender Hyperkalzämie","Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht)","Wachstumsverzögerung bei Kindern mit anhaltender Hyperkalzämie"]},"schwangerschaft":"Nur bei klarer Notwendigkeit und unter Kontrolle des Calciums, da eine Hyperkalzämie der Mutter dem Kind schaden kann; die Salbe nur nach ärztlicher Abwägung und kleinflächig.","stillzeit":"Calcitriol geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung mit Kontrolle des Calciums bei Mutter und Kind.","hinweise":["Blutkontrollen (Calcium, Phosphat, Kreatinin) zuverlässig wahrnehmen, besonders zu Beginn und nach Dosisänderungen.","Keine weiteren Vitamin-D- oder Calciumpräparate ohne ärztliche Absprache einnehmen; ausreichend trinken.","Warnzeichen zu hohen Calciums (starker Durst, viel Wasserlassen, Übelkeit, Verstopfung, Muskelschwäche, Verwirrtheit) ärztlich melden.","Salbe dünn auftragen und danach die Hände waschen."],"darreichung":["Weichkapseln","Salbe"]},"calcium":{"wirkmechanismus":"Ersetzt Calcium, das für Knochen und Zähne sowie für Muskeln, Nerven, Herz und Blutgerinnung unentbehrlich ist. Rund 99 % des Körpercalciums sind im Knochen gespeichert; eine ausreichende Zufuhr bremst den Knochenabbau, besonders zusammen mit Vitamin D, das die Aufnahme im Darm steigert. Calciumcarbonat braucht für die Aufnahme Magensäure und wird zu den Mahlzeiten besser aufgenommen, Calciumcitrat unabhängig davon. Intravenös gegebenes Calcium hebt einen gefährlich tiefen Calciumspiegel innert Minuten an.","nebenwirkungen":{"gelegentlich":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperkalziurie (erhöhtes Calcium im Urin)"],"selten":["Verstopfung, Blähungen, Übelkeit, Bauchschmerzen, Durchfall"],"sehrSelten":["Juckreiz, Hautausschlag, Nesselsucht","Milch-Alkali-Syndrom (Hyperkalzämie, Alkalose, Nierenfunktionsstörung), meist nur bei Überdosierung"],"unbekannt":["Injektion: Wärmegefühl, Hitzewallung, Blutdruckabfall, langsamer Puls oder Rhythmusstörungen bei zu rascher Gabe","Injektion: Reizung oder Gewebeschäden an der Einstichstelle"]},"schwangerschaft":"In üblichen Dosen erlaubt, der Bedarf ist erhöht; hohe Dosen und eine Hyperkalzämie vermeiden.","stillzeit":"Erlaubt; Calcium geht in die Muttermilch über.","hinweise":["Calciumcarbonat am besten zu den Mahlzeiten einnehmen; Kautabletten kauen oder lutschen, Brausetabletten in Wasser auflösen.","Abstand zu Antibiotika (Tetracycline, Chinolone), Schilddrüsenhormonen, Bisphosphonaten und Eisen einhalten.","Lebensmittel mit viel Oxalsäure (Spinat, Rhabarber) oder Phytinsäure (Vollkorn) vermindern die Calciumaufnahme."],"darreichung":["Kautabletten","Brausetabletten","Lutschtabletten","Injektionslösung (Calciumgluconat)"]},"calcium-colecalciferol":{"wirkmechanismus":"Liefert gleichzeitig Calcium und Vitamin D3, die der Knochen für seine Festigkeit braucht. Vitamin D3 wird in Leber und Niere zu Calcitriol aktiviert und steigert die Aufnahme von Calcium im Darm; das Calcium wird in den Knochen eingebaut. Gemeinsam gleichen sie einen Mangel aus und senken das Parathormon, das bei Mangel den Knochenabbau antreibt (sekundärer Hyperparathyreoidismus). So wird der altersbedingte Knochenabbau gebremst.","nebenwirkungen":{"gelegentlich":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperkalziurie (erhöhtes Calcium im Urin)"],"selten":["Verstopfung, Blähungen, Übelkeit, Bauchschmerzen, Durchfall"],"sehrSelten":["Juckreiz, Hautausschlag, Nesselsucht","Milch-Alkali-Syndrom (Hyperkalzämie, Alkalose, Nierenfunktionsstörung), meist nur bei Überdosierung"],"unbekannt":["Überempfindlichkeitsreaktionen wie Angioödem oder Kehlkopfschwellung"]},"schwangerschaft":"Bei Bedarf in üblichen Dosen erlaubt; in der Schwangerschaft insgesamt nicht mehr als 2500 mg Calcium und 4000 I. E. Vitamin D pro Tag aufnehmen.","stillzeit":"Erlaubt; Calcium und Vitamin D gehen in die Muttermilch über – bei zusätzlicher Vitamin-D-Gabe an den Säugling berücksichtigen.","hinweise":["Kautabletten kauen oder lutschen, am besten nach einer Mahlzeit.","Abstand zu Tetracyclinen, Chinolonen, Schilddrüsenhormonen, Bisphosphonaten und Eisen einhalten.","Keine weiteren Calcium- oder Vitamin-D-Präparate ohne ärztliche Absprache einnehmen."],"darreichung":["Kautabletten","Lutschtabletten","Brausetabletten"]},"calciumcarbonat-magnesiumcarbonat":{"wirkmechanismus":"Neutralisiert überschüssige Magensäure und lindert Sodbrennen innert Minuten. Calciumcarbonat und Magnesiumcarbonat reagieren mit der Salzsäure im Magen zu Calcium- bzw. Magnesiumchlorid, Wasser und Kohlendioxid und heben so den pH-Wert des Mageninhalts an. Magnesium wirkt leicht abführend, Calcium eher verstopfend. Ein Teil des Calciums und Magnesiums wird ins Blut aufgenommen und über die Nieren ausgeschieden.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen (Hautausschlag, Nesselsucht, Juckreiz, Anaphylaxie)","Übelkeit, Erbrechen, Magenbeschwerden","Durchfall oder Verstopfung","Hyperkalzämie und Alkalose bei langer, hochdosierter Einnahme (Milch-Alkali-Syndrom)","Hypermagnesiämie (erhöhtes Magnesium im Blut), v. a. bei Niereninsuffizienz","Muskelschwäche als Zeichen eines erhöhten Calcium- oder Magnesiumspiegels"]},"schwangerschaft":"Kann in der Schwangerschaft in der empfohlenen Dosis kurzfristig angewendet werden; eine übermässige Calciumzufuhr (zusätzlich viel Milch oder Calciumpräparate) vermeiden.","stillzeit":"In der empfohlenen Dosierung möglich.","hinweise":["Tabletten bei Bedarf lutschen oder kauen; Tageshöchstdosis gemäss Packungsbeilage nicht überschreiten.","Zu anderen Arzneimitteln 2 Stunden Abstand halten, zu Chinolon-Antibiotika mindestens 4 Stunden.","Ohne ärztlichen Rat nicht länger als 2 Wochen einnehmen."],"darreichung":["Kau- und Lutschtabletten"]},"calciumdobesilat":{"wirkmechanismus":"Stärkt die Wände kleiner Blutgefässe und vermindert Schwellungen. Calciumdobesilat senkt die erhöhte Durchlässigkeit der Kapillaren, verbessert die Fliesseigenschaften des Blutes (geringere Viskosität und Plättchenzusammenlagerung) und wirkt antioxidativ. Dadurch tritt weniger Flüssigkeit ins Gewebe aus.","nebenwirkungen":{"sehrSelten":["Agranulozytose (starker Mangel an weissen Blutkörperchen) mit Fieber und Infektionen"],"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Durchfall)","Hautreaktionen (Ausschlag, Juckreiz)","Fieber, Schüttelfrost","Gelenkschmerzen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur bei klarer Notwendigkeit nach ärztlicher Abwägung.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über; nur nach ärztlicher Abwägung.","hinweise":["Bei Fieber, Halsschmerzen, Mundschleimhautentzündung oder anderen Infektzeichen sofort ärztlich melden und das Blutbild kontrollieren lassen.","Während der Mahlzeiten einnehmen.","Vor Blutuntersuchungen die Einnahme angeben (kann die Kreatininmessung verfälschen)."],"darreichung":["Kapseln"]},"canagliflozin":{"wirkmechanismus":"Senkt den Blutzucker, indem die Nieren mehr Zucker mit dem Urin ausscheiden. Canagliflozin hemmt den Natrium-Glucose-Cotransporter 2 (SGLT2) im proximalen Nierentubulus, der normalerweise den grössten Teil der gefilterten Glucose zurück ins Blut holt. Die Wirkung ist unabhängig vom Insulin; zusätzlich gehen Kalorien sowie etwas Salz und Wasser verloren, was Gewicht und Blutdruck leicht senkt. Bei eingeschränkter Nierenfunktion lässt die blutzuckersenkende Wirkung nach.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) in Kombination mit Insulin oder Sulfonylharnstoffen","Pilzinfektion der Scheide"],"haeufig":["Pilzinfektion oder Entzündung der Eichel (Balanitis)","Harnwegsinfekte","Vermehrtes Wasserlassen","Durst","Obstipation (Verstopfung), Übelkeit","Veränderte Blutfettwerte, erhöhter Hämatokrit"],"gelegentlich":["Flüssigkeitsmangel mit Schwindel beim Aufstehen, tiefem Blutdruck oder Ohnmacht","Hautausschlag, Nesselsucht","Knochenbrüche","Akutes Nierenversagen","Amputationen der unteren Gliedmassen (vor allem Zehen)"],"selten":["Diabetische Ketoazidose","Anaphylaxie, Angioödem"],"unbekannt":["Fournier-Gangrän (nekrotisierende Fasziitis im Genital- und Dammbereich)"]},"schwangerschaft":"Nicht anwenden; im Tierversuch wurden die sich entwickelnden Nieren geschädigt (entspricht dem 2. und 3. Schwangerschaftsdrittel). In der Schwangerschaft wird Insulin verwendet.","stillzeit":"Nicht anwenden.","hinweise":["Auf gute Intimhygiene achten; bei Juckreiz, Ausfluss oder Rötung im Genitalbereich ärztlichen Rat einholen.","Vor grösseren Operationen und bei akuten Erkrankungen mit Erbrechen, Durchfall oder Fasten nach ärztlicher Anweisung pausieren.","Bei Übelkeit, Erbrechen, Bauchschmerzen, starkem Durst oder Atemnot sofort ärztlich abklären lassen – eine Ketoazidose ist auch bei normalem Blutzucker möglich.","Füsse täglich kontrollieren; Wunden oder Druckstellen früh behandeln lassen."],"darreichung":["Filmtabletten"]},"canakinumab":{"wirkmechanismus":"Hemmt einen Botenstoff, der bei diesen Krankheiten übermässig gebildet wird und Fieber und Entzündung auslöst. Canakinumab ist ein humaner monoklonaler Antikörper (IgG1/κ), der Interleukin-1-beta mit hoher Affinität bindet und dessen Andocken an den Interleukin-1-Rezeptor verhindert. Dadurch sinken auch nachgeschaltete Entzündungsmediatoren wie Interleukin-6, CRP und Serum-Amyloid A. Wegen der langen Halbwertszeit (etwa 26 Tage) genügen Injektionen im Abstand von 4–8 Wochen bzw. bei Gicht eine Einzeldosis.","nebenwirkungen":{"sehrHaeufig":["Atemwegsinfekte (z. B. Erkältung, Halsentzündung, Bronchitis, Lungenentzündung)","Weitere Infektionen (Magen-Darm-, Harnwegs-, Ohren- und Hautinfektionen)","Oberbauchschmerzen","Reaktionen an der Einstichstelle","Gelenkschmerzen (Arthralgie)","Verminderte Nierenfunktion (Kreatinin-Clearance) und Eiweiss im Urin, meist vorübergehend"],"haeufig":["Schwindel","Rücken- und Muskelschmerzen","Müdigkeit, Schwäche","Vaginale Pilzinfektion","Leukopenie und Neutropenie (Mangel an weissen Blutkörperchen)"],"gelegentlich":["Reflux (Sodbrennen)","Verminderung der Blutplättchen"],"unbekannt":["DRESS (schwere Arzneimittelreaktion mit Ausschlag, Fieber und Organbeteiligung), vor allem bei Morbus Still"]},"schwangerschaft":"Erfahrungen begrenzt; nur anwenden, wenn eindeutig nötig. Frauen sollen während und bis 3 Monate nach der letzten Dosis verhüten; im Mutterleib exponierte Säuglinge sollen 16 Wochen lang keine Lebendimpfstoffe erhalten.","stillzeit":"Übergang in die Muttermilch nicht bekannt; nur nach ärztlicher Nutzen-Risiko-Abwägung.","hinweise":["Vor Behandlungsbeginn Tuberkulose-Test und Impfstatus prüfen; keine Lebendimpfungen während der Behandlung.","Bei Fieber, anhaltendem Husten oder anderen Infektzeichen sofort ärztlich abklären lassen.","Kann Schwindel verursachen – bis zum Abklingen nicht Auto fahren oder Maschinen bedienen."],"darreichung":["Injektionslösung (unter die Haut)"]},"candesartan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des gefässverengenden Hormons Angiotensin II an seinem Rezeptor blockiert. Candesartancilexetil wird bei der Aufnahme im Darm vollständig zu Candesartan aktiviert, das sehr fest und lang anhaltend an den AT1-Rezeptor bindet. Dadurch weiten sich die Gefässe, die Aldosteronausschüttung sinkt und die Niere scheidet mehr Salz und Wasser aus, was Herz und Gefässe entlastet. Candesartan wird kaum verstoffwechselt und über Niere und Galle ausgeschieden; Reizhusten ist selten, da der Bradykinin-Abbau nicht beeinflusst wird.","nebenwirkungen":{"haeufig":["Atemwegsinfektionen","Schwindel, Drehschwindel","Kopfschmerzen","Hypotonie (tiefer Blutdruck) – vor allem bei Herzschwäche","Hyperkaliämie (erhöhtes Kalium) – vor allem bei Herzschwäche","Nierenfunktionsstörung, Kreatininanstieg – vor allem bei Herzschwäche"],"sehrSelten":["Leukopenie, Neutropenie, Agranulozytose (Mangel an weissen Blutkörperchen)","Hyponatriämie (Natriummangel)","Husten","Übelkeit","Erhöhte Leberwerte, Hepatitis","Angioödem (Schwellung von Gesicht, Lippen, Zunge, Rachen), Hautausschlag, Nesselsucht, Juckreiz","Rücken-, Gelenk- und Muskelschmerzen","Nierenversagen bei empfindlichen Patienten"],"unbekannt":["Durchfall"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten zum Übergang in die Muttermilch fehlen; besser untersuchte Alternativen wählen.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Zu Beginn kann Schwindel auftreten – Vorsicht beim Autofahren.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Tabletten"]},"cangrelor":{"wirkmechanismus":"Verhindert, dass sich Blutplättchen während eines Eingriffs an den Herzkranzgefässen zusammenlagern und Gerinnsel bilden. Cangrelor blockiert direkt und umkehrbar den P2Y12-Rezeptor für ADP auf den Blutplättchen. Die Wirkung setzt innerhalb von Minuten ein und klingt nach Ende der Infusion wegen der sehr kurzen Halbwertszeit (wenige Minuten) innerhalb von etwa einer Stunde ab. Anders als Clopidogrel und Prasugrel muss es nicht erst in der Leber aktiviert werden.","nebenwirkungen":{"haeufig":["Leichte bis mässige Blutungen","Blutergüsse und Nachblutungen an der Punktionsstelle","Dyspnoe (Atemnot)"],"gelegentlich":["Anämie (Blutarmut)","Nasenbluten","Magen-Darm-Blutungen","Blut im Urin","Hautausschlag, Juckreiz"],"selten":["Hirnblutung","Herzbeuteltamponade","Überempfindlichkeitsreaktionen bis Anaphylaxie"]},"schwangerschaft":"Keine Daten; vorsichtshalber nicht anwenden.","stillzeit":"Unbekannt, ob Cangrelor in die Muttermilch übergeht; ein Risiko für den Säugling kann nicht ausgeschlossen werden.","hinweise":["Wird nur im Spital während des Eingriffs gegeben; danach folgt ein Blutplättchenhemmer zum Einnehmen, der nicht eigenmächtig abgesetzt werden darf.","Die Wirkung klingt rund eine Stunde nach Infusionsende ab."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Injektions- bzw. Infusionslösung"]},"cannabidiol":{"wirkmechanismus":"Dämpft die Erregbarkeit von Nervenzellen; der genaue Mechanismus ist nicht vollständig geklärt. Cannabidiol wirkt kaum an den Cannabinoid-Rezeptoren CB1 und verursacht daher keinen Rausch. Diskutiert werden eine Hemmung des Rezeptors GPR55, eine Beeinflussung des Ionenkanals TRPV1 und eine Hemmung der Adenosin-Wiederaufnahme, was die Erregbarkeit von Nervenzellen senkt.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit","Verminderter Appetit","Durchfall","Erbrechen","Fieber","Müdigkeit"],"haeufig":["Lungenentzündung, Bronchitis und andere Infekte","Gewichtsverlust","Reizbarkeit, Aggressivität, Verhaltensauffälligkeiten, Unruhe","Lethargie (Antriebslosigkeit), Krampfanfälle","Husten","Übelkeit","Erhöhte Leberwerte (Transaminasen, Gamma-GT)","Hautausschlag"],"unbekannt":["Suizidgedanken","Ernsthafte Leberschädigung"]},"schwangerschaft":"Vorsichtshalber nicht anwenden, ausser der Nutzen überwiegt das Risiko klar.","stillzeit":"Keine ausreichenden Daten; während der Behandlung vorsichtshalber nicht stillen.","hinweise":["Immer gleich zum Essen einnehmen (stets mit oder stets ohne Mahlzeit): fettreiches Essen erhöht die Aufnahme stark.","Leberwerte werden vor Beginn und in den ersten Monaten regelmässig kontrolliert; bei Übelkeit, Bauchschmerzen, dunklem Urin oder Gelbsucht ärztlich abklären.","Enthält Alkohol (Ethanol) und Sesamöl.","Nicht durch frei verkäufliche CBD-Produkte ersetzen; nicht abrupt absetzen."],"darreichung":["Lösung zum Einnehmen"]},"capecitabin":{"wirkmechanismus":"Wird erst im Körper, bevorzugt im Tumorgewebe, in den eigentlichen Wirkstoff Fluorouracil (5-FU) umgewandelt. Die Aktivierung erfolgt in drei Schritten über Carboxylesterase und Cytidin-Deaminase (Leber) sowie Thymidin-Phosphorylase, die in vielen Tumoren vermehrt vorkommt. Fluorouracil hemmt die Thymidylat-Synthase und damit die DNA-Synthese und wird fehlerhaft in die RNA eingebaut. Der Abbau erfolgt über das Enzym DPD; bei DPD-Mangel drohen schwere Vergiftungen.","nebenwirkungen":{"sehrHaeufig":["Hand-Fuss-Syndrom (Rötung, Schwellung, Schmerzen an Handflächen und Fusssohlen)","Durchfall","Übelkeit, Erbrechen","Mundschleimhautentzündung (Stomatitis)","Bauchschmerzen","Appetitlosigkeit","Müdigkeit, Schwäche"],"haeufig":["Neutropenie, Anämie","Infektionen (z. B. Herpes)","Flüssigkeitsmangel, Gewichtsverlust","Kopfschmerzen, Schwindel, Geschmacksstörung, Kribbeln","Tränende, gereizte Augen, Bindehautentzündung","Erhöhtes Bilirubin, veränderte Leberwerte","Hautausschlag, Haarausfall, Hautverfärbung","Fieber, Wassereinlagerungen, Brustschmerzen"],"gelegentlich":["Thrombozytopenie, Fieber bei Neutropenie","Angina pectoris, Herzinfarkt, Herzrhythmusstörungen","Thrombosen und Lungenembolie","Magen-Darm-Blutungen, Darmverschluss","Lichtempfindlichkeit, Nesselsucht","Periphere Neuropathie (Nervenschäden)","Überempfindlichkeitsreaktionen"],"selten":["QT-Verlängerung, Kammerflimmern, Torsade de pointes","Verengung der Tränenwege, Hornhautentzündung","Leberversagen, cholestatische Hepatitis","Angioödem","Kutaner Lupus erythematodes"],"sehrSelten":["Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse"],"unbekannt":["Toxische Leukenzephalopathie (Schädigung der weissen Hirnsubstanz)","Akutes Nierenversagen bei Flüssigkeitsmangel"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend). Frauen müssen während und bis 6 Monate nach der letzten Dosis zuverlässig verhüten, Männer mit Partnerin im gebärfähigen Alter bis 3 Monate danach.","stillzeit":"Kontraindiziert; während und bis 2 Wochen nach der letzten Dosis nicht stillen.","hinweise":["Tabletten innerhalb von 30 Minuten nach einer Mahlzeit mit Wasser unzerkaut schlucken.","Vor Behandlungsbeginn wird auf einen DPD-Mangel getestet.","Bei Durchfall (mehr als 4 zusätzliche Stühle pro Tag), Erbrechen, Mundgeschwüren, Fieber oder schmerzhaften Händen und Füssen Einnahme unterbrechen und sofort ärztlich melden.","Kein Brivudin (Gürtelrosemittel) während der Behandlung sowie in den 4 Wochen davor und danach; bei Blutverdünnern INR engmaschig kontrollieren."],"darreichung":["Filmtabletten"]},"capivasertib":{"wirkmechanismus":"Unterbricht einen Signalweg, der bei vielen Brustkrebsformen das Wachstum antreibt. Capivasertib hemmt alle drei Formen der Serin-/Threonin-Kinase AKT (AKT1, AKT2, AKT3), ein zentrales Glied im PI3K/AKT-Signalweg. Tumoren mit Veränderungen in PIK3CA, AKT1 oder PTEN sind besonders von diesem Weg abhängig. Die Kombination mit dem Antiöstrogen Fulvestrant wirkt einer Resistenz gegen die Hormontherapie entgegen.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Hautausschlag (oft fleckig-knotig), Juckreiz","Hyperglykämie (erhöhter Blutzucker)","Übelkeit, Erbrechen, Appetitverlust","Stomatitis (Entzündung der Mundschleimhaut)","Müdigkeit","Harnwegsinfekte","Blutarmut"],"haeufig":["Trockene Haut","Geschmacksstörungen","Verdauungsbeschwerden"],"gelegentlich":["Diabetische Ketoazidose (lebensbedrohliche Stoffwechselentgleisung)"],"unbekannt":["Erythema multiforme (Hautentzündung mit kokardenartigen Flecken)","Arzneimittelreaktion mit Eosinophilie und systemischen Symptomen (DRESS)"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nicht empfohlen. Frauen müssen während der Behandlung und mindestens 4 Wochen danach, Männer mit Partnerin im gebärfähigen Alter mindestens 16 Wochen danach zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Zweimal täglich (etwa alle 12 Stunden) an 4 aufeinanderfolgenden Tagen, dann 3 Tage Pause; mit oder ohne Mahlzeit, Tabletten unzerkaut.","Blutzucker wird vor und regelmässig während der Behandlung kontrolliert; starken Durst, häufiges Wasserlösen oder Verwirrtheit melden.","Bei Durchfall früh ein Durchfallmittel nehmen und viel trinken; Hautausschläge melden.","Keine Grapefruit, kein Johanniskraut."],"darreichung":["Filmtabletten"]},"caplacizumab":{"wirkmechanismus":"Verhindert, dass sich Blutplättchen am von-Willebrand-Faktor anheften und in kleinen Gefässen Gerinnsel bilden. Caplacizumab ist ein bivalentes humanisiertes Nanobody (kleines Antikörperfragment), das an die A1-Domäne des von-Willebrand-Faktors bindet und dessen Wechselwirkung mit dem Glykoprotein-Ib-IX-V-Rezeptor der Thrombozyten blockiert. Bei der erworbenen TTP werden wegen Autoantikörpern gegen das Enzym ADAMTS13 übergrosse von-Willebrand-Faktor-Multimere nicht mehr gespalten; Caplacizumab unterbricht die dadurch ausgelöste Gerinnselbildung, behandelt aber nicht die Autoimmunursache – deshalb braucht es zusätzlich eine Immunsuppression.","nebenwirkungen":{"sehrHaeufig":["Nasenbluten","Zahnfleischbluten","Kopfschmerzen","Müdigkeit","Fieber"],"haeufig":["Andere Blutungen, z. B. Magen-Darm-Blutungen, Blut im Urin, verstärkte Regelblutung","Blutergüsse und blaue Flecken","Nesselsucht (Urtikaria)","Muskelschmerzen","Atemnot (Dyspnoe)","Blutung oder Juckreiz an der Injektionsstelle"],"unbekannt":["Schwere Blutungen, z. B. Hirnblutung"]},"schwangerschaft":"Keine Erfahrungen. Vorsichtshalber während der Schwangerschaft vermeiden; bei Anwendung besteht ein erhöhtes Blutungsrisiko für Mutter und Kind, auch bei der Geburt.","stillzeit":"Unbekannt, ob Caplacizumab in die Muttermilch übergeht; Entscheid zwischen Abstillen und Therapieverzicht nach ärztlicher Abwägung.","hinweise":["Die erste Dosis wird vor dem Plasmaaustausch in die Vene gegeben, danach täglich unter die Haut – auch nach Ende des Plasmaaustauschs noch mindestens 30 Tage.","Nach Schulung kann die tägliche Injektion selbst durchgeführt werden.","Ungewöhnliche oder anhaltende Blutungen sofort melden; vor Operationen und Zahnbehandlungen auf die Behandlung hinweisen."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (Fertigspritze)"]},"capmatinib":{"wirkmechanismus":"Blockiert ein Wachstumssignal, das durch eine bestimmte Genveränderung im Tumor überaktiv ist. Capmatinib hemmt selektiv die Rezeptor-Tyrosinkinase MET. Bei der MET-Exon-14-Skipping-Mutation wird MET in der Zelle nicht mehr normal abgebaut und treibt dauerhaft Zellteilung, Überleben und Ausbreitung der Krebszellen an; Capmatinib unterbricht diese Signale.","nebenwirkungen":{"sehrHaeufig":["Periphere Ödeme (Wassereinlagerungen, v. a. an den Beinen)","Übelkeit, Erbrechen, Durchfall, Verstopfung","Müdigkeit, Schwäche, Fieber","Appetitverlust, Gewichtsabnahme","Atemnot, Husten","Rückenschmerzen","Erhöhte Leberwerte, erhöhtes Kreatinin, erhöhte Lipase und Amylase","Albuminmangel im Blut"],"haeufig":["Interstitielle Lungenerkrankung, Pneumonitis","Cellulitis (Entzündung des Unterhautgewebes)","Juckreiz, Nesselsucht"],"unbekannt":["Akute Pankreatitis","Überempfindlichkeitsreaktionen","Lichtempfindlichkeitsreaktionen der Haut"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nur bei zwingender Notwendigkeit. Frauen und Männer müssen während der Behandlung und mindestens 1 Woche danach zuverlässig verhüten.","stillzeit":"Während der Behandlung und mindestens 1 Woche danach nicht stillen.","hinweise":["Zweimal täglich mit oder ohne Mahlzeit; Tabletten unzerkaut schlucken.","Konsequenter Sonnenschutz (Kleidung, Sonnencreme, Sonnenbrille).","Neue oder verschlimmerte Atemnot oder Husten sofort melden.","Kein Johanniskraut; Theophyllin, Tizanidin oder Digoxin nur unter Kontrolle."],"darreichung":["Filmtabletten"]},"capsaicin":{"wirkmechanismus":"Macht schmerzleitende Nervenfasern in der Haut vorübergehend unempfindlich. Capsaicin, der Scharfstoff der Chilischote, aktiviert den Wärme- und Schmerzrezeptor TRPV1 an den Nervenendigungen. Nach einer anfänglichen brennenden Reizung führt die hohe Konzentration zu einer «Defunktionalisierung» und einem Rückzug der Nervenendigungen in der Haut, sodass die Schmerzweiterleitung über Wochen bis Monate vermindert ist. Die Nervenfasern bilden sich danach wieder nach.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Anwendungsstelle","Hautrötung an der Anwendungsstelle"],"haeufig":["Juckreiz, Knötchen, Bläschen, Schwellung und Trockenheit an der Anwendungsstelle"],"gelegentlich":["Vorübergehender Blutdruckanstieg (durch die Schmerzen)","Herzrasen, Herzklopfen, AV-Block 1. Grades","Husten, Rachenreizung","Augenreizung","Brennen, Taubheitsgefühl, Geschmacksstörungen","Übelkeit","Herpes zoster (Gürtelrose)","Nesselsucht, Muskelkrämpfe, periphere Ödeme"],"unbekannt":["Verbrennungen an der Anwendungsstelle (auch 2. Grades)","Bei versehentlichem Kontakt: Augenschmerzen, Augen- und Rachenreizung, Husten","Vermindertes Empfinden im behandelten Hautbereich"]},"schwangerschaft":"Keine Daten beim Menschen; wegen der sehr geringen und kurzen Aufnahme ins Blut ist ein Risiko unwahrscheinlich. Anwendung nur nach ärztlicher Abwägung.","stillzeit":"Nur nach ärztlicher Abwägung; die Aufnahme ins Blut ist sehr gering und kurzfristig.","hinweise":["Das Pflaster wird von Ärztin, Arzt oder geschultem Fachpersonal mit Nitrilhandschuhen (keine Latexhandschuhe) aufgeklebt und nach 30–60 Minuten entfernt.","Brennen und Schmerzen während und nach der Anwendung lassen sich mit Kühlen und Schmerzmitteln lindern.","Die behandelte Haut kann einige Tage empfindlich auf Wärme reagieren – heisse Duschen, Bäder, direkte Sonne und starke körperliche Anstrengung meiden.","Eine Wiederholung ist frühestens nach 90 Tagen möglich."],"darreichung":["Kutanes Pflaster"]},"captopril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II hemmt. Captopril hemmt direkt, ohne vorherige Umwandlung in der Leber, das Angiotensin-Converting-Enzym (ACE); dadurch sinken Angiotensin II und Aldosteron, die Gefässe erweitern sich und die Niere scheidet mehr Salz und Wasser aus. Weil ACE auch Bradykinin abbaut, steigt dieses an – das erklärt Reizhusten und Angioödeme. Captopril wirkt nur einige Stunden und wird deshalb mehrmals täglich eingenommen.","nebenwirkungen":{"haeufig":["Schlafstörungen","Geschmacksstörungen","Schwindel","Trockener Reizhusten, Atemnot","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall oder Verstopfung","Mundtrockenheit","Juckreiz, Hautausschlag","Haarausfall"],"gelegentlich":["Tachykardie (Herzrasen), Herzklopfen","Angina pectoris (Brustenge)","Hypotonie (tiefer Blutdruck)","Raynaud-Syndrom, Flush, Blässe","Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)","Brustschmerzen, Müdigkeit, Unwohlsein"],"selten":["Appetitlosigkeit","Schläfrigkeit, Kopfschmerzen, Kribbeln","Stomatitis (Mundschleimhautentzündung), Aphthen","Nierenfunktionsstörungen bis Nierenversagen, veränderte Urinmenge"],"sehrSelten":["Neutropenie bis Agranulozytose, Panzytopenie (v. a. bei Nierenschäden)","Anämie, Thrombozytopenie","Hyperkaliämie (erhöhtes Kalium)","Hypoglykämie (Unterzuckerung)","Pankreatitis","Hepatitis, Gallenstau mit Gelbsucht","Stevens-Johnson-Syndrom, Erythema multiforme","Bronchospasmus (Verkrampfung der Atemwege)"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schädigung der kindlichen Nieren, Fruchtwassermangel, Verknöcherungsstörungen des Schädels). Bei Kinderwunsch oder Schwangerschaft auf ein anderes Mittel umstellen.","stillzeit":"Geht in geringer Menge in die Muttermilch über. Bei Frühgeborenen und in den ersten Lebenswochen nicht empfohlen; bei älteren Säuglingen nach ärztlicher Abwägung möglich.","hinweise":["Bei Schwellungen von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notfall aufsuchen (Angioödem).","Trockener Reizhusten ist eine typische Nebenwirkung – ärztlich melden, nicht selbst absetzen.","Kalium, Nierenwerte und Blutbild regelmässig kontrollieren; kaliumhaltige Salzersatzmittel meiden.","Zu Beginn sind Schwindel und Benommenheit möglich – Vorsicht beim Autofahren."],"darreichung":["Tabletten"]},"car-t-zelltherapien":{"wirkmechanismus":"Körpereigene T-Zellen (Abwehrzellen) werden aus dem Blut gewonnen, im Labor so verändert, dass sie Krebszellen erkennen, und als einmalige Infusion zurückgegeben. Die T-Zellen erhalten dabei einen künstlichen, chimären Antigenrezeptor (CAR), der ein Oberflächenmerkmal der Tumorzellen bindet – CD19 bei B-Zell-Lymphomen und B-ALL, BCMA beim multiplen Myelom. Nach der Bindung werden die CAR-T-Zellen aktiviert, vermehren sich im Körper und töten die Zielzellen ab; dabei werden auch gesunde B-Zellen bzw. Plasmazellen zerstört, was zu Antikörpermangel führt.","nebenwirkungen":{"sehrHaeufig":["Zytokin-Freisetzungssyndrom (Fieber, Blutdruckabfall, Atemnot, Herzrasen)","Neurologische Nebenwirkungen (ICANS: Verwirrtheit, Sprach- und Schreibstörungen, Zittern, Krampfanfälle)","Infektionen durch Bakterien, Viren und Pilze","Neutropenie, Anämie, Thrombozytopenie (teils lang anhaltend)","Hypogammaglobulinämie (Antikörpermangel)","Kopfschmerzen","Müdigkeit","Übelkeit, Durchfall"],"haeufig":["Tumorlyse-Syndrom (Stoffwechselentgleisung durch zerfallende Tumorzellen)"],"unbekannt":["Herzrhythmusstörungen und Herzschwäche","Hämophagozytische Lymphohistiozytose (HLH, überschiessende Immunreaktion)","Zweite Krebserkrankungen, einschliesslich von T-Zellen ausgehender Tumoren","Parkinson-ähnliche Bewegungsstörungen und Guillain-Barré-Syndrom (v. a. bei Anti-BCMA-CAR-T-Zellen)"]},"schwangerschaft":"Nicht empfohlen; es liegen keine Daten vor. Vor Beginn Schwangerschaftstest; wirksame Verhütung nach Vorgabe des Behandlungszentrums.","stillzeit":"Nur nach ärztlicher Abwägung; ein Risiko für das gestillte Kind kann nicht ausgeschlossen werden.","hinweise":["In den ersten 4 Wochen nach der Infusion in der Nähe des Behandlungszentrums bleiben; Fieber, Verwirrtheit, Zittern oder Sprachstörungen sofort melden.","Mindestens 8 Wochen nach der Infusion kein Fahrzeug lenken und keine Maschinen bedienen.","Patientenkarte stets mitführen; kein Blut und keine Organe, Gewebe oder Zellen spenden.","Manche HIV-Tests können nach der Behandlung falsch positiv ausfallen."],"darreichung":["Infusionsdispersion (einmalige Infusion)"]},"carbamazepin":{"wirkmechanismus":"Beruhigt überaktive Nervenzellen und verhindert so Krampfanfälle und einschiessende Nervenschmerzen. Carbamazepin blockiert spannungsabhängige Natriumkanäle und hemmt dadurch die wiederholte, hochfrequente Entladung von Nervenzellen. Es wird über CYP3A4 zum ebenfalls wirksamen Carbamazepin-10,11-epoxid abgebaut und ist selbst ein starker Induktor von CYP3A4, weiteren CYP-Enzymen und P-Glykoprotein – auch seines eigenen Abbaus (Autoinduktion).","nebenwirkungen":{"sehrHaeufig":["Leukopenie (Mangel an weissen Blutkörperchen)","Schwindel, Gang- und Koordinationsstörungen (Ataxie), Schläfrigkeit","Übelkeit, Erbrechen","Allergische Hautreaktionen, Nesselsucht","Erhöhte Gamma-GT (Leberenzym)"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen), Eosinophilie","Hyponatriämie (Natriummangel), Wassereinlagerungen, Gewichtszunahme","Kopfschmerzen, Müdigkeit","Doppelbilder, verschwommenes Sehen","Mundtrockenheit","Erhöhte alkalische Phosphatase"],"gelegentlich":["Unwillkürliche Bewegungen (Zittern, Tics, Dystonie), Augenzittern (Nystagmus)","Durchfall, Verstopfung","Erhöhte Leberwerte (Transaminasen)","Exfoliative Dermatitis (schuppende Hautentzündung)"],"selten":["Multiorgan-Überempfindlichkeitsreaktion (DRESS) mit Fieber, Ausschlag und Organbeteiligung","Hepatitis, Gelbsucht","Herzrhythmusstörungen, AV-Block","Halluzinationen, Depression, Verwirrtheit, Unruhe","Lupus-erythematodes-ähnliches Syndrom","Periphere Nervenschädigung, Sprechstörungen"],"sehrSelten":["Agranulozytose, aplastische Anämie, Panzytopenie (schwere Blutbildstörungen)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Anaphylaxie, Angioödem","Leberversagen","Pankreatitis (Entzündung der Bauchspeicheldrüse)","Akute Porphyrie","Interstitielle Nephritis, Nierenversagen","Verminderte Knochendichte (Osteomalazie)"],"unbekannt":["Knochenmarkdepression","Kolitis (Darmentzündung)","Reaktivierung des Herpesvirus 6","Knochenbrüche"]},"schwangerschaft":"Erhöht das Risiko für Fehlbildungen (u. a. Neuralrohrdefekte); nicht ohne ärztliche Rücksprache absetzen. Bei Kinderwunsch Behandlung vorab überprüfen; Monotherapie in niedrigster wirksamer Dosis und Folsäure-Einnahme.","stillzeit":"Geht in die Muttermilch über; Stillen ist nach ärztlicher Abwägung möglich, das Kind auf Schläfrigkeit, Trinkschwäche und Hautausschlag beobachten.","hinweise":["Blutbild, Leberwerte und Natrium vor und regelmässig während der Behandlung kontrollieren; bei Fieber, Halsschmerzen, Ausschlag, Blutergüssen oder Gelbsucht sofort ärztlich melden.","Nicht abrupt absetzen – Gefahr von Krampfanfällen.","Vor jedem neuen Medikament (auch Pille, Antibiotika, Blutverdünner) auf Carbamazepin hinweisen: viele Wechselwirkungen.","Kein Grapefruitsaft; Alkohol meiden; Vorsicht beim Autofahren."],"darreichung":["Tabletten","Retardtabletten","Suspension zum Einnehmen"]},"carbetocin":{"wirkmechanismus":"Bewirkt, dass sich die Gebärmutter nach der Geburt zusammenzieht, und beugt so starken Blutungen vor. Carbetocin ist ein synthetisches, lang wirksames Analogon des Hormons Oxytocin und bindet an die Oxytocin-Rezeptoren der Gebärmuttermuskulatur. Innerhalb von etwa 2 Minuten setzen kräftige Kontraktionen ein, die rund eine Stunde anhalten – länger als nach Oxytocin. Eine einmalige Injektion genügt.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Bauchschmerzen","Juckreiz","Kopfschmerzen","Zittern","Blutdruckabfall","Flush (Gesichtsrötung), Wärmegefühl"],"haeufig":["Erbrechen","Rückenschmerzen","Schwindel","Metallischer Geschmack","Anämie (Blutarmut)","Brustschmerzen","Atemnot","Schüttelfrost"]},"schwangerschaft":"Vor der Geburt des Kindes kontraindiziert; nicht zur Geburtseinleitung oder Wehenverstärkung.","stillzeit":"Nur sehr geringe Mengen gehen in die Muttermilch über und werden im Darm des Säuglings abgebaut; Stillen ist möglich.","hinweise":["Wird einmalig nach der Entbindung des Kindes von Fachpersonen in die Vene gespritzt; keine Wiederholung.","Blutdruck und Blutungen werden danach überwacht.","Bei anhaltender Blutung müssen andere Ursachen abgeklärt werden."],"darreichung":["Injektionslösung"]},"carbimazol":{"wirkmechanismus":"Bremst die Bildung von Schilddrüsenhormonen und normalisiert so den Stoffwechsel bei einer Überfunktion. Carbimazol wird im Körper rasch und vollständig in den Wirkstoff Thiamazol (Methimazol) umgewandelt. Thiamazol hemmt die Thyreoperoxidase, das Enzym, das Jod in das Speichereiweiss Thyreoglobulin einbaut und die Hormonvorstufen zu T4 und T3 verknüpft. Bereits gebildetes, gespeichertes Hormon wird nicht beeinflusst; deshalb setzt die Wirkung erst nach 1–3 Wochen ein, die volle Wirkung oft erst nach 4–8 Wochen.","nebenwirkungen":{"haeufig":["Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Gelenkschmerzen","Übelkeit, leichte Magen-Darm-Beschwerden","Kopfschmerzen"],"gelegentlich":["Agranulozytose (starker Mangel an weissen Blutkörperchen) mit Fieber, Halsschmerzen und Infektionen, meist in den ersten Behandlungsmonaten","Arzneimittelfieber"],"sehrSelten":["Leberschäden (Gallenstau mit Gelbsucht, Hepatitis)","Aplastische Anämie, Thrombozytopenie, Panzytopenie (Mangel an allen Blutzellen)","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom)","Haarausfall","Insulin-Autoimmunsyndrom mit Unterzuckerung","Vaskulitis, Lupus-ähnliche Reaktionen, Nervenentzündungen","Geschmacks- und Geruchsstörungen"],"unbekannt":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Angioödem","Schilddrüsenunterfunktion und Kropfwachstum bei zu hoher Dosis"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung in der niedrigsten wirksamen Dosis und ohne zusätzliches Levothyroxin. Im ersten Schwangerschaftsdrittel kann Carbimazol Fehlbildungen verursachen (z. B. Hautdefekte am Kopf, Fehlbildungen von Gesicht, Speiseröhre oder Bauchwand); in dieser Zeit wird meist ein anderes Thyreostatikum bevorzugt.","stillzeit":"Geht in die Muttermilch über. Stillen ist nur nach ärztlicher Abwägung bei niedriger Dosis und mit Kontrolle der Schilddrüsenwerte des Kindes möglich.","hinweise":["Bei Fieber, Halsschmerzen, Mundgeschwüren oder grippeähnlichen Beschwerden sofort ärztliche Hilfe suchen und das Blutbild bestimmen lassen.","Regelmässige Kontrollen von Schilddrüsenwerten, Blutbild und Leberwerten.","Frauen im gebärfähigen Alter sollen während der Behandlung zuverlässig verhüten.","Die Wirkung setzt erst nach einigen Wochen ein; nicht eigenmächtig absetzen."],"darreichung":["Tabletten"]},"carboplatin":{"wirkmechanismus":"Schädigt das Erbgut von Krebszellen, sodass sie sich nicht mehr teilen können. Carboplatin wird in der Zelle in reaktive Platinkomplexe umgewandelt, die DNA-Stränge vernetzen und so DNA-Synthese und Zellteilung blockieren. Wirkprinzip und Wirkspektrum ähneln Cisplatin; Carboplatin ist weniger nieren-, nerven- und gehörschädigend, hemmt aber das Knochenmark stärker. Die Dosis wird meist anhand der Nierenfunktion berechnet.","nebenwirkungen":{"sehrHaeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Neutropenie und Leukopenie (Mangel an weissen Blutkörperchen)","Anämie (Blutarmut)","Übelkeit und Erbrechen","Bauchschmerzen","Elektrolytverluste (Natrium, Kalium, Calcium, Magnesium)","Anstieg von Leberwerten (alkalische Phosphatase)"],"haeufig":["Infektionen","Blutungen","Allergische Reaktionen bis zur Anaphylaxie (schwere allergische Reaktion)","Periphere Neuropathie (Kribbeln, Taubheit)","Hörstörungen, Tinnitus (Ohrgeräusche)","Interstitielle Lungenerkrankung, Bronchospasmus (Verkrampfung der Atemwege)","Durchfall, Verstopfung, Geschmacksstörungen","Haarausfall, Schwäche"],"unbekannt":["Akute Leukämie oder andere Zweitkrebserkrankungen als Spätfolge","Hämolytisch-urämisches Syndrom (Blutzerfall mit Nierenversagen)","Herzinsuffizienz, Schlaganfall, Embolien","Sehstörungen bis vorübergehende Erblindung","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Tumorlysesyndrom"]},"schwangerschaft":"Kontraindiziert, da Fruchtschäden möglich sind. Frauen und Männer sollen während und noch mindestens 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert; während der Behandlung nicht stillen.","hinweise":["Vor jedem Zyklus wird das Blutbild kontrolliert; Fieber über 38 °C oder Blutungszeichen sofort melden.","Keine Lebendimpfungen während und einige Monate nach der Therapie.","Spermien- bzw. Eizellkonservierung vor Therapiebeginn besprechen (mögliche Unfruchtbarkeit)."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"carfilzomib":{"wirkmechanismus":"Blockiert in Myelomzellen das Proteasom, die «Abfallentsorgung» der Zelle, sodass sich fehlerhafte Eiweisse anhäufen und die Krebszelle abstirbt. Carfilzomib bindet selektiv und irreversibel an die chymotrypsinartige Untereinheit (β5) des 20S-Proteasoms und des Immunoproteasoms. Die anhaltende Hemmung führt zu Zellzyklus-Stillstand und programmiertem Zelltod (Apoptose); Myelomzellen sind dafür wegen ihrer hohen Eiweissproduktion besonders empfindlich.","nebenwirkungen":{"sehrHaeufig":["Thrombozytopenie, Neutropenie, Anämie (Blutbildveränderungen)","Atemwegsinfekte, Lungenentzündung","Bluthochdruck","Atemnot (Dyspnoe), Husten","Durchfall, Übelkeit, Erbrechen","Müdigkeit, Fieber","Periphere Ödeme (Wassereinlagerungen)","Erhöhtes Kreatinin (Nierenwert)"],"haeufig":["Herzinsuffizienz (Herzschwäche), Vorhofflimmern","Akutes Nierenversagen","Tiefe Venenthrombose, Lungenembolie","Sepsis (Blutvergiftung)","Infusionsreaktionen"],"gelegentlich":["Herzinfarkt","Akutes Lungenversagen (ARDS), Lungenhochdruck","Tumorlyse-Syndrom (Stoffwechselentgleisung durch zerfallende Tumorzellen)","Leberversagen","Hirnblutung","Magen-Darm-Perforation"],"selten":["Thrombotische Mikroangiopathie (z. B. TTP, hämolytisch-urämisches Syndrom)","Posteriores reversibles Enzephalopathie-Syndrom (PRES: Kopfschmerzen, Sehstörungen, Krampfanfälle)"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, seltene Hirninfektion)","Reaktivierung einer Hepatitis B"]},"schwangerschaft":"Nicht anwenden; im Tierversuch fruchtschädigend. Frauen verhüten während und bis 1 Monat, Männer bis 3 Monate nach der Behandlung. In Kombination mit Lenalidomid gilt zusätzlich dessen Schwangerschaftsverhütungsprogramm.","stillzeit":"Kontraindiziert; während der Behandlung und mindestens 2 Tage danach nicht stillen.","hinweise":["Ausreichend trinken; vor den Infusionen wird oft zusätzlich Flüssigkeit gegeben (Schutz der Nieren).","Blutdruck, Blutbild, Nierenwerte und Elektrolyte werden regelmässig kontrolliert.","Atemnot, Brustschmerzen, geschwollene Beine, starke Kopfschmerzen oder Sehstörungen sofort melden.","Thromboseprophylaxe nach ärztlicher Vorgabe, besonders in Kombination mit Lenalidomid."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"carglumsaeure":{"wirkmechanismus":"Ermöglicht dem Körper, giftiges Ammoniak wieder in Harnstoff umzuwandeln und über den Urin auszuscheiden. Carglumsäure ist ein Strukturanalogon von N-Acetylglutamat, dem natürlichen Aktivator der Carbamoylphosphat-Synthetase 1, des ersten Enzyms des Harnstoffzyklus in der Leber. Fehlt N-Acetylglutamat – angeboren beim NAGS-Mangel oder durch Hemmung der Synthase bei Organoazidurien –, aktiviert Carglumsäure das Enzym direkt und senkt so den Ammoniakspiegel.","nebenwirkungen":{"haeufig":["Vermehrtes Schwitzen (Hyperhidrose)"],"gelegentlich":["Bradykardie (langsamer Puls)","Durchfall, Erbrechen","Fieber","Erhöhte Leberwerte (Transaminasen)"],"unbekannt":["Hautausschlag"]},"schwangerschaft":"Nur begrenzte Erfahrungen; im Tierversuch geringe Entwicklungstoxizität. Anwendung nur nach sorgfältiger ärztlicher Abwägung.","stillzeit":"Kontraindiziert: Carglumsäure geht bei Ratten in die Milch über und schadete den Jungtieren. Während der Behandlung nicht stillen.","hinweise":["Tabletten nicht ganz schlucken und nicht zerkauen: in etwas Wasser zerfallen lassen und sofort trinken; Gabe auch über eine Magensonde möglich.","Vor den Mahlzeiten einnehmen.","Ungeöffnet im Kühlschrank lagern; nach dem ersten Öffnen nicht mehr kühlen, unter 30 °C aufbewahren und innerhalb eines Monats verbrauchen.","Bei Erbrechen, Schläfrigkeit oder Verwirrtheit sofort ärztliche Hilfe holen – mögliche Zeichen eines Ammoniakanstiegs."],"darreichung":["Tabletten zur Herstellung einer Suspension zum Einnehmen"]},"cariprazin":{"wirkmechanismus":"Stabilisiert die Signalübertragung durch Dopamin im Gehirn und mildert so psychotische Symptome und Antriebslosigkeit. Cariprazin ist ein Partialagonist an Dopamin-D3- und D2-Rezeptoren mit besonders hoher Affinität zu D3, ausserdem Partialagonist an Serotonin-5-HT1A- und Antagonist an 5-HT2B- und 5-HT2A-Rezeptoren. Zusammen mit seinen beiden aktiven Metaboliten (Desmethyl- und Didesmethylcariprazin) hat es eine sehr lange Halbwertszeit von bis zu mehreren Wochen, so dass Wirkung und Nebenwirkungen verzögert einsetzen und abklingen.","nebenwirkungen":{"sehrHaeufig":["Akathisie (Sitzunruhe, Bewegungsdrang)","Parkinsonismus (Zittern, Steifigkeit, verlangsamte Bewegungen)"],"haeufig":["Gewichtszunahme, Appetitzunahme oder -abnahme, veränderte Blutfette","Schlafstörungen, Schläfrigkeit, Angst","Sedierung, Schwindel, Dystonie (Muskelverkrampfungen), Dyskinesien","Verschwommenes Sehen","Herzrasen, Bluthochdruck","Übelkeit, Verstopfung, Erbrechen","Erhöhte Leberwerte, erhöhte Kreatinkinase (Muskelenzym)","Müdigkeit"],"gelegentlich":["Blutarmut, Eosinophilie","Hyponatriämie (Natriummangel), Blutzuckerschwankungen","Suizidales Verhalten, Depression","Spätdyskinesien (unwillkürliche Bewegungen)","Reizleitungsstörungen, langsamer Puls, QT-Verlängerung","Blutdruckabfall","Juckreiz, Hautausschlag","Störungen beim Wasserlassen"],"selten":["Neutropenie (Mangel an weissen Blutkörperchen)","Schilddrüsenunterfunktion","Anaphylaxie (schwere allergische Reaktion)","Krampfanfälle","Grauer Star (Katarakt), Lichtscheu","Rhabdomyolyse (Muskelzerfall)"],"unbekannt":["Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung)","Toxische Hepatitis (Leberentzündung)"]},"schwangerschaft":"Nicht empfohlen. Frauen im gebärfähigen Alter müssen während der Behandlung und mindestens 10 Wochen danach sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wirkung und Nebenwirkungen setzen wegen der sehr langen Halbwertszeit verzögert ein und klingen nach dem Absetzen erst nach Wochen ab.","Keinen Grapefruitsaft trinken; neue Medikamente (auch Johanniskraut) nur nach Rücksprache einnehmen.","Innere Unruhe oder Bewegungsdrang (Akathisie) ärztlich melden."],"darreichung":["Hartkapseln"]},"carmustin":{"wirkmechanismus":"Hemmt die Vermehrung von Krebszellen, indem es ihr Erbgut schädigt. Carmustin ist ein fettlöslicher Nitrosoharnstoff, der die Blut-Hirn-Schranke gut überwindet. Seine Abbauprodukte alkylieren DNA und RNA und vernetzen DNA-Stränge; zusätzlich carbamoylieren sie Eiweisse und hemmen so Reparaturenzyme. Die Knochenmarkhemmung tritt verzögert auf, mit einem Tiefpunkt nach 4–6 Wochen.","nebenwirkungen":{"sehrHaeufig":["Verzögerte Knochenmarkhemmung (Thrombozytopenie, Leukopenie) mit Blutungs- und Infektionsgefahr","Übelkeit und Erbrechen (meist innert 2 Stunden nach der Infusion)","Lungenschäden (Lungeninfiltrate, Lungenfibrose), auch Jahre später"],"haeufig":["Anämie (Blutarmut)","Appetitlosigkeit, Verstopfung, Durchfall, Mundschleimhautentzündung","Vorübergehend erhöhte Leberwerte","Haarausfall, Hautrötung (Flush), Hautverfärbung","Akute Leukämie und Myelodysplasie (Zweiterkrankungen)"],"unbekannt":["Blutdruckabfall und Brennen an der Vene bei zu schneller Infusion","Nierenschäden bis Nierenversagen","Lebervenenverschlusskrankheit","Krampfanfälle, Enzephalopathie","Netzhautschäden (bei hoher Dosis)","Unfruchtbarkeit"]},"schwangerschaft":"Nicht anwenden: Carmustin kann das ungeborene Kind schädigen. Frauen und Männer müssen während und bis mindestens 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Wird im Spital als Infusion über 1–2 Stunden gegeben; zu schnelle Gabe verursacht Hautrötung und Blutdruckabfall.","Bei Husten oder Atemnot – auch noch Jahre nach der Behandlung – ärztlich abklären lassen; nicht rauchen.","Blutbild wird bis 6 Wochen nach jeder Gabe kontrolliert; die nächste Gabe frühestens nach 6 Wochen.","Das Lösungsmittel enthält Alkohol – am Behandlungstag nicht Auto fahren."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Infusionslösung"]},"carvedilol":{"wirkmechanismus":"Senkt Blutdruck und Puls und entlastet das Herz, indem es die Wirkung der Stresshormone dämpft und gleichzeitig die Blutgefässe weitet. Carvedilol blockiert nicht selektiv die Beta-1- und Beta-2-Adrenozeptoren und senkt so Herzfrequenz, Kontraktionskraft und Reninfreisetzung. Die zusätzliche Blockade der Alpha-1-Rezeptoren in den Gefässwänden erweitert die Gefässe und senkt den peripheren Widerstand. Carvedilol wird in der Leber vor allem über CYP2D6 und CYP2C9 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Kopfschmerzen","Müdigkeit und Schwäche (Asthenie)","Hypotonie (tiefer Blutdruck)","Verschlechterung einer Herzschwäche, vor allem zu Beginn und bei Dosiserhöhung"],"haeufig":["Bradykardie (langsamer Puls), Ödeme (Wassereinlagerungen)","Blutdruckabfall beim Aufstehen, kalte Hände und Füsse","Atemnot; Asthmaanfälle bei entsprechender Veranlagung","Bronchitis, Lungenentzündung, Harnwegsinfekte","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Depression, depressive Verstimmung","Sehstörungen, verminderter Tränenfluss (trockene Augen)","Schlechtere Blutzuckereinstellung bei Diabetes, Gewichtszunahme; Verschlechterung der Nierenfunktion bei Gefässerkrankung oder Nierenschwäche","Anämie (Blutarmut)"],"gelegentlich":["AV-Block, Angina pectoris","Synkope (Ohnmacht), Kribbeln (Parästhesien)","Schlafstörungen","Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht, psoriasisartige Veränderungen), Haarausfall","Erektionsstörungen","Verstopfung"],"selten":["Thrombozytopenie (Mangel an Blutplättchen)","Verstopfte Nase","Mundtrockenheit"],"sehrSelten":["Leukopenie (Mangel an weissen Blutkörperchen)","Allergische Reaktionen","Erhöhte Leberwerte","Harninkontinenz bei Frauen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)"],"unbekannt":["Halluzinationen","Vermehrtes Schwitzen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung: Betablocker können die Durchblutung der Plazenta vermindern und das Wachstum des Kindes hemmen. Neugeborene in den ersten Lebenstagen auf langsamen Puls, Unterzuckerung und Atemprobleme überwachen.","stillzeit":"Stillen wird nicht empfohlen; Carvedilol und seine Abbauprodukte gehen (im Tierversuch) in die Muttermilch über.","hinweise":["Mit einer Mahlzeit einnehmen – bei Herzschwäche verringert das Schwindel und Blutdruckabfall beim Aufstehen.","Nicht abrupt absetzen (Gefahr von Angina-pectoris-Anfällen und Blutdruckanstieg); ein Absetzen erfolgt schrittweise nach ärztlicher Anweisung.","Zu Beginn und bei Dosiserhöhung Schwindel und Müdigkeit möglich; Vorsicht beim Autofahren, Alkohol verstärkt dies.","Bei Herzschwäche täglich wiegen: rasche Gewichtszunahme oder zunehmende Atemnot ärztlich melden."],"darreichung":["Tabletten"]},"caspofungin":{"wirkmechanismus":"Schädigt die Zellwand von Pilzen, sodass diese platzen oder nicht mehr wachsen können. Caspofungin hemmt nicht-kompetitiv das Enzym β-(1,3)-D-Glucan-Synthase, das einen wesentlichen Baustein der Pilzzellwand herstellt; menschliche Zellen besitzen dieses Enzym nicht. Gegen Candida wirkt es abtötend, gegen Aspergillus hemmt es das Wachstum der Pilzfäden. Caspofungin wird nicht über Cytochrom-P450 abgebaut und hat daher wenige Wechselwirkungen.","nebenwirkungen":{"haeufig":["Abfall von Hämoglobin, Hämatokrit und weissen Blutkörperchen","Hypokaliämie (Kaliummangel)","Kopfschmerzen","Venenentzündung an der Infusionsstelle (Phlebitis)","Atemnot","Übelkeit, Durchfall, Erbrechen","Erhöhte Leberwerte (ALT, AST, alkalische Phosphatase, Bilirubin)","Ausschlag, Juckreiz, Hautrötung, Schwitzen, Gelenkschmerzen, Fieber, Schüttelfrost"],"gelegentlich":["Anämie, Thrombozytopenie, Gerinnungsstörungen","Flüssigkeitsüberladung, Hypomagnesiämie, Hyperglykämie, Appetitlosigkeit","Angst, Schlaflosigkeit, Verwirrtheit","Schwindel, Geschmacksstörungen, Kribbeln, Zittern","Herzrhythmusstörungen (z. B. Vorhofflimmern), Herzklopfen, Herzinsuffizienz","Blutdruckabfall oder -anstieg, Hitzewallungen","Bronchospasmus, Husten","Bauchschmerzen, Verstopfung, Verdauungsbeschwerden","Cholestase, Gelbsucht, Leberfunktionsstörung","Nesselsucht, Erythema multiforme","Muskelschmerzen, Nierenfunktionsstörung bis akutes Nierenversagen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Akutes Atemnotsyndrom (ARDS)","Hyperkalzämie","Periphere Ödeme"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur bei eindeutiger Notwendigkeit anwenden.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird im Spital einmal täglich als Infusion über etwa 1 Stunde verabreicht.","Ausschlag, Schwellungen, Juckreiz, Wärmegefühl oder Atemnot während der Infusion sofort melden.","Leberwerte und Elektrolyte werden während der Behandlung kontrolliert."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"cefaclor":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Cefaclor ist ein Betalaktam-Antibiotikum und hemmt die Penicillin-bindenden Proteine, die für die Quervernetzung der Zellwand nötig sind (bakterizid). Es wirkt gegen viele grampositive Erreger (Streptokokken, Staphylokokken) und einige gramnegative wie Haemophilus influenzae, Moraxella und E. coli. Gegen Enterokokken und MRSA wirkt es nicht.","nebenwirkungen":{"haeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautablösung)"],"unbekannt":["Serumkrankheit-ähnliche Reaktion (Ausschlag mit Gelenkschmerzen und Fieber), vor allem bei Kindern","Pseudomembranöse Kolitis (schwere Darmentzündung)","Scheidenpilz","Erhöhte Leberwerte, Gelbsucht","Blutbildveränderungen (Eosinophilie, Leukopenie, Thrombozytopenie, hämolytische Anämie)","Interstitielle Nephritis (Nierenentzündung)","Schwindel, Kopfschmerzen, Unruhe, Schlaflosigkeit"]},"schwangerschaft":"Cephalosporine gelten in der Schwangerschaft als gut verträglich; trotzdem nur nach ärztlicher Abwägung anwenden, besonders im ersten Drittel.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich. Beim Säugling auf Durchfall oder Pilzbefall achten.","hinweise":["Die verordnete Behandlungsdauer einhalten, auch wenn die Beschwerden früher abklingen.","Retardtabletten unzerkaut zu einer Mahlzeit einnehmen.","Hautausschlag mit Gelenkschmerzen oder Fieber sowie starken oder blutigen Durchfall ärztlich melden."],"darreichung":["Kapseln","Retardtabletten","Suspension zum Einnehmen"]},"cefazolin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Cefazolin hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Als Cephalosporin der 1. Generation wirkt es besonders gut gegen grampositive Keime wie Methicillin-empfindliche Staphylokokken und Streptokokken, gegen gramnegative Erreger nur begrenzt. Gegen MRSA und Enterokokken ist es unwirksam.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Appetitlosigkeit, Durchfall, Bauchschmerzen","Schmerzen an der Einstichstelle, Venenentzündung (Phlebitis) bei Infusion"],"gelegentlich":["Hautausschlag, Nesselsucht, Juckreiz","Pilzinfektion von Mund oder Scheide (Candidose)"],"selten":["Blutbildveränderungen (Leukopenie, Neutropenie, Thrombozytopenie, Eosinophilie)","Vorübergehender Anstieg der Leberwerte","Nierenfunktionsstörung, interstitielle Nephritis (Nierenentzündung)","Anaphylaxie (schwere allergische Reaktion)"],"sehrSelten":["Pseudomembranöse Kolitis (schwere Darmentzündung)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Hämolytische Anämie (Blutzerfall)"],"unbekannt":["Krampfanfälle bei hohen Dosen und eingeschränkter Nierenfunktion","Gerinnungsstörungen mit Blutungen (Hypoprothrombinämie)","Positiver Coombs-Test"]},"schwangerschaft":"Kann angewendet werden, wenn nötig; breite Erfahrung, z. B. als Infektionsvorbeugung beim Kaiserschnitt, ohne Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht nur in sehr geringen Mengen in die Muttermilch über; die Anwendung ist möglich (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Wird im Spital oder in der Praxis als Injektion oder Infusion gegeben.","Allergien gegen Penicilline oder Cephalosporine vor der Gabe unbedingt melden.","Bei längerer Behandlung Blutbild und Nierenwerte kontrollieren."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"cefepim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Cefepim hemmt als Betalaktam-Antibiotikum die Penicillin-bindenden Proteine. Es dringt besonders rasch durch die äussere Membran gramnegativer Bakterien und ist stabiler gegen AmpC-Betalaktamasen als ältere Cephalosporine. Es wirkt gegen viele gramnegative Erreger einschliesslich Pseudomonas aeruginosa sowie gegen Streptokokken und methicillinempfindliche Staphylokokken, nicht aber gegen MRSA und Enterokokken.","nebenwirkungen":{"sehrHaeufig":["Positiver Coombs-Test (Laborbefund)"],"haeufig":["Durchfall","Hautausschlag","Venenentzündung und Reaktionen an der Injektionsstelle","Erhöhte Leber- und Bilirubinwerte","Anämie, Eosinophilie","Verlängerte Gerinnungszeiten"],"gelegentlich":["Übelkeit, Erbrechen","Kopfschmerzen","Pilzinfektionen (Mund, Scheide)","Kolitis, auch pseudomembranös (schwere Darmentzündung)","Thrombozytopenie, Leukopenie, Neutropenie","Juckreiz, Nesselsucht","Fieber","Erhöhte Nierenwerte"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Krampfanfälle","Kribbeln, Geschmacksstörungen, Schwindel","Angioödem","Atemnot"],"unbekannt":["Enzephalopathie (Verwirrtheit, Halluzinationen, Muskelzuckungen, Bewusstseinsstörung bis zum Koma)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Agranulozytose, aplastische und hämolytische Anämie","Nierenversagen"]},"schwangerschaft":"Begrenzte Erfahrungen; Tierversuche ohne Hinweis auf Schädigung. Nur nach sorgfältiger ärztlicher Abwägung anwenden.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über; Anwendung mit Vorsicht möglich. Beim Säugling auf Durchfall oder Pilzbefall achten.","hinweise":["Wird im Spital als Infusion oder Injektion gegeben; die Dosis richtet sich nach der Nierenfunktion.","Verwirrtheit, Muskelzuckungen oder Krampfanfälle sofort melden – besonders bei eingeschränkter Nierenfunktion.","Starken oder blutigen Durchfall melden, auch nach Behandlungsende."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"cefiderocol":{"wirkmechanismus":"Tötet auch hochresistente gramnegative Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Cefiderocol trägt eine Gruppe, die Eisen bindet wie die bakterieneigenen Eisenfänger (Siderophore): Die Bakterien schleusen es über ihre Eisentransportsysteme aktiv ins Innere («Trojanisches Pferd»). Dort hemmt es vor allem das Penicillin-bindende Protein 3. Es ist stabil gegen viele Betalaktamasen, auch Carbapenemasen einschliesslich Metallo-Betalaktamasen; gegen grampositive Bakterien und Anaerobier wirkt es kaum.","nebenwirkungen":{"haeufig":["Pilzinfektionen (Mund, Scheide, Harnwege)","Clostridioides-difficile-Kolitis (schwere Darmentzündung)","Husten","Durchfall, Übelkeit, Erbrechen","Hautausschlag","Erhöhte Leberwerte","Reaktionen an der Infusionsstelle"],"gelegentlich":["Überempfindlichkeitsreaktionen, Juckreiz"],"unbekannt":["Positiver Coombs-Test (Laborbefund)","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Keine Erfahrungen beim Menschen. Vorsichtshalber während der Schwangerschaft nicht anwenden, ausser es ist unbedingt erforderlich.","stillzeit":"Nicht bekannt, ob Cefiderocol in die Muttermilch übergeht. Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Wird im Spital als Infusion über 3 Stunden gegeben; die Dosis richtet sich nach der Nierenfunktion.","Urin-Teststreifen (Eiweiss, Ketone, Blut) können falsch positiv ausfallen – andere Messmethoden verwenden.","Starken oder blutigen Durchfall sofort melden."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"cefixim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Cefixim hemmt als Betalaktam-Antibiotikum die Penicillin-bindenden Proteine und damit die Quervernetzung der bakteriellen Zellwand (bakterizid). Es ist gegen viele Betalaktamasen stabil und wirkt besonders gut gegen gramnegative Erreger wie Haemophilus influenzae, Moraxella, E. coli und Gonokokken sowie gegen Streptokokken. Gegen Staphylokokken, Enterokokken und Pseudomonas wirkt es nicht ausreichend.","nebenwirkungen":{"haeufig":["Durchfall, weicher Stuhl"],"gelegentlich":["Bauchschmerzen, Übelkeit, Erbrechen","Kopfschmerzen","Hautausschlag","Erhöhte Leberwerte"],"selten":["Juckreiz, Überempfindlichkeitsreaktionen","Schwindel","Blähungen, Appetitlosigkeit","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Pilzinfektionen (Superinfektion)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse (schwere Hautablösung)","Pseudomembranöse Kolitis (schwere Darmentzündung)","Blutbildveränderungen (Agranulozytose, Thrombozytopenie, hämolytische Anämie)","Leberentzündung, Gelbsucht","Interstitielle Nephritis (Nierenentzündung)"]},"schwangerschaft":"Cephalosporine gelten in der Schwangerschaft als gut verträglich; trotzdem nur nach ärztlicher Abwägung anwenden.","stillzeit":"Übergang in die Muttermilch nicht ausreichend untersucht; Anwendung nur nach ärztlicher Abwägung. Beim Säugling auf Durchfall oder Pilzbefall achten.","hinweise":["Unabhängig von den Mahlzeiten einnehmen; die verordnete Behandlungsdauer einhalten.","Starken oder blutigen Durchfall ärztlich melden.","Bei Gonorrhö auch Sexualpartnerinnen und -partner untersuchen und behandeln lassen."],"darreichung":["Filmtabletten","Suspension zum Einnehmen"]},"cefpodoxim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Cefpodoxim-Proxetil ist eine Vorstufe (Prodrug), die beim Durchtritt durch die Darmwand zum wirksamen Cefpodoxim gespalten wird. Dieses hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es ist gegen viele Beta-Laktamasen stabil und wirkt gegen Streptokokken, Pneumokokken, Haemophilus influenzae, Moraxella und viele E.-coli-Stämme; gegen Staphylokokken nur mässig, gegen Pseudomonas, Enterokokken und MRSA nicht.","nebenwirkungen":{"haeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Blähungen"],"gelegentlich":["Kopfschmerzen, Schwindel, Kribbeln (Parästhesien)","Hautausschlag, Nesselsucht, Juckreiz","Müdigkeit, Schwäche"],"selten":["Blutbildveränderungen (Abfall des Hämoglobins, Thrombozytose, Thrombozytopenie, Leukopenie, Eosinophilie)","Anstieg von Leber- und Nierenwerten"],"sehrSelten":["Hämolytische Anämie (Blutzerfall)","Anaphylaxie, Angioödem, Bronchospasmus","Pseudomembranöse Kolitis (schwere Darmentzündung)","Leberschädigung (meist mit Gallestau)","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)"],"unbekannt":["Pilzinfektionen (Mund, Scheide)","Ohrensausen (Tinnitus)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; im Tierversuch keine Hinweise auf eine Schädigung, Erfahrungen beim Menschen begrenzt.","stillzeit":"Geht in die Muttermilch über; nur nach ärztlicher Abwägung anwenden oder abstillen.","hinweise":["Tabletten mit einer Mahlzeit einnehmen – so wird Cefpodoxim besser aufgenommen.","Antazida und andere säurebindende Mittel mit 2–3 Stunden Abstand einnehmen.","Die verordnete Behandlungsdauer einhalten; bei Hautausschlag oder schwerem Durchfall ärztlichen Rat einholen."],"darreichung":["Filmtabletten","Granulat für Suspension zum Einnehmen"]},"ceftarolinfosamil":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört – auch bei methicillinresistenten Staphylokokken (MRSA). Ceftarolinfosamil ist eine Vorstufe, die im Blut rasch zum wirksamen Ceftarolin umgewandelt wird. Ceftarolin bindet an die Penicillin-bindenden Proteine, insbesondere auch an PBP2a von MRSA und an veränderte PBPs penicillinresistenter Pneumokokken. Gegen ESBL- und AmpC-bildende Enterobakterien sowie Pseudomonas wirkt es nicht.","nebenwirkungen":{"sehrHaeufig":["Positiver direkter Coombs-Test (Laborbefund)"],"haeufig":["Hautausschlag, Juckreiz","Kopfschmerzen, Schwindel","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Erhöhte Leberwerte","Venenentzündung und Reaktionen an der Infusionsstelle","Fieber"],"gelegentlich":["Clostridioides-difficile-Kolitis (schwere Darmentzündung)","Anämie, Leukopenie, Neutropenie, Thrombozytopenie","Verlängerte Gerinnungszeiten","Anaphylaxie und andere Überempfindlichkeitsreaktionen (Nesselsucht, Schwellung von Lippen und Gesicht)","Erhöhtes Kreatinin"],"selten":["Agranulozytose","Eosinophilie"],"unbekannt":["Eosinophile Pneumonie (allergische Lungenentzündung)","Enzephalopathie (Verwirrtheit, Bewusstseinsstörung), vor allem bei eingeschränkter Nierenfunktion"]},"schwangerschaft":"Begrenzte Erfahrungen; Tierversuche ohne Hinweis auf Schädigung. Vorsichtshalber nur anwenden, wenn der Zustand der Patientin es erfordert.","stillzeit":"Nicht bekannt, ob Ceftarolin in die Muttermilch übergeht. Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Wird im Spital als Infusion gegeben; die Dosis richtet sich nach der Nierenfunktion.","Starken oder blutigen Durchfall sowie Hautausschlag sofort melden.","Kann den Coombs-Test positiv machen; vor Bluttransfusionen die Behandlung angeben."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"ceftazidim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Ceftazidim hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es wirkt vor allem gegen gramnegative Bakterien einschliesslich Pseudomonas aeruginosa, gegen grampositive Keime wie Staphylokokken dagegen nur schwach. Bakterien mit Beta-Laktamasen vom ESBL- oder AmpC-Typ sowie Carbapenemase-Bildner sind meist resistent. Ceftazidim wird fast unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Eosinophilie, Thrombozytose (Vermehrung der Blutplättchen)","Venenentzündung (Phlebitis) bei Infusion, Schmerzen und Entzündung an der Einstichstelle","Durchfall","Vorübergehender Anstieg der Leberwerte","Hautausschlag (fleckig oder mit Quaddeln)","Positiver Coombs-Test"],"gelegentlich":["Pilzinfektionen (Candidose)","Leukopenie, Neutropenie, Thrombozytopenie","Kopfschmerzen, Schwindel","Antibiotika-assoziierte Kolitis, Bauchschmerzen, Übelkeit, Erbrechen","Juckreiz, Fieber","Vorübergehender Anstieg der Nierenwerte"],"sehrSelten":["Interstitielle Nephritis (Nierenentzündung), akutes Nierenversagen"],"unbekannt":["Agranulozytose, hämolytische Anämie, Lymphozytose","Anaphylaxie (schwere allergische Reaktion bis zum Schock)","Neurologische Störungen bei eingeschränkter Nierenfunktion (Zittern, Muskelzuckungen, Krampfanfälle, Enzephalopathie, Koma)","Kribbeln (Parästhesien), Geschmacksstörung","Gelbsucht","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS), Angioödem"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; im Tierversuch keine Hinweise auf eine Schädigung, Erfahrungen beim Menschen begrenzt.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Wird im Spital als Injektion oder Infusion gegeben.","Bei eingeschränkter Nierenfunktion wird die Dosis angepasst; Verwirrtheit oder Muskelzuckungen sofort melden.","Allergien gegen Penicilline oder Cephalosporine vor der Behandlung angeben."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"ceftazidim-avibactam":{"wirkmechanismus":"Tötet Bakterien ab, auch solche, die gegen viele andere Antibiotika resistent sind. Ceftazidim hemmt als Cephalosporin die Penicillin-bindenden Proteine und damit den Aufbau der bakteriellen Zellwand. Avibactam hat keine eigene antibakterielle Wirkung, sondern blockiert Betalaktamasen, mit denen Bakterien Ceftazidim zerstören (ESBL, AmpC sowie KPC- und OXA-48-Carbapenemasen). Gegen Metallo-Betalaktamasen (z. B. NDM, VIM) wirkt die Kombination nicht.","nebenwirkungen":{"sehrHaeufig":["Positiver direkter Coombs-Test (Laborbefund)"],"haeufig":["Pilzinfektionen (Mund, Scheide)","Durchfall, Bauchschmerzen, Übelkeit, Erbrechen","Kopfschmerzen, Schwindel","Erhöhte Leberwerte","Hautausschlag, Juckreiz, Nesselsucht","Eosinophilie, Thrombozytose oder Thrombozytopenie","Venenentzündung oder Thrombose an der Infusionsstelle","Fieber"],"gelegentlich":["Clostridioides-difficile-Kolitis (schwere Darmentzündung)","Leukopenie, Neutropenie","Kribbeln (Parästhesien), Geschmacksstörungen","Erhöhtes Kreatinin, akute Nierenschädigung"],"sehrSelten":["Interstitielle Nephritis (Nierenentzündung)"],"unbekannt":["Anaphylaxie, Angioödem","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS","Agranulozytose, hämolytische Anämie","Gelbsucht"]},"schwangerschaft":"Begrenzte Erfahrungen; Tierversuche ohne Hinweis auf Schädigung. Nur anwenden, wenn der Nutzen das mögliche Risiko klar überwiegt.","stillzeit":"Ceftazidim geht in geringen Mengen in die Muttermilch über, für Avibactam ist es unbekannt. Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Wird im Spital als Infusion über 2 Stunden gegeben; die Dosis richtet sich nach der Nierenfunktion.","Starken oder blutigen Durchfall sofort melden, auch Wochen nach der Behandlung.","Kann den Coombs-Test positiv machen; vor Bluttransfusionen die Behandlung angeben."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"ceftolozan-tazobactam":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand stört. Ceftolozan ist ein Cephalosporin, das stark an die Penicillin-bindenden Proteine bindet und besonders gut gegen Pseudomonas aeruginosa wirkt, auch gegen viele multiresistente Stämme. Tazobactam hemmt bakterielle Betalaktamasen, vor allem ESBL, und schützt Ceftolozan so vor dem Abbau. Gegen Carbapenemasen wirkt die Kombination nicht.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel, Schlaflosigkeit, Angst","Übelkeit, Durchfall, Verstopfung, Erbrechen, Bauchschmerzen","Hypokaliämie (Kaliummangel)","Blutdruckabfall","Thrombozytose (Vermehrung der Blutplättchen)","Hautausschlag","Fieber, Reaktionen an der Infusionsstelle","Erhöhte Leberwerte"],"gelegentlich":["Clostridioides-difficile-Kolitis (schwere Darmentzündung)","Pilzinfektionen (Mund, Scheide, Harnwege)","Anämie","Vorhofflimmern, Herzrasen, Angina pectoris","Ischämischer Schlaganfall","Nierenfunktionsstörung bis Nierenversagen","Nesselsucht","Positiver Coombs-Test"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen. Nur anwenden, wenn der Nutzen das mögliche Risiko für Mutter und Kind überwiegt.","stillzeit":"Nicht bekannt, ob Ceftolozan und Tazobactam in die Muttermilch übergehen. Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Wird im Spital als Infusion über eine Stunde gegeben; die Dosis richtet sich nach der Nierenfunktion.","Starken oder blutigen Durchfall sofort melden, auch nach Behandlungsende."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"ceftriaxon":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Ceftriaxon hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es wirkt gegen viele grampositive und gramnegative Bakterien wie Pneumokokken, Streptokokken, Meningokokken, Gonokokken, Haemophilus und zahlreiche Darmbakterien und dringt gut in die Hirnhäute ein. Dank seiner langen Halbwertszeit (etwa 8 Stunden) genügt meist eine Gabe pro Tag; ausgeschieden wird es etwa je zur Hälfte über Niere und Galle. Gegen Pseudomonas, Enterokokken, MRSA und ESBL-Bildner ist es nicht zuverlässig wirksam.","nebenwirkungen":{"haeufig":["Eosinophilie, Leukopenie, Thrombozytopenie","Durchfall, weicher Stuhl","Anstieg der Leberwerte","Hautausschlag"],"gelegentlich":["Pilzinfektion im Genitalbereich","Granulozytopenie, Anämie, Gerinnungsstörung","Kopfschmerzen, Schwindel","Übelkeit, Erbrechen","Juckreiz","Venenentzündung, Schmerzen an der Einstichstelle, Fieber","Anstieg des Kreatinins (Nierenwert)"],"selten":["Pseudomembranöse Kolitis (schwere Darmentzündung)","Bronchospasmus (Verkrampfung der Atemwege)","Nesselsucht (Urtikaria)","Blut oder Zucker im Urin, Ödeme, Schüttelfrost"],"unbekannt":["Hämolytische Anämie (Blutzerfall, auch schwer), Agranulozytose","Anaphylaxie (schwere allergische Reaktion bis zum Schock), Kounis-Syndrom","Ceftriaxon-Calcium-Ablagerungen in Gallenblase und Nieren, Gallenkolik, Pankreatitis","Krampfanfälle, Enzephalopathie","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP, DRESS)","Kernikterus (Bilirubin-Hirnschädigung) bei Neugeborenen","Jarisch-Herxheimer-Reaktion bei Borreliose oder Syphilis"]},"schwangerschaft":"Passiert die Plazenta; nach ärztlicher Abwägung möglich, besonders im 1. Drittel nur bei klarer Notwendigkeit. Bisher keine Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung möglich (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Wird als Injektion oder Infusion gegeben; die Zubereitung mit Lidocain darf nur in den Muskel gespritzt werden.","Starke Schmerzen im rechten Oberbauch, Blässe, dunkler Urin oder Atemnot während der Behandlung sofort melden.","Bei längerer Behandlung wird das Blutbild kontrolliert; ausreichend trinken."],"darreichung":["Pulver zur Herstellung einer Injektions- oder Infusionslösung","Pulver mit Lidocain-haltigem Lösungsmittel zur Injektion in den Muskel"]},"cefuroxim":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Cefuroxim hemmt die Penicillin-bindenden Proteine und damit die Quervernetzung des Peptidoglykans (bakterizide Wirkung). Es ist gegen viele Beta-Laktamasen stabil und wirkt gegen Streptokokken, Methicillin-empfindliche Staphylokokken, Haemophilus influenzae, Moraxella sowie einen Teil der Darmbakterien wie E. coli. Die Tablettenform Cefuroxim-Axetil ist eine Vorstufe, die in der Darmwand zu Cefuroxim gespalten wird.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Durchfall, Übelkeit, Bauchschmerzen","Pilzinfektionen (z. B. Mund oder Scheide)","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Vorübergehender Anstieg der Leberwerte","Bei Infusion: Schmerzen oder Venenentzündung an der Einstichstelle"],"gelegentlich":["Erbrechen","Hautausschlag","Thrombozytopenie, Leukopenie","Positiver Coombs-Test"],"unbekannt":["Clostridioides-difficile-Infektion, pseudomembranöse Kolitis (schwere Darmentzündung)","Hämolytische Anämie (Blutzerfall)","Anaphylaxie, Arzneimittelfieber, Serumkrankheit","Jarisch-Herxheimer-Reaktion","Gelbsucht (meist durch Gallestau), Leberentzündung","Nesselsucht, Juckreiz, Angioödem","Schwere Hautreaktionen (Erythema multiforme, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Interstitielle Nephritis, Anstieg der Nierenwerte (Infusion)"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich; bisher keine Hinweise auf eine Schädigung des Kindes.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; Anwendung nach Abwägung möglich (beim Säugling Durchfall oder Pilzbefall möglich).","hinweise":["Tabletten nach einer Mahlzeit einnehmen – so werden sie besser aufgenommen; nicht zerkauen oder zerdrücken (sehr bitterer Geschmack).","Die verordnete Behandlungsdauer einhalten.","Kann Schwindel verursachen – Vorsicht beim Autofahren und Bedienen von Maschinen.","Bei Hautausschlag, Atemnot oder schwerem Durchfall ärztlichen Rat einholen."],"darreichung":["Filmtabletten","Granulat für Suspension zum Einnehmen","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"celecoxib":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen und schont dabei die Magenschleimhaut etwas mehr als herkömmliche NSAR. Celecoxib hemmt selektiv die Cyclooxygenase-2 (COX-2), die im entzündeten Gewebe Prostaglandine bildet; die für Magenschutz und Blutplättchen wichtige COX-1 wird in therapeutischer Dosis kaum gehemmt. Deshalb hemmt Celecoxib die Blutplättchen nicht und ersetzt keine Acetylsalicylsäure zum Herzschutz. Abgebaut wird es hauptsächlich über CYP2C9.","nebenwirkungen":{"haeufig":["Bluthochdruck","Dyspepsie (Verdauungsbeschwerden), Bauchschmerzen, Durchfall, Blähungen","Schwindel, Schlaflosigkeit","Hautausschlag, Juckreiz","Periphere Ödeme (Wassereinlagerungen)","Infekte der oberen Atemwege, Nasennebenhöhlenentzündung, Harnwegsinfekte"],"gelegentlich":["Anämie (Blutarmut)","Hyperkaliämie (erhöhtes Kalium)","Sehstörungen, Ohrensausen (Tinnitus)","Herzinsuffizienz, Herzklopfen","Erhöhte Leber- und Nierenwerte","Nesselsucht"],"selten":["Magen-Darm-Geschwüre, -Blutungen und -Durchbrüche","Pankreatitis (Bauchspeicheldrüsenentzündung), Hepatitis","Angioödem (Schwellung von Haut und Schleimhaut)","Blutbildveränderungen","Verwirrtheit","Akutes Nierenversagen"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Leberversagen","Hirnblutung"],"unbekannt":["Herzinfarkt und Schlaganfall (Risiko steigt mit Dosis und Behandlungsdauer)","Vorübergehend verminderte Fruchtbarkeit bei Frauen"]},"schwangerschaft":"Kontraindiziert. Frauen, die schwanger werden können, sollen während der Behandlung wirksam verhüten.","stillzeit":"Kontraindiziert; Celecoxib geht in geringen Mengen in die Muttermilch über.","hinweise":["Mit oder ohne Essen einnehmen; so niedrig dosiert und so kurz wie möglich.","Ersetzt keine Acetylsalicylsäure zum Schutz von Herz und Gefässen.","Blutdruck regelmässig kontrollieren.","Kann Schwindel verursachen – Vorsicht beim Autofahren."],"darreichung":["Kapseln"]},"celiprolol":{"wirkmechanismus":"Senkt Blutdruck und Puls, indem es die Wirkung von Stresshormonen am Herzen abschwächt. Celiprolol blockiert bevorzugt die Beta-1-Rezeptoren des Herzens und regt gleichzeitig in geringem Mass Beta-2-Rezeptoren an (partielle agonistische Aktivität), was die Gefässe leicht erweitert. Es wird kaum verstoffwechselt und weitgehend unverändert ausgeschieden.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Müdigkeit"],"unbekannt":["Übelkeit, Magen-Darm-Beschwerden","Schlafstörungen, depressive Verstimmung","Bradykardie (langsamer Puls), Blutdruckabfall","Bronchospasmus (Verkrampfung der Atemwege)","Kalte Hände und Füsse","Hautausschlag, Verschlechterung einer Psoriasis","Verdeckte Unterzuckerungszeichen bei Diabetes"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Betablocker können das Wachstum des Kindes vermindern und beim Neugeborenen langsamen Puls und Unterzuckerung verursachen.","stillzeit":"Nicht empfohlen bzw. nur nach strenger ärztlicher Abwägung; Säugling auf langsamen Puls und Unterzuckerung beobachten.","hinweise":["Morgens nüchtern, mindestens 30 Minuten vor oder 2 Stunden nach einer Mahlzeit mit Wasser einnehmen; nicht mit Grapefruit- oder Orangensaft.","Nicht abrupt absetzen, sondern ausschleichen.","Kann besonders zu Beginn und zusammen mit Alkohol die Fahrtüchtigkeit beeinträchtigen.","Vor Operationen die Behandlung angeben."],"darreichung":["Filmtabletten"]},"cemiplimab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, damit Abwehrzellen Krebszellen wieder bekämpfen. Cemiplimab ist ein humaner IgG4-Antikörper, der an den Rezeptor PD-1 auf T-Zellen bindet und dessen Aktivierung durch die Liganden PD-L1 und PD-L2 blockiert. Tumoren nutzen diese Liganden, um T-Zellen abzuschalten; die Blockade stellt die Immunantwort gegen den Tumor wieder her.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit","Muskel- und Gelenkschmerzen","Hautausschlag, Juckreiz","Durchfall, Übelkeit","Anämie (Blutarmut)","Appetitlosigkeit"],"haeufig":["Hypothyreose, Hyperthyreose (Schilddrüsenunter- und -überfunktion)","Pneumonitis (nicht-infektiöse Lungenentzündung)","Kolitis (Dickdarmentzündung)","Hepatitis, erhöhte Leberwerte","Infusionsreaktionen","Stomatitis (Mundschleimhautentzündung)","Husten, Atemnot"],"gelegentlich":["Nebenniereninsuffizienz, Hypophysitis, Thyreoiditis","Typ-1-Diabetes","Nephritis (Nierenentzündung)","Myokarditis (Herzmuskelentzündung)","Periphere Neuropathie, Arthritis"],"unbekannt":["Myasthenia gravis, Meningitis, Enzephalitis","Abstossung transplantierter Organe"]},"schwangerschaft":"Nicht empfohlen: IgG-Antikörper gehen über die Plazenta, und die PD-1-Blockade kann die Toleranz gegenüber dem Ungeborenen stören. Frauen im gebärfähigen Alter verhüten während der Behandlung und mindestens 4 Monate danach.","stillzeit":"Während der Behandlung und mindestens 4 Monate nach der letzten Dosis nicht stillen.","hinweise":["Neue Beschwerden wie Durchfall, Husten, Atemnot, Gelbsucht, starke Müdigkeit, Kopfschmerzen oder Hautausschlag sofort melden – auch Monate nach Therapieende.","Den Patientenausweis immer bei sich tragen und allen Ärztinnen und Ärzten zeigen.","Leber-, Nieren- und Schilddrüsenwerte sowie Blutzucker werden regelmässig kontrolliert.","Kortison nicht eigenmächtig beginnen oder absetzen."],"darreichung":["Infusionskonzentrat"]},"cenobamat":{"wirkmechanismus":"Dämpft die übermässige Erregbarkeit von Nervenzellen im Gehirn. Cenobamat hemmt bevorzugt den anhaltenden (persistierenden) Natriumstrom in Nervenzellen und verstärkt als positiver Modulator die hemmende Wirkung von GABA am GABA-A-Rezeptor. Beides zusammen vermindert die Anfallsbereitschaft.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit","Schwindel","Müdigkeit","Kopfschmerzen"],"haeufig":["Doppelbilder, verschwommenes Sehen","Gangunsicherheit (Ataxie), Gleichgewichts- und Koordinationsstörungen, undeutliche Sprache","Nystagmus (Augenzittern), Gedächtnisstörungen","Verwirrtheit, Reizbarkeit","Übelkeit, Erbrechen, Verstopfung, Durchfall, Mundtrockenheit","Hautausschlag, Juckreiz","Erhöhte Leberwerte"],"gelegentlich":["Überempfindlichkeitsreaktionen","Suizidgedanken"],"selten":["DRESS (Arzneimittelreaktion mit Fieber, Ausschlag und Organbeteiligung)"],"unbekannt":["Verkürzung der QT-Zeit im EKG"]},"schwangerschaft":"Nicht empfohlen bei Frauen im gebärfähigen Alter ohne wirksame Verhütung; in der Schwangerschaft nur nach sorgfältiger ärztlicher Abwägung.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen; während der Behandlung nicht stillen.","hinweise":["Das langsame Aufdosierungsschema über mehrere Monate genau einhalten (Schutz vor DRESS).","Bei Fieber, Hautausschlag oder geschwollenen Lymphknoten sofort ärztlich abklären.","Nicht abrupt absetzen; Alkohol meiden, die Fahrtüchtigkeit kann beeinträchtigt sein."],"darreichung":["Filmtabletten"]},"ceritinib":{"wirkmechanismus":"Blockiert gezielt das veränderte Wachstumssignal-Enzym ALK in Lungenkrebszellen. Ceritinib ist ein ALK-Hemmer der zweiten Generation, der ALK deutlich stärker hemmt als Crizotinib und auch gegen viele Crizotinib-Resistenzmutationen wirkt; zusätzlich hemmt es den IGF-1-Rezeptor. Die Hemmung der ALK-Fusionsproteine unterbricht Signalwege für Wachstum und Überleben der Tumorzellen.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen, Bauchschmerzen","Müdigkeit, Appetitlosigkeit, Gewichtsverlust","Verstopfung, Speiseröhrenbeschwerden (Sodbrennen, Schluckbeschwerden)","Hautausschlag","Erhöhte Leberwerte","Erhöhtes Kreatinin","Blutarmut (Anämie)"],"haeufig":["Erhöhter Blutzucker, tiefes Phosphat im Blut","Langsamer Puls (Bradykardie), QT-Verlängerung im EKG","Herzbeutelerguss, Herzbeutelentzündung (Perikarditis)","Interstitielle Lungenerkrankung, Pneumonitis","Sehstörungen","Nierenfunktionsstörung","Erhöhte Lipase und Amylase"],"gelegentlich":["Leberschädigung (Hepatotoxizität)","Pankreatitis (Bauchspeicheldrüsenentzündung)"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig. Frauen im gebärfähigen Alter müssen während und bis 3 Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit mit einer Mahlzeit einnehmen; keine Grapefruit und kein Johanniskraut.","Durchfall, Übelkeit oder Erbrechen früh behandeln und ärztlich melden.","Leberwerte, Blutzucker, Puls und EKG regelmässig kontrollieren lassen."],"darreichung":["Filmtabletten"]},"cerliponase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das in Nervenzellen Eiweissabbauprodukte zerlegt, und verlangsamt so den Verlust der Geh- und Sprechfähigkeit. Cerliponase alfa ist die gentechnisch hergestellte inaktive Vorstufe (Proenzym) der menschlichen Tripeptidylpeptidase 1. Sie wird über ein unter der Kopfhaut implantiertes Reservoir mit Katheter in die Hirnkammern gegeben, über Mannose-6-Phosphat-Rezeptoren von Nervenzellen aufgenommen und in den Lysosomen aktiviert. Dort spaltet sie Tripeptide von Eiweissen ab und vermindert die Ablagerung von Speichermaterial.","nebenwirkungen":{"sehrHaeufig":["Fieber","Erbrechen","Überempfindlichkeitsreaktionen","Krampfanfälle","Kopfschmerzen","Reizbarkeit","EKG-Veränderungen","Veränderungen im Hirnwasser (erhöhte Zellzahl, verändertes Eiweiss)"],"haeufig":["Infektionen des Zugangssystems, Hirnhautentzündung","Probleme mit dem Zugangssystem (Leck, Verstopfung, Nadelprobleme)","Bradykardie (langsamer Puls)"]},"schwangerschaft":"Keine Erfahrungen. Nur anwenden, wenn eindeutig nötig.","stillzeit":"Keine Daten. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen über mehrere Stunden in einem spezialisierten Zentrum über das implantierte Reservoir gegeben; das Zugangssystem wird regelmässig geprüft und bei Bedarf ersetzt.","Fieber, Kopfschmerzen, Nackensteife, Rötung oder Flüssigkeitsaustritt am Reservoir sofort melden.","Herz und Kreislauf werden während jeder Gabe überwacht."],"darreichung":["Infusionslösung zur Gabe in die Hirnkammern (intraventrikulär)"]},"certolizumab-pegol":{"wirkmechanismus":"Hemmt den Entzündungsbotenstoff TNF-alpha, der bei vielen Autoimmunerkrankungen die Entzündung antreibt. Certolizumab Pegol ist ein humanisiertes Antikörperfragment (Fab'), das an Polyethylenglykol gekoppelt ist und deshalb lange im Körper verbleibt. Es bindet lösliches und membranständiges TNF-alpha und neutralisiert es. Da ihm der Fc-Teil fehlt, gelangt es kaum über die Plazenta zum Kind.","nebenwirkungen":{"haeufig":["Bakterielle Infektionen (inkl. Abszess), Virusinfektionen (Herpes, Grippe, Papillomaviren)","Eosinophilie, Leukopenie (inkl. Neutropenie und Lymphopenie)","Kopfschmerzen (inkl. Migräne), Empfindungsstörungen","Bluthochdruck","Übelkeit","Leberentzündung, erhöhte Leberwerte","Hautausschlag, Juckreiz","Fieber, Schmerzen, Schwäche, Reaktionen an der Injektionsstelle"],"gelegentlich":["Sepsis, Tuberkulose, Pilzinfektionen und andere opportunistische Infektionen","Lymphome und andere bösartige Erkrankungen, Hautkrebs (ausser Melanom)","Anämie (Blutarmut), Thrombozytopenie (Mangel an Blutplättchen)","Herzinsuffizienz, Herzrhythmusstörungen","Lupus-ähnliche Reaktionen, Gefässentzündung (Vaskulitis)","Überempfindlichkeitsreaktionen"],"unbekannt":["Demyelinisierende Erkrankungen (z. B. Multiple Sklerose, Guillain-Barré-Syndrom)","Panzytopenie","Hepatitis-B-Reaktivierung","Merkelzellkarzinom","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)"]},"schwangerschaft":"Kann nach ärztlicher Abwägung während der Schwangerschaft angewendet werden, da kaum Wirkstoff über die Plazenta zum Kind gelangt.","stillzeit":"Geht nur in sehr geringer Menge in die Muttermilch über; Stillen ist möglich.","hinweise":["Vor Beginn Tuberkulose- und Hepatitis-B-Test; Impfungen möglichst vorher auffrischen.","Fieber, anhaltender Husten, Gewichtsverlust oder andere Infektzeichen sofort ärztlich melden.","Im Kühlschrank lagern; vor der Injektion auf Raumtemperatur bringen.","Kann gewisse Gerinnungstests (aPTT) falsch verlängert erscheinen lassen – Labor informieren."],"darreichung":["Injektionslösung in Fertigspritze oder Fertigpen (subkutan)"]},"cetirizin":{"wirkmechanismus":"Blockiert die Wirkung von Histamin, das bei allergischen Reaktionen Niesen, Juckreiz, Quaddeln und tränende Augen auslöst. Cetirizin ist ein selektiver Antagonist an peripheren Histamin-H1-Rezeptoren und der wirksame Hauptmetabolit von Hydroxyzin. Es gelangt nur in geringem Mass ins Gehirn und wirkt kaum anticholinerg; deshalb macht es weniger müde als ältere Antihistaminika. Es wird grösstenteils unverändert über die Nieren ausgeschieden.","nebenwirkungen":{"haeufig":["Müdigkeit, Schläfrigkeit (Somnolenz)","Kopfschmerzen","Schwindel","Mundtrockenheit","Übelkeit","Rachenentzündung (Pharyngitis)"],"gelegentlich":["Unruhe (Agitiertheit)","Kribbeln (Parästhesien)","Bauchschmerzen, Durchfall","Juckreiz, Hautausschlag","Schwäche (Asthenie), Unwohlsein"],"selten":["Überempfindlichkeitsreaktionen","Aggressivität, Verwirrtheit, Depression, Halluzinationen, Schlaflosigkeit","Krampfanfälle","Herzrasen (Tachykardie)","Abweichende Leberwerte","Nesselsucht, Ödeme (Wassereinlagerungen), Gewichtszunahme"],"sehrSelten":["Anaphylaktischer Schock","Thrombozytopenie (Mangel an Blutplättchen)","Ohnmacht (Synkope), Zittern, Geschmacksstörungen, Tics","Sehstörungen (Akkommodationsstörungen, verschwommenes Sehen)","Angioödem (Schwellung von Haut und Schleimhäuten), fixes Arzneimittelexanthem","Schmerzhaftes Wasserlassen, Einnässen"],"unbekannt":["Harnverhalt","Juckreiz nach dem Absetzen","Suizidgedanken, Albträume, Gedächtnisstörungen","Gelenk- und Muskelschmerzen","Akute generalisierte exanthematische Pustulose (AGEP, schwere Hautreaktion)","Hepatitis (Leberentzündung)","Appetitsteigerung"]},"schwangerschaft":"Umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko. Trotzdem nur nach ärztlicher Abwägung anwenden.","stillzeit":"Geht in die Muttermilch über. Nur nach ärztlicher Abwägung anwenden und beim Säugling auf Schläfrigkeit achten.","hinweise":["Kann trotz geringer Sedierung die Reaktionsfähigkeit beeinträchtigen – die eigene Reaktion vor dem Autofahren prüfen; Alkohol meiden.","Vor Allergie-Hauttests 3 Tage absetzen, sonst können die Resultate falsch negativ ausfallen.","Bei eingeschränkter Nierenfunktion ist eine tiefere Dosis nötig."],"darreichung":["Filmtabletten","Tropfen zum Einnehmen"]},"cetrorelix":{"wirkmechanismus":"Verhindert, dass der Eisprung zu früh ausgelöst wird, bevor die Eizellen entnommen werden können. Cetrorelix blockiert als Gegenspieler (Antagonist) die GnRH-Rezeptoren der Hirnanhangdrüse und unterdrückt so rasch und umkehrbar die Ausschüttung von luteinisierendem Hormon (LH) und follikelstimulierendem Hormon (FSH). Anders als GnRH-Agonisten löst es keinen anfänglichen Hormonanstieg aus.","nebenwirkungen":{"haeufig":["Leichte, vorübergehende Reaktionen an der Einstichstelle (Rötung, Schwellung, Juckreiz)","Leichtes bis mittelschweres ovarielles Überstimulationssyndrom"],"gelegentlich":["Allergische oder allergieähnliche Allgemeinreaktionen bis zur lebensbedrohlichen Anaphylaxie","Kopfschmerzen","Übelkeit","Schweres ovarielles Überstimulationssyndrom"]},"schwangerschaft":"Kontraindiziert; die Behandlung erfolgt vor einer möglichen Schwangerschaft.","stillzeit":"Kontraindiziert.","hinweise":["Einmal täglich etwa zur gleichen Tageszeit unter die Haut des Unterbauchs spritzen; Einstichstelle wechseln.","Vergessene Dosen sofort dem Behandlungsteam melden – es droht ein vorzeitiger Eisprung."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (Anwendung unter die Haut)"]},"cetuximab":{"wirkmechanismus":"Blockiert eine Antenne für Wachstumssignale auf Krebszellen. Cetuximab ist ein chimärer IgG1-Antikörper, der an den epidermalen Wachstumsfaktor-Rezeptor (EGFR) bindet und so die Bindung von Wachstumsfaktoren wie EGF und TGF-alpha verhindert. Dadurch werden Zellteilung, Gefässneubildung und Metastasierung gehemmt, und der Rezeptor wird abgebaut; zusätzlich lenkt der Antikörper Immunzellen gegen den Tumor. Bei RAS-Mutation ist der Signalweg unterhalb des Rezeptors dauerhaft aktiv – dann wirkt Cetuximab nicht.","nebenwirkungen":{"sehrHaeufig":["Hautreaktionen (akneartiger Ausschlag, trockene Haut, Juckreiz, Nagelbettentzündung)","Hypomagnesiämie (Magnesiummangel)","Leichte bis mässige Infusionsreaktionen (Fieber, Schüttelfrost, Atemnot)","Mukositis (Schleimhautentzündung)","Erhöhte Leberwerte"],"haeufig":["Schwere Infusionsreaktionen, selten tödlich","Konjunktivitis (Bindehautentzündung)","Kopfschmerzen","Durchfall, Übelkeit, Erbrechen","Dehydratation (Flüssigkeitsverlust), Hypokaliämie, Hypokalzämie","Appetitlosigkeit, Müdigkeit"],"gelegentlich":["Tiefe Venenthrombose, Lungenembolie","Blepharitis, Keratitis (Lid- und Hornhautentzündung)"],"sehrSelten":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)"],"unbekannt":["Interstitielle Lungenerkrankung","Aseptische Meningitis (Hirnhautentzündung ohne Erreger)","Superinfektion von Hautveränderungen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung: EGFR ist an der Entwicklung des Ungeborenen beteiligt, und IgG1-Antikörper gehen über die Plazenta. Frauen im gebärfähigen Alter verhüten zuverlässig.","stillzeit":"Während der Behandlung und 2 Monate nach der letzten Dosis nicht stillen.","hinweise":["Vor der Infusion gibt es ein Antihistaminikum und Kortison; danach folgt mindestens eine Stunde Überwachung.","Sonne meiden und Sonnenschutz verwenden; Hautausschlag früh nach ärztlicher Anweisung behandeln.","Augenrötung, Augenschmerzen oder Sehstörungen sofort melden.","Magnesium, Kalium und Calcium werden regelmässig im Blut kontrolliert."],"darreichung":["Infusionslösung"]},"chenodesoxycholsaeure":{"wirkmechanismus":"Ersetzt eine Gallensäure, die der Körper bei der zerebrotendinösen Xanthomatose nicht ausreichend bilden kann. Wegen des angeborenen Mangels am Enzym Sterol-27-Hydroxylase (CYP27A1) entstehen statt normaler Gallensäuren Zwischenprodukte wie Cholestanol und Gallenalkohole, die sich in Gehirn, Nerven, Sehnen und Augenlinse ablagern. Zugeführte Chenodesoxycholsäure hemmt über eine Rückkopplung das Schlüsselenzym der Gallensäurebildung (Cholesterin-7α-Hydroxylase, CYP7A1) und senkt so die Bildung dieser schädlichen Stoffe.","nebenwirkungen":{"unbekannt":["Obstipation (Verstopfung)","Durchfall, vor allem bei höheren Dosen","Erhöhte Leberwerte (Transaminasen) bis zur Leberschädigung"]},"schwangerschaft":"Nicht empfohlen: nur sehr begrenzte Erfahrungen, Tierversuche zeigten schädliche Wirkungen. Während der Behandlung zuverlässig verhüten.","stillzeit":"Nicht ausreichend untersucht; Nutzen und Risiko ärztlich abwägen.","hinweise":["Langzeitbehandlung: Leberwerte und Cholestanol im Blut regelmässig kontrollieren lassen.","Gallensäurebinder und aluminiumhaltige Säurebinder zeitversetzt einnehmen."],"darreichung":["Hartkapseln"]},"chlorambucil":{"wirkmechanismus":"Hemmt das Wachstum von Krebszellen, indem es ihr Erbgut schädigt. Chlorambucil ist ein aromatisches Stickstofflost-Derivat und wirkt als bifunktionelles Alkylans: Es verknüpft die beiden DNA-Stränge miteinander (Quervernetzung) und verhindert so das Ablesen und Verdoppeln der DNA, was zum Zelltod führt. Auch der Hauptmetabolit Phenylessigsäure-Lost ist wirksam. Besonders empfindlich sind sich rasch teilende Zellen wie Lymphozyten und Knochenmarkzellen.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung: Leukopenie, Neutropenie (Mangel an weissen Blutkörperchen), Thrombozytopenie (Mangel an Blutplättchen), Panzytopenie"],"haeufig":["Anämie (Blutarmut)","Übelkeit, Erbrechen, Durchfall","Mundgeschwüre","Krampfanfälle bei Kindern mit nephrotischem Syndrom","Akute Leukämie und Myelodysplasie als Zweiterkrankung (v. a. nach Langzeitbehandlung)"],"gelegentlich":["Hautausschlag"],"selten":["Allergische Reaktionen (Nesselsucht, Angioödem)","Krampfanfälle bei Kindern und Erwachsenen","Leberschäden, Gelbsucht","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Arzneimittelfieber"],"sehrSelten":["Bleibende Knochenmarkschädigung","Interstitielle Lungenfibrose und Lungenentzündung","Bewegungsstörungen (Zittern, Muskelzuckungen) und periphere Neuropathie (Nervenschäden)","Nicht-infektiöse Blasenentzündung"],"unbekannt":["Unfruchtbarkeit (fehlende Spermienbildung, Ausbleiben der Menstruation)"]},"schwangerschaft":"Nicht anwenden: Chlorambucil kann das ungeborene Kind schädigen. Frauen und Männer müssen während der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Tabletten ganz schlucken, nicht teilen oder zerkleinern; im Kühlschrank (2–8 °C) lagern.","Regelmässige Blutbildkontrollen sind nötig; bei Fieber, Halsschmerzen, Blutungen oder blauen Flecken sofort ärztliche Hilfe holen.","Keine Lebendimpfungen während der Behandlung.","Vor Behandlungsbeginn Möglichkeiten zum Fruchtbarkeitserhalt besprechen."],"darreichung":["Filmtabletten"]},"chlorhexidin":{"wirkmechanismus":"Tötet Bakterien ab und hemmt Pilze auf Haut und Schleimhaut. Das positiv geladene Chlorhexidin bindet an die negativ geladene Zellwand der Mikroorganismen, macht die Zellmembran durchlässig und führt in höherer Konzentration zum Absterben der Keime. Es wirkt besonders gut gegen grampositive, etwas schwächer gegen gramnegative Bakterien und Hefepilze, gegen Sporen kaum. Weil es an Zähnen und Schleimhaut haftet und langsam wieder freigesetzt wird, hält die Wirkung im Mund mehrere Stunden an (Depotwirkung).","nebenwirkungen":{"haeufig":["Bräunliche Verfärbungen von Zähnen, Füllungen, Prothesen und Zunge (rückbildungsfähig, durch professionelle Zahnreinigung entfernbar)","Belegte Zunge","Vorübergehende Geschmacksstörungen","Brennen oder Taubheitsgefühl der Zunge"],"selten":["Überempfindlichkeitsreaktionen der Haut (Ausschlag, Rötung, Juckreiz)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion bis zum Schock)"],"unbekannt":["Reizung oder Abschuppung der Mundschleimhaut","Rückbildungsfähige Schwellung der Ohrspeicheldrüse","Vermehrte Zahnsteinbildung","Hautreizung oder Kontaktekzem bei Anwendung auf der Haut","Hautverätzungen bei Frühgeborenen"]},"schwangerschaft":"Bei Anwendung im Mund oder auf der Haut wird kaum Wirkstoff ins Blut aufgenommen; die Anwendung in der Schwangerschaft ist möglich.","stillzeit":"Anwendung in der Stillzeit möglich; nicht im Bereich der Brust anwenden, damit der Säugling den Wirkstoff nicht aufnimmt.","hinweise":["Mundspülung nach dem Spülen ausspucken und nicht schlucken; nicht unmittelbar nach dem Zähneputzen anwenden.","Kaffee, Tee, Rotwein und Rauchen verstärken die Verfärbungen der Zähne.","Ohne zahnärztlichen Rat die Mundspülung nicht länger als etwa 2 Wochen anwenden.","Bei Kontakt mit den Augen sofort gründlich mit Wasser spülen."],"darreichung":["Mundspüllösung","Lösung und Spray zur Haut- und Wunddesinfektion","Crème und Spray (Kombination mit Dexpanthenol)"]},"chlormethin":{"wirkmechanismus":"Hemmt das Wachstum der krankhaften Immunzellen (T-Lymphozyten) in der Haut. Chlormethin ist ein bifunktionelles Alkylans aus der Gruppe der Stickstofflost-Verbindungen: Es verknüpft die DNA-Stränge sich rasch teilender Zellen miteinander und verhindert so deren Vermehrung. Als Gel aufgetragen wirkt es örtlich; ins Blut gelangen nur sehr geringe Mengen.","nebenwirkungen":{"sehrHaeufig":["Dermatitis (Hautentzündung mit Rötung, Reizung, Schuppung)","Juckreiz"],"haeufig":["Hautinfektionen","Hautgeschwüre und Blasen","Dunkelfärbung der Haut (Hyperpigmentierung)","Überempfindlichkeitsreaktionen"],"unbekannt":["Heller Hautkrebs (nicht-melanozytärer Hautkrebs)"]},"schwangerschaft":"Nicht anwenden: Chlormethin kann das ungeborene Kind schädigen. Frauen im gebärfähigen Alter müssen sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich dünn auf die trockene Haut auftragen und danach sofort Hände waschen; wer das Gel bei jemand anderem aufträgt, trägt Einweg-Nitrilhandschuhe.","Nach dem Auftragen 5–10 Minuten trocknen lassen und mindestens 4 Stunden nicht duschen oder baden.","Das Gel ist brennbar: bis zum Trocknen offenes Feuer, Flammen und Rauchen meiden.","Im Kühlschrank (2–8 °C) lagern; Kontakt mit Augen und Schleimhäuten vermeiden."],"darreichung":["Gel"]},"chloroprocain":{"wirkmechanismus":"Betäubt vorübergehend die Nerven im behandelten Gebiet, sodass Schmerzreize nicht mehr weitergeleitet werden. Chloroprocain blockiert spannungsabhängige Natriumkanäle der Nervenmembran und verhindert so die Entstehung und Weiterleitung von Aktionspotenzialen. Als Lokalanästhetikum vom Ester-Typ wird es im Blut sehr rasch durch die Plasmacholinesterase (Pseudocholinesterase) gespalten; daraus ergeben sich der schnelle Wirkungseintritt, die kurze Wirkdauer und ein geringes Risiko einer Anreicherung. Beim Abbau entsteht 4-Amino-2-chlorbenzoesäure, ein Verwandter der Para-Aminobenzoesäure (PABA).","nebenwirkungen":{"haeufig":["Hypotonie (Blutdruckabfall)","Übelkeit","Erbrechen"],"selten":["Allergische Reaktionen bis Anaphylaxie (schwerer allergischer Schock)","Krampfanfälle bei zu hohen Blutspiegeln","Herzrhythmusstörungen bis Herzstillstand","Nervenschäden, Lähmungen (z. B. Cauda-equina-Syndrom) nach rückenmarksnaher Betäubung"],"unbekannt":["Bradykardie (langsamer Puls)","Schwindel","Kopfschmerzen nach Spinalanästhesie","Parästhesien (Kribbeln, Taubheitsgefühl)"]},"schwangerschaft":"Keine ausreichenden Daten; nur nach strenger ärztlicher Abwägung anwenden. Wegen des sehr raschen Abbaus gelangt wenig Wirkstoff zum Kind.","stillzeit":"Ungenügende Daten; wegen des sehr raschen Abbaus gilt das Risiko für den Säugling als gering – Vorgehen mit der Ärztin oder dem Arzt besprechen.","hinweise":["Wird nur von Fachpersonen im Spital oder in der Praxis mit Notfallausrüstung angewendet.","Nach einer Spinalanästhesie erst aufstehen, Auto fahren oder Maschinen bedienen, wenn Gefühl und Kraft vollständig zurückgekehrt sind und die Ärztin oder der Arzt es erlaubt.","Allergien auf Lokalanästhetika sowie die Einnahme von Blutverdünnern vor dem Eingriff angeben."],"darreichung":["Injektionslösung (intrathekal)","Injektionslösung (perineural)"]},"chlorprothixen":{"wirkmechanismus":"Beruhigt und dämpft Erregung und psychotische Symptome. Chlorprothixen ist ein niederpotentes Thioxanthen-Neuroleptikum: Es blockiert Dopamin-D1- und D2-Rezeptoren nur mässig, dafür stark Histamin-H1-, Alpha-1-adrenerge, Muskarin- und Serotonin-5-HT2-Rezeptoren. Daraus ergeben sich die ausgeprägte Sedierung, der Blutdruckabfall und anticholinerge Wirkungen, während Bewegungsstörungen seltener sind als bei hochpotenten Neuroleptika.","nebenwirkungen":{"unbekannt":["Starke Müdigkeit, Benommenheit, Schwindel","Mundtrockenheit, Verstopfung, Sehstörungen, Harnverhalt (anticholinerge Wirkungen)","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Herzrasen","Gewichtszunahme, vermehrtes Schwitzen","Bewegungsstörungen (Zittern, Muskelsteifigkeit, Sitzunruhe), Spätdyskinesien, Krampfanfälle","QT-Verlängerung, Torsade de pointes (lebensgefährliche Herzrhythmusstörung)","Blutbildveränderungen bis Agranulozytose, Gelbsucht","Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung), venöse Thromboembolien"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen, Schläfrigkeit und Entzugssymptome auftreten.","stillzeit":"Geht in die Muttermilch über; nur nach ärztlicher Abwägung stillen und das Kind auf Schläfrigkeit beobachten.","hinweise":["Wirkt stark beruhigend: nicht Auto fahren, besonders zu Beginn, und keinen Alkohol trinken.","Langsam aufstehen – Gefahr von Schwindel und Stürzen durch Blutdruckabfall.","Bei Fieber mit Muskelsteifigkeit und Verwirrtheit sofort ärztliche Hilfe holen (malignes neuroleptisches Syndrom)."],"darreichung":["Filmtabletten"]},"chlortalidon":{"wirkmechanismus":"Fördert die Ausscheidung von Salz und Wasser über die Niere und senkt so den Blutdruck. Chlortalidon hemmt wie die Thiazide den Natrium-Chlorid-Cotransporter im frühdistalen Tubulus; dadurch werden mehr Natrium, Chlorid und Wasser, aber auch Kalium und Magnesium ausgeschieden, Calcium dagegen zurückgehalten. Die Dauerwirkung auf den Blutdruck beruht zusätzlich auf einer Abnahme des Gefässwiderstands. Wegen der sehr langen Halbwertszeit von rund 50 Stunden (Bindung an die roten Blutkörperchen) hält die Wirkung 48–72 Stunden an.","nebenwirkungen":{"sehrHaeufig":["Hypokaliämie (Kaliummangel)","Hyperurikämie (erhöhte Harnsäure)","Erhöhte Blutfette, vor allem bei höheren Dosen"],"haeufig":["Hyponatriämie (Natriummangel), Hypomagnesiämie (Magnesiummangel)","Hyperglykämie (erhöhter Blutzucker)","Nesselsucht und andere Hautausschläge","Orthostatische Hypotonie (Schwindel beim Aufstehen), verstärkt durch Alkohol oder Beruhigungsmittel","Appetitlosigkeit, leichte Magen-Darm-Beschwerden","Erektionsstörungen","Schwindel"],"selten":["Hyperkalzämie (erhöhtes Calcium)","Verschlechterung eines Diabetes, Zucker im Urin, Gichtanfälle","Photosensibilität (Lichtempfindlichkeit der Haut)","Herzrhythmusstörungen","Übelkeit, Erbrechen, Bauchschmerzen, Verstopfung, Durchfall","Gallenstau in der Leber (intrahepatische Cholestase), Gelbsucht","Kopfschmerzen, Kribbeln (Parästhesien), Sehstörungen","Thrombozytopenie, Leukopenie, Agranulozytose, Eosinophilie"],"sehrSelten":["Hypochlorämische Alkalose","Pankreatitis (Bauchspeicheldrüsenentzündung)","Lungenödem als Überempfindlichkeitsreaktion","Allergische interstitielle Nephritis (Nierenentzündung)","Vaskulitis (Gefässentzündung)"],"unbekannt":["Akute Kurzsichtigkeit, Aderhauterguss, akutes Engwinkelglaukom"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit; nicht bei schwangerschaftsbedingten Ödemen, Bluthochdruck oder Präeklampsie, da es die Durchblutung der Plazenta vermindern und beim Neugeborenen Gelbsucht, Elektrolytstörungen und Blutplättchenmangel verursachen kann.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen; in der Stillzeit nicht anwenden.","hinweise":["Am Morgen einnehmen; die Wirkung hält 2–3 Tage an, deshalb kann sie nach dem Absetzen noch nachwirken.","Kalium, Natrium, Nierenwerte, Harnsäure und Blutzucker regelmässig kontrollieren lassen; bei Erbrechen, Durchfall oder starkem Schwitzen ärztlichen Rat einholen.","Haut vor starker Sonne schützen (Lichtempfindlichkeit).","Bei plötzlicher Sehverschlechterung oder Augenschmerzen sofort ärztliche Hilfe suchen."],"darreichung":["Tabletten"]},"cholera-impfstoff":{"wirkmechanismus":"Regt das Immunsystem des Darms an, Abwehrstoffe gegen den Cholera-Erreger zu bilden. Der Impfstoff enthält abgetötete Vibrio-cholerae-O1-Bakterien (Serotypen Inaba und Ogawa, klassischer und El-Tor-Biotyp) sowie die gentechnisch hergestellte, ungiftige B-Untereinheit des Choleratoxins. Er bewirkt die Bildung von IgA-Antikörpern in der Darmschleimhaut gegen die Bakterien und gegen das Toxin. Der Schutz beginnt etwa eine Woche nach Abschluss der Grundimmunisierung.","nebenwirkungen":{"gelegentlich":["Durchfall, Bauchschmerzen, Bauchkrämpfe, Darmgeräusche, Blähungen","Kopfschmerzen"],"selten":["Fieber, Unwohlsein","Schwindel","Übelkeit, Erbrechen, Appetitlosigkeit","Atemwegsbeschwerden (Schnupfen, Husten)"],"sehrSelten":["Hautausschlag","Gelenkschmerzen"],"unbekannt":["Lymphknotenentzündung","Kribbeln (Parästhesien)","Blutdruckanstieg","Atemnot","Nesselsucht, Angioödem, Juckreiz","Grippeähnliche Beschwerden"]},"schwangerschaft":"Keine ausreichenden Daten. Da der Impfstoff abgetötete Erreger enthält und nur im Darm wirkt, ist ein Risiko unwahrscheinlich; Anwendung nach ärztlicher Nutzen-Risiko-Abwägung.","stillzeit":"Kann nach ärztlicher Abwägung angewendet werden.","hinweise":["Brausegranulat in kühlem Wasser auflösen und mit der Impfsuspension mischen; die Anleitung der Packungsbeilage genau befolgen.","1 Stunde vor und nach der Einnahme nichts essen, trinken oder andere Medikamente einnehmen.","Mehrere Dosen sind nötig: Grundimmunisierung rechtzeitig vor der Abreise vollständig abschliessen."],"darreichung":["Suspension und Brausegranulat zum Einnehmen"]},"chondroitinsulfat":{"wirkmechanismus":"Soll den Gelenkknorpel unterstützen und Arthroseschmerzen langsam lindern. Chondroitinsulfat ist ein natürlicher Bestandteil der Knorpelgrundsubstanz (Glykosaminoglykan). Es fördert die Bildung von Knorpelmatrix und hemmt knorpelabbauende Enzyme sowie Entzündungsbotenstoffe im Gelenk. Die Wirkung setzt erst nach einigen Wochen ein und hält nach dem Absetzen eine Zeit lang an.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden wie Übelkeit, Bauchschmerzen oder Durchfall","Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Angioödem (Schwellung von Haut und Schleimhäuten)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; in der Schwangerschaft nur nach ärztlicher Abwägung anwenden.","stillzeit":"Keine Daten zum Übergang in die Muttermilch; in der Stillzeit nicht empfohlen.","hinweise":["Die Wirkung setzt erst nach einigen Wochen ein; die Behandlung erfolgt über mehrere Monate.","Bei akuten Schmerzschüben kann zusätzlich ein Schmerzmittel nötig sein – ärztlich oder in der Apotheke besprechen.","Bei Einnahme von Phenprocoumon oder Acenocoumarol die Gerinnungswerte kontrollieren lassen."],"darreichung":["Kapseln","Tabletten"]},"choriongonadotropin":{"wirkmechanismus":"Löst den Eisprung aus, nachdem die Eibläschen (Follikel) herangereift sind. Choriongonadotropin wirkt wie das körpereigene luteinisierende Hormon (LH) am LH/hCG-Rezeptor: Es bewirkt die abschliessende Reifung der Eizelle, den Eisprung und die Bildung des Gelbkörpers. Beim Mann regt es die Leydig-Zellen im Hoden zur Bildung von Testosteron an. Ovitrelle enthält gentechnisch hergestelltes hCG (Choriogonadotropin alfa), Pregnyl und Brevactid aus dem Urin schwangerer Frauen gewonnenes hCG.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Müdigkeit","Reaktionen an der Einstichstelle (Schmerzen, Rötung, Schwellung)","Übelkeit, Erbrechen, Bauchschmerzen","Leichtes bis mittelschweres ovarielles Überstimulationssyndrom (OHSS)"],"gelegentlich":["Durchfall","Depression, Reizbarkeit, Unruhe","Brustschmerzen","Schweres ovarielles Überstimulationssyndrom"],"sehrSelten":["Thromboembolie (meist zusammen mit schwerem OHSS)","Überempfindlichkeitsreaktionen bis Anaphylaxie, Hautausschlag"],"unbekannt":["Männer: Wassereinlagerungen, Brustvergrösserung (Gynäkomastie), Akne"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft. Nach Kinderwunschbehandlungen sind Fehlgeburten, Eileiter- und Mehrlingsschwangerschaften häufiger.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Den von der Ärztin oder vom Arzt festgelegten Injektionszeitpunkt genau einhalten; Eizellentnahme oder Geschlechtsverkehr werden darauf abgestimmt.","Schwangerschaftstests können bis etwa 10 Tage nach der Injektion falsch positiv ausfallen.","Bei starken Bauchschmerzen, Blähbauch, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen (Überstimulation)."],"darreichung":["Injektionslösung im Fertigpen","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"ciclopirox":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen und tötet sie ab. Ciclopirox bindet (chelatiert) dreiwertige Metallionen wie Eisen und Aluminium und blockiert dadurch eisenabhängige Enzyme, die der Pilz für seinen Stoffwechsel und die Entgiftung von Sauerstoffradikalen braucht. Es wirkt breit gegen Dermatophyten, Hefen und Schimmelpilze, zusätzlich gegen einige Bakterien, und dämpft Entzündungen leicht. Aus dem Nagellack dringt der Wirkstoff in die Nagelplatte ein.","nebenwirkungen":{"gelegentlich":["Brennen und Juckreiz an der Anwendungsstelle (Creme, Lösung)"],"sehrSelten":["Rötung und Schuppung der Haut rund um den behandelten Nagel (Nagellack)","Allergische Kontaktdermatitis (juckender Ausschlag an der Auftragsstelle)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung: Es gibt kaum Erfahrungen, die Aufnahme in den Körper ist bei äusserlicher Anwendung aber gering.","stillzeit":"Nach ärztlicher Abwägung möglich, da kaum Wirkstoff in den Körper gelangt; nicht im Brustbereich auftragen.","hinweise":["Nagelpilz braucht Geduld: Die Behandlung dauert meist mehrere Monate (Fingernägel etwa 6, Zehennägel 9–12 Monate), bis der Nagel gesund nachgewachsen ist.","Während der Behandlung mit dem Nagellack keinen kosmetischen Nagellack und keine künstlichen Nägel verwenden.","Nicht in die Augen oder auf Schleimhäute bringen.","Keine Besserung nach etwa 6 Monaten: ärztlich kontrollieren lassen."],"darreichung":["Nagellack (wirkstoffhaltig)","Creme","Lösung zur Anwendung auf der Haut"]},"ciclosporin":{"wirkmechanismus":"Hemmt die Aktivierung bestimmter Abwehrzellen (T-Lymphozyten), die transplantierte Organe angreifen oder Autoimmunentzündungen antreiben. Ciclosporin bindet in der Zelle an Cyclophilin; dieser Komplex hemmt das Enzym Calcineurin. Dadurch wird die Bildung von Interleukin-2 und anderen Botenstoffen unterdrückt, und T-Zellen vermehren sich nicht. Als Augentropfen wirkt es örtlich entzündungshemmend auf Hornhaut und Bindehaut.","nebenwirkungen":{"sehrHaeufig":["Nierenfunktionsstörung (Anstieg des Kreatinins)","Bluthochdruck","Zittern (Tremor), Kopfschmerzen","Erhöhte Blutfette"],"haeufig":["Erhöhtes Kalium, Magnesiummangel, erhöhte Harnsäure, erhöhter Blutzucker","Appetitlosigkeit, Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Zahnfleischwucherung (Gingivahyperplasie)","Leberfunktionsstörungen","Vermehrte Körperbehaarung (Hypertrichose), Akne","Parästhesien (Kribbeln, Brennen), Krampfanfälle","Muskelkrämpfe, Muskelschmerzen","Leukopenie, Fieber, Müdigkeit"],"gelegentlich":["Anämie, Thrombozytopenie","Hirnstörungen (Enzephalopathie, PRES) mit Krampfanfällen, Verwirrtheit, Sehstörungen","Ödeme, Gewichtszunahme","Allergischer Hautausschlag"],"selten":["Thrombotische Mikroangiopathie, hämolytisch-urämisches Syndrom","Periphere Neuropathie (Nervenschädigung)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Muskelschwäche, Myopathie","Menstruationsstörungen, Brustvergrösserung beim Mann"],"sehrSelten":["Papillenödem (Sehnervschwellung) mit Sehstörungen"],"unbekannt":["Schwere Leberschäden bis Leberversagen","Lymphome und Hautkrebs (bei Langzeitimmunsuppression)","Opportunistische Infektionen, auch PML und BK-Virus-Nephropathie","Augentropfen: Augenschmerzen, Augenreizung, Brennen nach dem Eintropfen (sehr häufig)"]},"schwangerschaft":"Nur bei zwingender Indikation (z. B. nach Transplantation) nach ärztlicher Abwägung; kein Hinweis auf Fehlbildungen, aber mehr Frühgeburten und tiefes Geburtsgewicht. Augentropfen in der Schwangerschaft nicht empfohlen.","stillzeit":"Ciclosporin geht in die Muttermilch über; unter systemischer Therapie wird vom Stillen abgeraten.","hinweise":["Immer gleich und regelmässig einnehmen; keinen Grapefruitsaft und kein Johanniskraut.","Ciclosporin-Spiegel, Nierenwerte, Blutdruck, Kalium und Leberwerte werden regelmässig kontrolliert.","Nicht ohne Rücksprache zwischen verschiedenen Ciclosporin-Präparaten wechseln (unterschiedliche Aufnahme).","Gute Mundhygiene gegen Zahnfleischwucherung; konsequenter Sonnenschutz."],"darreichung":["Weichkapseln","Lösung zum Einnehmen","Konzentrat zur Herstellung einer Infusionslösung","Augentropfen (Emulsion)"]},"cilazapril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II hemmt. Cilazapril ist ein Prodrug, das in der Leber zum wirksamen Cilazaprilat umgewandelt wird; dieses hemmt das Angiotensin-Converting-Enzym (ACE). Dadurch sinken Angiotensin II und Aldosteron, die Gefässe erweitern sich und die Salz- und Wasserausscheidung nimmt zu. Weil ACE auch Bradykinin abbaut, steigt dieses an – das erklärt Reizhusten und Angioödeme.","nebenwirkungen":{"haeufig":["Schwindel","Kopfschmerzen","Husten","Übelkeit","Müdigkeit"],"gelegentlich":["Hypotonie (tiefer Blutdruck), Herzklopfen, Tachykardie (Herzrasen)","Angina pectoris (Brustenge)","Atemnot, Bronchospasmus, Schnupfen","Mundtrockenheit, Geschmacksstörungen, Appetitlosigkeit","Durchfall, Erbrechen","Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)","Hautausschlag, Schwitzen, Flush","Muskelschmerzen, Schlafstörungen, Erektionsstörungen"],"selten":["Neutropenie bis Agranulozytose, Thrombozytopenie, Anämie","Herzinfarkt, Herzrhythmusstörungen","Schlaganfall, vorübergehende Durchblutungsstörung des Gehirns (TIA)","Pankreatitis","Hepatitis, Gallenstau, Leberzellschädigung","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Nierenfunktionsstörung bis akutes Nierenversagen","Hyperkaliämie (erhöhtes Kalium)"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schädigung der kindlichen Nieren, Fruchtwassermangel, Verknöcherungsstörungen des Schädels). Bei Kinderwunsch oder Schwangerschaft auf ein anderes Mittel umstellen.","stillzeit":"Keine Daten zum Übergang in die Muttermilch; nicht empfohlen – besser untersuchte Alternativen wählen.","hinweise":["Bei Schwellungen von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notfall aufsuchen (Angioödem).","Trockener Reizhusten ist eine typische Nebenwirkung – ärztlich melden, nicht selbst absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel meiden.","Zu Beginn sind Schwindel und Benommenheit möglich – Vorsicht beim Autofahren."],"darreichung":["Filmtabletten"]},"cimicifuga":{"wirkmechanismus":"Lindert typische Wechseljahresbeschwerden wie Hitzewallungen und Schweissausbrüche. Der Wirkmechanismus des Extrakts aus dem Wurzelstock der Traubensilberkerze ist nicht vollständig geklärt. Nach heutigem Wissen wirkt er nicht wie ein klassisches Östrogen auf Brust und Gebärmutterschleimhaut, sondern beeinflusst vermutlich zentrale Botenstoffsysteme (u. a. Serotonin- und Opioidrezeptoren), die an der Temperaturregulation beteiligt sind.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Verdauungsbeschwerden, Durchfall)","Allergische Hautreaktionen (Nesselsucht, Juckreiz, Ausschlag)","Schwellungen im Gesicht, Wassereinlagerungen in Armen und Beinen (Ödeme)","Leberschädigung (Leberentzündung, Gelbsucht, veränderte Leberwerte), in Einzelfällen schwer"]},"schwangerschaft":"Nicht anwenden – keine ausreichenden Daten; das Mittel ist für Frauen in den Wechseljahren bestimmt.","stillzeit":"Nicht anwenden – keine ausreichenden Daten.","hinweise":["Die Wirkung setzt nach etwa 2 Wochen ein, die volle Wirkung oft erst nach mehreren Wochen.","Ohne ärztliche Rücksprache nicht länger als 6 Monate einnehmen.","Bei Anzeichen einer Leberschädigung (Gelbsucht, dunkler Urin, starke Müdigkeit, Oberbauchschmerzen) sofort absetzen und eine Ärztin oder einen Arzt aufsuchen.","Ersetzt keine ärztliche Abklärung von Blutungen nach der Menopause."],"darreichung":["Tabletten","Filmtabletten"]},"cinacalcet":{"wirkmechanismus":"Macht die Nebenschilddrüsen empfindlicher für Calcium, sodass sie weniger Parathormon ausschütten. Cinacalcet ist ein allosterischer Modulator des calciumsensitiven Rezeptors (CaSR) auf den Hauptzellen der Nebenschilddrüse: Schon niedrigere Calciumkonzentrationen hemmen dadurch die Parathormon-Freisetzung. In der Folge sinken Parathormon und Calcium im Blut, bei Dialysepatienten auch das Calcium-Phosphat-Produkt.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Erbrechen"],"haeufig":["Hypokalzämie (zu tiefes Calcium; z. B. Kribbeln, Muskelkrämpfe)","Krampfanfälle","Appetitlosigkeit","Schwindel, Kribbeln (Parästhesien), Kopfschmerzen","Blutdruckabfall (Hypotonie)","Durchfall, Verstopfung, Bauchschmerzen, Verdauungsbeschwerden","Muskelschmerzen, Muskelkrämpfe, Rückenschmerzen, Schwäche","Hautausschlag, Überempfindlichkeitsreaktionen, Hyperkaliämie (erhöhtes Kalium), tieferes Testosteron"],"unbekannt":["Verschlechterung einer Herzinsuffizienz","QT-Verlängerung und ventrikuläre Herzrhythmusstörungen infolge Hypokalzämie","Nesselsucht (Urtikaria)","Angioödem (Schwellung von Gesicht, Lippen oder Rachen)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn der Nutzen das mögliche Risiko für das Kind klar überwiegt.","stillzeit":"Nicht bekannt, ob Cinacalcet in die Muttermilch übergeht; nach ärztlicher Abwägung entweder abstillen oder auf das Mittel verzichten.","hinweise":["Mit einer Mahlzeit oder kurz danach einnehmen – so wird Cinacalcet besser aufgenommen. Tabletten ganz schlucken, nicht teilen oder zerkauen.","Regelmässige Kontrollen von Calcium und Parathormon, besonders in den ersten Wochen und nach jeder Dosisänderung.","Kribbeln um den Mund oder in den Fingern, Muskelzuckungen, Krämpfe oder Krampfanfälle können Zeichen eines zu tiefen Calciums sein – sofort ärztlich melden.","Beginn oder Ende des Rauchens der Ärztin oder dem Arzt mitteilen."],"darreichung":["Filmtabletten"]},"cinchocain":{"wirkmechanismus":"Betäubt die Nervenenden in Haut und Schleimhaut des Afters und lindert so Schmerz und Juckreiz. Cinchocain blockiert spannungsabhängige Natriumkanäle der Nervenmembran und verhindert dadurch die Weiterleitung von Schmerzreizen. Es gehört zu den stärksten und am längsten wirksamen Lokalanästhetika und wird heute nur noch oberflächlich angewendet.","nebenwirkungen":{"unbekannt":["Lokales Brennen","Allergische Kontaktdermatitis (juckender Ausschlag)","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung; bei kortisonhaltigen Kombipräparaten besonders im ersten Schwangerschaftsdrittel zurückhaltend anwenden.","stillzeit":"Kurzfristige Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Nur äusserlich bzw. rektal anwenden und für Kinder unzugänglich aufbewahren – Cinchocain ist beim Verschlucken sehr giftig.","Bei Blut im Stuhl oder fehlender Besserung nach einer Woche ärztlich abklären lassen.","Kann die Reissfestigkeit von Latexkondomen vermindern."],"darreichung":["Salbe","Zäpfchen"]},"cinnarizin-dimenhydrinat":{"wirkmechanismus":"Lindert Schwindel und begleitende Übelkeit über zwei sich ergänzende Wirkstoffe. Cinnarizin hemmt den Calciumeinstrom in die Sinneszellen des Gleichgewichtsorgans und verbessert die Durchblutung im Innenohr (peripherer Angriffspunkt). Dimenhydrinat ist ein sedierendes Antihistaminikum mit anticholinerger Wirkung, das die Gleichgewichtszentren im Hirnstamm dämpft (zentraler Angriffspunkt) und gegen Übelkeit wirkt.","nebenwirkungen":{"haeufig":["Schläfrigkeit, Benommenheit","Kopfschmerzen","Mundtrockenheit","Bauchschmerzen"],"gelegentlich":["Kribbeln (Parästhesien), Zittern, Nervosität, Vergesslichkeit","Ohrensausen (Tinnitus)","Übelkeit, Dyspepsie (Verdauungsbeschwerden)","Schwitzen, Hautausschlag"],"unbekannt":["Krampfanfälle","Sehstörungen","Überempfindlichkeitsreaktionen, Lichtempfindlichkeit der Haut","Blutbildveränderungen (Leukopenie, Thrombozytopenie, aplastische Anämie)","Extrapyramidale Symptome (Bewegungsstörungen), vor allem bei älteren Menschen","Harnverhalt"]},"schwangerschaft":"Keine ausreichenden Daten; in der Schwangerschaft nicht anwenden.","stillzeit":"Dimenhydrinat geht in die Muttermilch über; nicht stillen.","hinweise":["Nach den Mahlzeiten unzerkaut mit etwas Flüssigkeit einnehmen.","In der Regel nicht länger als 4 Wochen ohne ärztliche Neubeurteilung anwenden.","Alkohol meiden; die Fahrtüchtigkeit ist häufig beeinträchtigt."],"darreichung":["Tabletten"]},"cipaglucosidase-alfa":{"wirkmechanismus":"Ersetzt ein Enzym, das bei Morbus Pompe fehlt, damit sich weniger Glykogen in den Muskelzellen ablagert. Cipaglucosidase alfa ist eine gentechnisch hergestellte saure Alpha-Glucosidase mit vielen Bis-Mannose-6-Phosphat-Zuckerketten, die über Mannose-6-Phosphat-Rezeptoren gut in die Muskelzellen aufgenommen wird. In den Lysosomen wird sie zur reifen Form aktiviert und spaltet Glykogen. Das kurz vorher eingenommene Miglustat bindet im Blut an das Enzym und stabilisiert es, sodass weniger aktives Enzym verloren geht.","nebenwirkungen":{"haeufig":["Infusionsbedingte Reaktionen und Überempfindlichkeitsreaktionen","Kopfschmerzen, Schwindel, Zittern, Schläfrigkeit, Geschmacksstörung","Herzrasen, Hautrötung mit Hitzegefühl","Husten, Atemnot","Durchfall, Übelkeit, Bauchschmerzen, Blähungen, Verstopfung","Juckreiz, Ausschlag, Nesselsucht, vermehrtes Schwitzen","Muskelschmerzen, Muskelkrämpfe, Muskelschwäche","Müdigkeit, Schüttelfrost, Fieber, Schmerzen"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Die Kombination mit Miglustat wird in der Schwangerschaft nicht empfohlen (Miglustat im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter müssen während und bis 4 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob die Wirkstoffe in die Muttermilch übergehen; ein Risiko für den Säugling ist nicht auszuschliessen. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird alle 2 Wochen als Infusion in eine Vene gegeben; die Miglustat-Kapseln werden etwa 1 Stunde vor Beginn der Infusion nüchtern eingenommen (2 Stunden vorher und 2 Stunden nachher nichts essen).","Atemnot, Schwellungen oder Ausschlag während oder nach der Infusion sofort melden.","Zuverlässig verhüten; eine Schwangerschaft sofort der Ärztin oder dem Arzt mitteilen."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"ciprofloxacin":{"wirkmechanismus":"Tötet Bakterien ab, indem es das Kopieren ihrer Erbsubstanz verhindert. Ciprofloxacin hemmt die bakteriellen Topoisomerasen II (DNA-Gyrase) und IV, die zum Entwinden und Trennen der DNA nötig sind; es entstehen tödliche DNA-Brüche. Es wirkt besonders gut gegen gramnegative Erreger einschliesslich Pseudomonas aeruginosa, schwächer gegen Pneumokokken und kaum gegen Anaerobier. Ciprofloxacin hemmt zudem das Leberenzym CYP1A2.","nebenwirkungen":{"haeufig":["Übelkeit, Durchfall","Bei Augentropfen: Augenbeschwerden, weissliche Ablagerungen auf der Hornhaut"],"gelegentlich":["Pilzinfektionen","Kopfschmerzen, Schwindel, Schlafstörungen, Geschmacksstörungen, Unruhe","Erbrechen, Bauchschmerzen, Verdauungsbeschwerden, Blähungen","Erhöhte Leberwerte und Bilirubin","Hautausschlag, Juckreiz, Nesselsucht","Gelenkschmerzen (bei Kindern häufig)","Eosinophilie, Appetitlosigkeit, Schwäche, Fieber"],"selten":["Antibiotika-assoziierte Kolitis (sehr selten pseudomembranös)","Blutbildveränderungen (Leukopenie, Anämie, Thrombozytopenie)","Verwirrtheit, Angst, Albträume, Depression bis Suizidgedanken, Halluzinationen","Krampfanfälle, Kribbeln und Missempfindungen, Zittern","Sehstörungen, Tinnitus, Hörverlust","Herzrasen, Blutdruckabfall, Ohnmacht","Unter- oder Überzuckerung","Lichtempfindlichkeit der Haut, Muskelschmerzen, Nierenversagen, Kristallurie"],"sehrSelten":["Sehnenentzündung und Sehnenriss (vor allem Achillessehne), Muskelschwäche, Verschlechterung einer Myasthenia gravis","Agranulozytose, hämolytische Anämie, Panzytopenie","Anaphylaktischer Schock","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Lebernekrose bis Leberversagen, Pankreatitis","Psychotische Reaktionen, Gangstörungen, erhöhter Hirndruck"],"unbekannt":["QT-Verlängerung, ventrikuläre Herzrhythmusstörungen, Torsade de pointes","Periphere Neuropathie (teils bleibend)","Aortenaneurysma und -dissektion, Herzklappenundichtigkeit","DRESS und akute generalisierte exanthematische Pustulose","Hyponatriämie (SIADH), Manie","Lang anhaltende, möglicherweise bleibende Nebenwirkungen an Sehnen, Muskeln, Gelenken, Nerven und Psyche"]},"schwangerschaft":"Vorsichtshalber nicht anwenden, da in Tierversuchen Gelenkknorpelschäden beim Jungtier auftraten. Augen- und Ohrentropfen nur nach ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über; wegen möglicher Gelenkknorpelschäden beim Säugling während der systemischen Behandlung nicht stillen.","hinweise":["Nicht zusammen mit Milch, Joghurt oder mit Calcium angereicherten Säften allein einnehmen; Abstand zu Mineralstoff- und Eisenpräparaten sowie Antazida einhalten.","Bei Sehnenschmerzen, Kribbeln, Taubheit, plötzlichen Brust-, Bauch- oder Rückenschmerzen sofort absetzen und ärztliche Hilfe holen.","Starke Sonne und Solarium meiden; das Reaktionsvermögen kann eingeschränkt sein (Autofahren).","Kaffee wirkt stärker und länger."],"darreichung":["Filmtabletten","Suspension zum Einnehmen","Infusionslösung","Augentropfen","Ohrentropfen"]},"cisatracurium":{"wirkmechanismus":"Lähmt vorübergehend die Skelettmuskulatur, indem es die Signalübertragung vom Nerv auf den Muskel unterbricht. Cisatracurium blockiert kompetitiv die nikotinischen Acetylcholinrezeptoren an der motorischen Endplatte, ohne sie zu aktivieren (nicht-depolarisierend). Es zerfällt unabhängig von Leber und Niere spontan (Hofmann-Elimination) zu Laudanosin und einem Acrylat-Metaboliten. Die Wirkung lässt sich mit Acetylcholinesterase-Hemmern wie Neostigmin aufheben. Cisatracurium wirkt weder schmerzstillend noch beruhigend.","nebenwirkungen":{"haeufig":["Bradykardie (langsamer Puls)","Hypotonie (Blutdruckabfall)"],"gelegentlich":["Hautrötung (Flush)","Hautausschlag","Bronchospasmus (Verkrampfung der Atemwege)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Myopathie und Muskelschwäche nach längerer Anwendung auf der Intensivstation"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; Anwendung nur, wenn sie klar notwendig ist.","stillzeit":"Es ist nicht bekannt, ob Cisatracurium in die Muttermilch übergeht; wegen des raschen Abbaus kann nach Abklingen der Wirkung in der Regel wieder gestillt werden.","hinweise":["Wird nur im Spital durch erfahrene Anästhesie- oder Intensivfachpersonen verabreicht, wenn eine künstliche Beatmung möglich ist.","Bekannte Muskelerkrankungen und frühere allergische Reaktionen bei Narkosen vor dem Eingriff angeben.","Nach einer Narkose mindestens 24 Stunden kein Fahrzeug lenken und keine Maschinen bedienen."],"darreichung":["Injektions- bzw. Infusionslösung"]},"cisplatin":{"wirkmechanismus":"Schädigt das Erbgut von Krebszellen, sodass sie sich nicht mehr teilen können. Cisplatin bildet in der Zelle reaktive Platinkomplexe, die die DNA-Stränge quer und innerhalb eines Strangs vernetzen. Dadurch werden DNA-Verdoppelung und Ablesung blockiert und der programmierte Zelltod ausgelöst. Betroffen sind vor allem sich schnell teilende Zellen; Cisplatin wird über die Niere ausgeschieden und reichert sich dort an.","nebenwirkungen":{"sehrHaeufig":["Nierenschädigung (Anstieg von Kreatinin und Harnstoff)","Übelkeit und Erbrechen","Knochenmarkhemmung (Leukopenie, Thrombozytopenie, Anämie)","Elektrolytstörungen (Mangel an Magnesium, Kalium, Natrium, Calcium)","Hyperurikämie (erhöhte Harnsäure)","Fieber"],"haeufig":["Hörverlust (v. a. hohe Töne) und Tinnitus (Ohrgeräusche)","Periphere Neuropathie (Kribbeln, Taubheit)","Infektionen, Sepsis","Herzrhythmusstörungen, Bradykardie","Venenentzündung an der Einstichstelle"],"gelegentlich":["Anaphylaxie (schwere allergische Reaktion)","Hypomagnesiämie mit Krämpfen"],"selten":["Akute Leukämie als Spätfolge","Krampfanfälle","Herzinfarkt"],"sehrSelten":["Herzstillstand"],"unbekannt":["Hämolytische Anämie","Thromboembolien","Sehstörungen, Sehnervenentzündung","Syndrom der inadäquaten ADH-Sekretion (SIADH, Natriummangel)","Posteriores reversibles Enzephalopathie-Syndrom (PRES)"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit, da Fruchtschäden möglich sind. Frauen und Männer sollen während und noch mindestens 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert; Cisplatin geht in die Muttermilch über.","hinweise":["Viel trinken, wie vom Behandlungsteam empfohlen – das schützt die Nieren.","Hörveränderungen, Ohrgeräusche, Kribbeln oder Taubheit in Händen und Füssen melden.","Keine Lebendimpfungen während und einige Monate nach der Therapie.","Spermien- bzw. Eizellkonservierung vor Therapiebeginn besprechen (mögliche Unfruchtbarkeit)."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"citalopram":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Panikattacken, indem es die Menge des Botenstoffs Serotonin zwischen den Nervenzellen erhöht. Citalopram ist ein sehr selektiver Hemmer des Serotonin-Transporters und hat kaum Wirkung an anderen Rezeptoren. Es wird in der Leber über CYP2C19, CYP3A4 und CYP2D6 abgebaut; die Halbwertszeit beträgt etwa 1,5 Tage. Dosisabhängig verlängert es die QT-Zeit im EKG.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Schlaflosigkeit","Kopfschmerzen","Übelkeit, Mundtrockenheit","Vermehrtes Schwitzen"],"haeufig":["Verminderter Appetit, Gewichtsabnahme","Unruhe, Angst, Nervosität, Verwirrtheit, ungewöhnliche Träume","Verminderte Libido, Orgasmus- und Ejakulationsstörungen, Impotenz","Zittern, Kribbeln, Schwindel, Konzentrationsstörungen","Ohrgeräusche (Tinnitus), Gähnen","Durchfall, Verstopfung, Erbrechen","Juckreiz, Muskel- und Gelenkschmerzen","Müdigkeit"],"gelegentlich":["Gewichtszunahme, Aggressivität, Halluzinationen, Manie","Ohnmacht (Synkope)","Erweiterte Pupillen (Mydriasis)","Langsamer oder schneller Puls","Nesselsucht, Hautausschlag, Haarausfall, Lichtempfindlichkeit, Hautblutungen (Purpura)","Harnverhalt","Starke Menstruationsblutungen","Wassereinlagerungen (Ödeme)"],"selten":["Hyponatriämie (Natriummangel)","Krampfanfälle, unwillkürliche Bewegungen","Blutungen","Leberentzündung (Hepatitis)","Fieber"],"unbekannt":["QT-Verlängerung, ventrikuläre Herzrhythmusstörungen inkl. Torsade de pointes","Serotoninsyndrom","Suizidgedanken und suizidales Verhalten","Thrombozytopenie, anaphylaktische Reaktionen, Angioödem","Magen-Darm-Blutungen, Nasenbluten, Blutergüsse","Akathisie (Bewegungsunruhe), Panikattacken, Zähneknirschen","Blutdruckabfall beim Aufstehen, Kaliummangel","Milchfluss (Galaktorrhö), Priapismus, Nachblutungen nach der Geburt"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung, nicht abrupt absetzen. Bei Einnahme in der Spätschwangerschaft sind beim Neugeborenen Anpassungsstörungen (z. B. Atemprobleme, Trinkschwäche, Zittern) und ein erhöhtes Risiko für Lungenhochdruck (PPHN) möglich.","stillzeit":"Citalopram geht in die Muttermilch über; ist eine Behandlung nötig, soll ein Abstillen erwogen werden.","hinweise":["Höchstdosis 40 mg pro Tag; bei Menschen über 65 Jahren, eingeschränkter Leberfunktion oder langsamem CYP2C19-Abbau höchstens 20 mg pro Tag (QT-Risiko).","Bei Herzklopfen, Schwindel oder Ohnmacht sofort ärztlich abklären lassen.","Die Wirkung setzt nach 2–4 Wochen ein; nicht abrupt absetzen, sondern schrittweise ausschleichen.","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden."],"darreichung":["Filmtabletten"]},"cladribin":{"wirkmechanismus":"Vermindert gezielt bestimmte weisse Blutkörperchen (Lymphozyten), die bei Haarzellenleukämie entartet sind bzw. bei Multipler Sklerose das Nervensystem angreifen. Cladribin ist eine Vorstufe (Prodrug), die in Zellen mit viel Desoxycytidinkinase und wenig 5'-Nukleotidase – vor allem in B- und T-Lymphozyten – zu Cladribin-Triphosphat aktiviert wird. Dieses stört DNA-Synthese und -Reparatur und löst den programmierten Zelltod (Apoptose) aus, auch in ruhenden Zellen. Bei Multipler Sklerose führen zwei kurze Behandlungsphasen im Abstand eines Jahres zu einer anhaltenden Verminderung der Lymphozyten.","nebenwirkungen":{"sehrHaeufig":["Lymphopenie (starke Abnahme der Lymphozyten)","Neutropenie, Thrombozytopenie, Anämie (Injektion)","Fieber und Infektionen (Injektion)","Müdigkeit, Kopfschmerzen, Übelkeit (Injektion)","Hautausschlag, Reaktionen an der Einstichstelle (Injektion)"],"haeufig":["Lippenherpes und Gürtelrose (Herpes zoster)","Haarausfall (Tabletten)","Durchfall, Verstopfung, Bauchschmerzen (Injektion)","Husten, Atemnot (Injektion)","Schwindel, Schlaflosigkeit (Injektion)","Muskel- und Gelenkschmerzen (Injektion)"],"sehrSelten":["Tuberkulose (Tabletten)"],"unbekannt":["Progressive multifokale Leukoenzephalopathie (PML, seltene schwere Hirninfektion) und andere opportunistische Infektionen","Leberschädigung","Bösartige Neubildungen (Krebs)","Autoimmunhämolytische Anämie (Blutzerfall)","Tumorlysesyndrom (Injektion)","Nerven- und Nierenschäden bei hohen Dosen"]},"schwangerschaft":"Kontraindiziert, da Cladribin das Ungeborene schwer schädigen kann. Frauen und Männer müssen während der Behandlung und mindestens 6 Monate nach der letzten Dosis zuverlässig verhüten; bei hormonaler Verhütung zusätzlich eine Barrieremethode.","stillzeit":"Kontraindiziert. Bei der Tablettentherapie während der Behandlung und mindestens 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Tabletten mit Wasser unzerkaut schlucken, nur mit trockenen Händen anfassen und danach Hände waschen; an den Behandlungstagen andere Medikamente zum Einnehmen mindestens 3 Stunden zeitversetzt nehmen.","Blutbild (Lymphozyten) vor jedem Behandlungsjahr sowie 2 und 6 Monate nach Beginn kontrollieren lassen.","Bei Fieber, Bläschenausschlag (Gürtelrose), Gelbsucht oder neuen neurologischen Beschwerden umgehend ärztlichen Rat einholen.","Vor Bluttransfusionen das Behandlungsteam informieren (nur bestrahlte Blutprodukte)."],"darreichung":["Tabletten","Injektionslösung (unter die Haut)"]},"clarithromycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Clarithromycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und blockiert die Verlängerung der Eiweisskette; sein Hauptmetabolit 14-Hydroxy-Clarithromycin ist ebenfalls wirksam. Es wirkt gegen Streptokokken, Haemophilus, atypische Erreger (Mykoplasmen, Chlamydien, Legionellen), Helicobacter pylori und Mykobakterien. Clarithromycin hemmt das Abbauenzym CYP3A4 und den Transporter P-Glykoprotein stark und erhöht dadurch die Spiegel vieler anderer Medikamente.","nebenwirkungen":{"haeufig":["Geschmacksstörungen, Kopfschmerzen","Schlaflosigkeit","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Verdauungsbeschwerden","Hautausschlag, vermehrtes Schwitzen","Abweichende Leberwerte","Venenentzündung an der Infusionsstelle"],"gelegentlich":["Pilzinfektionen (Candidose), Scheideninfektion","Leukopenie, Neutropenie, Eosinophilie (Blutbildveränderungen)","Schwindel, Drehschwindel, Schläfrigkeit, Zittern, Angst","Hörstörungen, Tinnitus (Ohrensausen)","QT-Verlängerung im EKG, Herzklopfen","Gastritis, Verstopfung, Mundtrockenheit, Blähungen","Cholestase und Hepatitis (Leberentzündung)","Juckreiz, Nesselsucht, Muskelschmerzen"],"unbekannt":["Torsade de pointes, Kammertachykardie und Kammerflimmern","Pseudomembranöse Kolitis (schwere Dickdarmentzündung)","Agranulozytose (starker Mangel an weissen Blutkörperchen), Thrombozytopenie","Anaphylaxie, Angioödem","Leberversagen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS, AGEP)","Verwirrtheit, Halluzinationen, Psychosen, Krampfanfälle, Hörverlust","Rhabdomyolyse (Muskelzerfall), Nierenversagen, interstitielle Nephritis"]},"schwangerschaft":"Die Sicherheit ist nicht belegt; Tierversuche zeigen schädliche Wirkungen. Nur nach sorgfältiger ärztlicher Nutzen-Risiko-Abwägung anwenden.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall und Pilzbefall möglich. Nur nach ärztlicher Abwägung.","hinweise":["Vor Beginn alle anderen Medikamente angeben: Clarithromycin hat sehr viele, teils lebensgefährliche Wechselwirkungen.","Retardtabletten mit einer Mahlzeit und unzerkaut schlucken.","Bei Herzklopfen, Ohnmacht, Gelbsucht, dunklem Urin oder starkem Durchfall sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten","Retardtabletten","Granulat für Suspension zum Einnehmen","Pulver zur Herstellung einer Infusionslösung"]},"clindamycin":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien, indem es ihre Eiweissherstellung stoppt. Clindamycin bindet an die 50S-Untereinheit der bakteriellen Ribosomen und hemmt die Peptidkettenbildung; es wirkt vorwiegend bakteriostatisch gegen grampositive Kokken (Staphylokokken, Streptokokken) und Anaerobier. Es dringt gut in Knochen und Gewebe ein und hemmt die Toxinbildung von Streptokokken und Staphylokokken. Gegen Enterokokken und die meisten gramnegativen Keime wirkt es nicht.","nebenwirkungen":{"haeufig":["Durchfall, Bauchschmerzen","Pseudomembranöse Kolitis (schwere Dickdarmentzündung durch Clostridioides difficile)","Fleckiger Hautausschlag","Abweichende Leberwerte","Venenentzündung bei Infusion","Bei Anwendung auf der Haut: Trockenheit, Rötung, Brennen; bei Vaginalcreme: Scheidenpilz"],"gelegentlich":["Übelkeit, Erbrechen","Geschmacksstörungen","Nesselsucht"],"selten":["Erythema multiforme (Hautausschlag mit kokardenförmigen Flecken)","Juckreiz"],"unbekannt":["Agranulozytose, Neutropenie, Thrombozytopenie (Blutbildschäden)","Anaphylaxie, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS, AGEP)","Gelbsucht","Speiseröhrenentzündung oder -geschwür bei Kapseln","Akute Nierenschädigung"]},"schwangerschaft":"Im 2. und 3. Drittel zeigten Studien kein erhöhtes Fehlbildungsrisiko; für das 1. Drittel sind die Daten begrenzt. Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; die Anwendung auf der Haut gilt als vertretbar.","stillzeit":"Geht in die Muttermilch über; beim Säugling sind Durchfall, Pilzbefall und selten blutiger Stuhl möglich. Nach ärztlicher Abwägung, Kind beobachten.","hinweise":["Kapseln aufrecht mit einem vollen Glas Wasser schlucken (Gefahr einer Speiseröhrenreizung).","Bei starkem, anhaltendem oder blutigem Durchfall – auch Wochen nach der Behandlung – sofort ärztliche Hilfe holen; keine stopfenden Mittel wie Loperamid nehmen.","Vaginalcreme kann Kondome und Diaphragmen aus Latex beschädigen.","Akne-Kombinationen mit Benzoylperoxid können Textilien und Haare bleichen."],"darreichung":["Kapseln","Injektions- und Infusionslösung","Lösung und Gel zum Auftragen auf die Haut","Vaginalcreme"]},"clindamycin-benzoylperoxid":{"wirkmechanismus":"Bekämpft die an der Akne beteiligten Bakterien, wirkt entzündungshemmend und löst Verhornungen. Clindamycin hemmt als Lincosamid-Antibiotikum die bakterielle Eiweissbildung an der 50S-Untereinheit der Ribosomen und wirkt gegen Cutibacterium acnes. Benzoylperoxid setzt Sauerstoffradikale frei, tötet so Bakterien ab und wirkt leicht schälend (keratolytisch). Weil Benzoylperoxid unspezifisch wirkt, vermindert die Kombination die Entstehung Clindamycin-resistenter Bakterien.","nebenwirkungen":{"sehrHaeufig":["Rötung, Schuppung und Trockenheit der Haut an der Auftragsstelle (meist leicht)"],"haeufig":["Brennen, Schmerzen und Juckreiz an der Auftragsstelle","Kopfschmerzen","Lichtempfindlichkeit (Photosensibilität)"],"gelegentlich":["Kribbeln der Haut (Parästhesien)","Dermatitis, Verschlechterung der Akne"],"unbekannt":["Darmentzündung durch Antibiotika (pseudomembranöse Kolitis), blutiger Durchfall, Bauchschmerzen","Allergische Reaktionen bis zur Anaphylaxie, Gesichtsschwellung","Nesselsucht (Urtikaria)"]},"schwangerschaft":"Nur wenig Erfahrungen; nur nach ärztlicher Abwägung anwenden, wenn klar notwendig.","stillzeit":"Nur nach ärztlicher Abwägung; nicht auf die Brust auftragen, damit der Säugling nicht in Kontakt mit dem Gel kommt.","hinweise":["Einmal täglich abends dünn auf die gereinigte, trockene Haut auftragen; danach die Hände waschen.","Benzoylperoxid bleicht Haare und Textilien (Kleidung, Handtücher, Bettwäsche) – Kontakt vermeiden.","Ohne ärztliche Neubeurteilung nicht länger als 12 Wochen anwenden (Resistenzgefahr).","Sonne und Solarium meiden, Sonnenschutz verwenden."],"darreichung":["Gel"]},"clioquinol":{"wirkmechanismus":"Hemmt das Wachstum von Bakterien und Pilzen auf der Haut und im Gehörgang. Clioquinol (5-Chlor-7-iod-8-hydroxychinolin) bindet Metallionen wie Eisen, Zink und Kupfer, die Mikroorganismen für ihre Enzyme benötigen, und wirkt dadurch bakteriostatisch und fungistatisch, u. a. gegen grampositive Bakterien sowie Hefe- und Hautpilze. In der Kombination dämpft das Kortikosteroid Flumetason Entzündung und Juckreiz. Bei grossflächiger Anwendung, auf verletzter Haut oder unter Verbänden kann Clioquinol durch die Haut ins Blut gelangen.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz oder Reizung an der Auftragsstelle","Allergische Kontaktdermatitis","Gelbliche Verfärbung von Haut, Haaren und Nägeln","Hautatrophie (Hautverdünnung), erweiterte Äderchen, Dehnungsstreifen bei längerer Anwendung (Kortikosteroid-Anteil)","Hellere Hautstellen (Hypopigmentierung)","Unterdrückung der Nebennierenrinde bei grossflächiger Anwendung (Kortikosteroid-Anteil)"]},"schwangerschaft":"Keine ausreichenden Daten; nur nach strenger ärztlicher Abwägung, kleinflächig und kurzzeitig anwenden.","stillzeit":"Nicht bekannt, ob Clioquinol in die Muttermilch übergeht; nur nach ärztlicher Abwägung und nicht im Brustbereich anwenden.","hinweise":["Färbt Haut, Haare, Kleidung und Wäsche gelb; Flecken in Textilien lassen sich oft nicht auswaschen.","Nicht grossflächig und nicht unter luftdichten Verbänden anwenden; die Behandlung auf die verordnete Dauer begrenzen.","Vor Schilddrüsenuntersuchungen die Anwendung angeben, weil das Jod Messwerte verfälschen kann."],"darreichung":["Creme","Ohrentropfen"]},"clobazam":{"wirkmechanismus":"Wirkt angstlösend und krampfhemmend. Clobazam ist ein 1,5-Benzodiazepin, das an GABA-A-Rezeptoren die hemmende Wirkung des Botenstoffs GABA verstärkt. Sein aktiver Hauptmetabolit N-Desmethylclobazam (Norclobazam) hat eine lange Halbwertszeit und trägt wesentlich zur Wirkung bei, besonders bei Epilepsie. Gebildet wird er über CYP3A4, abgebaut über CYP2C19.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Müdigkeit"],"haeufig":["Schwindel, Kopfschmerzen, Zittern","Gangunsicherheit (Ataxie), verwaschene Sprache","Reizbarkeit, Aggressivität, Unruhe, depressive Verstimmung","Konzentrationsstörungen","Mundtrockenheit, Verstopfung, Übelkeit","Appetitverlust"],"gelegentlich":["Gedächtnisstörungen (Amnesie)","Hautausschlag","Doppelbilder, Augenzittern (Nystagmus)","Verminderte Libido"],"unbekannt":["Atemdämpfung","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Paradoxe Reaktionen, Halluzinationen","Abhängigkeit; Entzugssymptome und Rebound-Angst beim Absetzen","Stürze bei älteren Menschen","Nachlassende Wirkung bei Epilepsie (Toleranz)"]},"schwangerschaft":"Im ersten Drittel nur bei zwingendem Grund. Bei Einnahme in der Spätschwangerschaft können beim Neugeborenen Atemprobleme, Muskelschwäche, Unterkühlung und Entzugssymptome auftreten.","stillzeit":"Geht in die Muttermilch über; in der Stillzeit kontraindiziert – nicht stillen.","hinweise":["Kann abhängig machen: nicht abrupt absetzen, sondern ärztlich ausschleichen – bei Epilepsie drohen sonst Anfälle.","Keinen Alkohol trinken; Fahrtüchtigkeit ist beeinträchtigt.","Ältere Menschen: erhöhte Sturzgefahr."],"darreichung":["Tabletten"]},"clobetasol":{"wirkmechanismus":"Hemmt Entzündung, Juckreiz und übermässige Zellteilung in der Haut sehr stark. Clobetasolpropionat bindet an den Glukokortikoid-Rezeptor der Hautzellen und unterdrückt die Bildung entzündungsfördernder Botenstoffe; zusätzlich verengt es die kleinen Hautgefässe und bremst die Vermehrung der Hautzellen (antiproliferative Wirkung). Es gehört zu den stärksten äusserlich angewendeten Kortikosteroiden (Klasse IV) und kann bei grossflächiger oder langer Anwendung in relevanter Menge in den Körper gelangen.","nebenwirkungen":{"haeufig":["Juckreiz","Brennen oder Schmerzen der Haut an der Auftragsstelle"],"gelegentlich":["Hautverdünnung (Atrophie)","Dehnungsstreifen (Striae)","Erweiterte Äderchen (Teleangiektasien)"],"sehrSelten":["Kortison-Wirkungen im ganzen Körper: Cushing-Syndrom, Nebennierenschwäche, erhöhter Blutzucker, Bluthochdruck, Wachstumsverzögerung bei Kindern","Grauer und grüner Star (Katarakt, Glaukom)","Opportunistische Hautinfektionen","Allergische Kontaktdermatitis und andere Überempfindlichkeitsreaktionen","Verschlechterung der Psoriasis, pustulöse Psoriasis","Pigmentveränderungen, vermehrte Behaarung, Akne, rosazeaartige Hautentzündung"],"unbekannt":["Verschwommenes Sehen (Chorioretinopathie)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung, so kurz und kleinflächig wie möglich; in Tierversuchen traten nach Anwendung starker Kortikosteroide Fehlbildungen auf.","stillzeit":"Nach Abwägung kurzfristig und kleinflächig möglich; nicht auf die Brust auftragen.","hinweise":["Höchstens 50 g Creme oder Salbe pro Woche und in der Regel nicht länger als 4 Wochen anwenden.","Dünn auftragen und danach die Hände waschen; luftdichte Verbände nur auf ärztliche Anweisung.","Nach Besserung nicht abrupt absetzen, sondern ausschleichen oder auf ein schwächeres Präparat wechseln.","Shampoo (Clobex) auf die trockene Kopfhaut auftragen, 15 Minuten einwirken lassen und gründlich ausspülen."],"darreichung":["Creme","Salbe","Lösung für die Kopfhaut","Shampoo"]},"clodronsaeure":{"wirkmechanismus":"Hemmt den Knochenabbau durch die knochenabbauenden Zellen (Osteoklasten). Clodronsäure lagert sich an das Knochenmineral (Hydroxylapatit) an und wird von den Osteoklasten aufgenommen. In der Zelle entsteht daraus ein nicht spaltbares ATP-Analogon, das den Energiestoffwechsel stört und den Zelltod (Apoptose) der Osteoklasten auslöst. Dadurch sinken Knochenabbau und Calciumfreisetzung ins Blut.","nebenwirkungen":{"haeufig":["Durchfall","Übelkeit, Erbrechen","Hypokalzämie (tiefes Calcium) ohne Beschwerden","Leichter Anstieg der Leberwerte (Transaminasen)"],"selten":["Hypokalzämie mit Beschwerden (Kribbeln, Muskelkrämpfe)","Erhöhtes Parathormon und erhöhte alkalische Phosphatase im Blut","Überempfindlichkeitsreaktionen der Haut","Verschlechterung der Atmung bei Analgetika-Asthma","Atypische Oberschenkelbrüche"],"sehrSelten":["Osteonekrose (Absterben von Knochen) des äusseren Gehörgangs"],"unbekannt":["Kiefernekrose (Absterben von Kieferknochen)","Nierenfunktionsstörung bis Nierenversagen, vor allem nach rascher Infusion","Augenentzündungen (z. B. Uveitis)","Starke Knochen-, Gelenk- oder Muskelschmerzen"]},"schwangerschaft":"Nicht anwenden: keine ausreichenden Daten, Bisphosphonate können die Skelettentwicklung des Ungeborenen beeinträchtigen.","stillzeit":"Nicht anwenden; es ist nicht bekannt, ob Clodronsäure in die Muttermilch übergeht.","hinweise":["Kapseln und Tabletten nüchtern mit einem Glas Leitungswasser einnehmen; danach mindestens 1 Stunde nichts essen, nur Wasser trinken und keine anderen Medikamente einnehmen – besonders keine Milch und kein Calcium.","Gute Zahnpflege und regelmässige Zahnkontrollen; vor Zahneingriffen die Behandlung angeben.","Genügend trinken; Nierenwerte und Calcium im Blut werden regelmässig kontrolliert."],"darreichung":["Kapseln","Filmtabletten","Infusionskonzentrat"]},"clofarabin":{"wirkmechanismus":"Hemmt die Vermehrung von Leukämiezellen und löst deren Absterben aus. Clofarabin wird in der Zelle durch die Desoxycytidinkinase zum wirksamen Triphosphat aktiviert. Dieses hemmt die Ribonukleotid-Reduktase und DNA-Polymerasen, wird in die DNA eingebaut und stört so DNA-Synthese und -Reparatur. Zusätzlich schädigt es die Mitochondrienmembran und setzt damit den programmierten Zelltod (Apoptose) in Gang.","nebenwirkungen":{"sehrHaeufig":["Febrile Neutropenie (Fieber bei Mangel an Abwehrzellen)","Übelkeit, Erbrechen, Durchfall","Kopfschmerzen, Angst","Hitzegefühl (Flush)","Hand-Fuss-Syndrom (schmerzhafte Rötung von Handflächen und Fusssohlen), Juckreiz","Fieber, Schleimhautentzündung, Müdigkeit"],"haeufig":["Infektionen bis zur Sepsis und zum septischen Schock, Pilz- und Herpesinfektionen","Tumorlysesyndrom","Systemisches Entzündungsreaktionssyndrom (SIRS), Kapillarlecksyndrom, Multiorganversagen","Blutdruckabfall, Herzrasen, Perikarderguss (Flüssigkeit im Herzbeutel)","Erhöhte Leberwerte, Gelbsucht, venookklusive Lebererkrankung","Akutes Nierenversagen, Blut im Urin","Schläfrigkeit, Kribbeln, Zittern, Hörverlust","Magen-Darm-Blutungen, Mundschleimhautentzündung, Bauchschmerzen"],"unbekannt":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Enterokolitis, inkl. neutropenischer und pseudomembranöser Kolitis","Hyponatriämie (Natriummangel)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit; im Tierversuch fruchtschädigend. Frauen im gebärfähigen Alter und sexuell aktive Männer müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert: vor, während und nach der Behandlung nicht stillen.","hinweise":["Behandlung im Spital durch erfahrene Fachpersonen; während der Behandlungstage ausreichend Flüssigkeit (Infusionen, Trinken).","Blutbild, Nieren- und Leberwerte, Blutdruck und Atmung werden engmaschig kontrolliert; Atemnot oder Hautausschlag sofort melden.","Schwindel, Schläfrigkeit oder Ohnmacht können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"clomethiazol":{"wirkmechanismus":"Wirkt beruhigend, schlaffördernd und krampfhemmend. Clomethiazol ist chemisch mit dem Thiazolteil von Vitamin B1 verwandt und verstärkt die Wirkung des hemmenden Botenstoffs GABA am GABA-A-Rezeptor über eine eigene Bindungsstelle. Es wirkt rasch und hat eine kurze Halbwertszeit von wenigen Stunden; bei Leberzirrhose und im Alter ist der Abbau deutlich verlangsamt.","nebenwirkungen":{"haeufig":["Kribbeln und Brennen in der Nase, Niesreiz","Vermehrte Bronchial- und Speichelsekretion"],"unbekannt":["Müdigkeit, Benommenheit, Kopfschmerzen","Atemdepression (Atemdämpfung)","Blutdruckabfall, Herzklopfen","Magenbrennen, Übelkeit, Erbrechen, Durchfall","Hautausschlag, Juckreiz, Bindehautreizung","Anaphylaxie (schwere allergische Reaktion)","Erhöhte Leberwerte, Gelbsucht","Abhängigkeit und Entzugserscheinungen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach strenger ärztlicher Abwägung. Vor der Geburt angewendet kann es beim Neugeborenen Atemdämpfung und Muskelschlaffheit verursachen.","stillzeit":"Geht in die Muttermilch über – während der Anwendung nicht stillen.","hinweise":["Wegen hohen Abhängigkeitsrisikos nur kurzfristig und unter ärztlicher Kontrolle anwenden.","Auf keinen Fall mit Alkohol kombinieren – auch kleine Mengen können gefährlich sein.","Kein Autofahren und kein Bedienen von Maschinen während der Behandlung."],"darreichung":["Kapseln"]},"clomifen":{"wirkmechanismus":"Bewirkt, dass die Hirnanhangsdrüse mehr eisprungfördernde Hormone ausschüttet. Clomifen besetzt als nichtsteroidaler Östrogenrezeptor-Modulator die Östrogenrezeptoren im Hypothalamus und hebt so die hemmende Rückkopplung durch körpereigenes Östrogen auf. Dadurch steigt die Ausschüttung von GnRH und in der Folge von FSH und LH, was die Reifung eines Eibläschens (Follikel) und den Eisprung auslöst.","nebenwirkungen":{"sehrHaeufig":["Vergrösserung der Eierstöcke","Hitzewallungen"],"haeufig":["Bauch- und Unterleibsbeschwerden, Blähgefühl","Übelkeit, Erbrechen","Brustspannen","Sehstörungen (Verschwommensehen, Flimmern, Lichtblitze)","Kopfschmerzen","Zwischenblutungen"],"unbekannt":["Ovarielles Überstimulationssyndrom (OHSS)","Schwindel, Nervosität, Schlafstörungen, depressive Verstimmung","Hautausschlag, Nesselsucht, Haarausfall","Bauchspeicheldrüsenentzündung bei stark erhöhten Triglyceriden"]},"schwangerschaft":"Kontraindiziert. Vor jedem Behandlungszyklus muss eine Schwangerschaft ausgeschlossen werden.","stillzeit":"Nicht anwenden; Clomifen kann zudem die Milchbildung vermindern.","hinweise":["Behandlung nur unter fachärztlicher Kontrolle mit Ultraschall; in der Regel nicht mehr als 6 Zyklen.","Bei Sehstörungen sofort absetzen, augenärztlich abklären lassen und nicht Auto fahren.","Starke Bauchschmerzen, Blähbauch oder rasche Gewichtszunahme können auf eine Überstimulation hinweisen – sofort ärztlich melden.","Die Wahrscheinlichkeit für Zwillinge oder Mehrlinge ist erhöht."],"darreichung":["Tabletten"]},"clomipramin":{"wirkmechanismus":"Hellt die Stimmung auf und vermindert Zwangsgedanken und Angst, indem es die Konzentration von Botenstoffen im Gehirn erhöht. Clomipramin hemmt besonders stark die Wiederaufnahme von Serotonin und – vor allem über sein Abbauprodukt Desmethylclomipramin – auch von Noradrenalin in die Nervenzellen. Zusätzlich blockiert es Muskarin-, Histamin-H1- und Alpha-1-Rezeptoren, was Nebenwirkungen wie Mundtrockenheit, Müdigkeit und Blutdruckabfall erklärt. Die stimmungsaufhellende Wirkung setzt meist erst nach 2–4 Wochen ein.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Müdigkeit, Unruhe","Schwindel, Zittern (Tremor), Kopfschmerzen, Muskelzuckungen (Myoklonien)","Mundtrockenheit, Verstopfung, Übelkeit","Vermehrtes Schwitzen","Sehstörungen (Akkommodationsstörungen, verschwommenes Sehen)","Störungen beim Wasserlassen","Appetit- und Gewichtszunahme","Libido- und Potenzstörungen"],"haeufig":["Verwirrtheit, Desorientierung, Halluzinationen (vor allem bei älteren Menschen)","Angst, Agitiertheit, Schlafstörungen, Albträume, Manie, Aggressivität","Konzentrations- und Gedächtnisstörungen, Sprachstörungen, Kribbeln (Parästhesien)","Herzrasen, Herzklopfen, Blutdruckabfall beim Aufstehen (orthostatische Hypotonie), EKG-Veränderungen","Erbrechen, Bauchschmerzen, Durchfall, Appetitlosigkeit","Erhöhte Leberwerte","Hautausschlag, Juckreiz, Lichtempfindlichkeit","Ohrgeräusche (Tinnitus), Geschmacksstörungen, Milchfluss (Galaktorrhö)"],"gelegentlich":["Krampfanfälle","Gangunsicherheit (Ataxie)","Herzrhythmusstörungen","Blutdruckanstieg"],"sehrSelten":["Agranulozytose (starke Verminderung bestimmter weisser Blutkörperchen) und andere Blutbildveränderungen","Hyponatriämie durch inadäquate ADH-Sekretion (SIADH)","Akutes Glaukom","Leberentzündung (Hepatitis)","Reizleitungsstörungen des Herzens, QT-Verlängerung, Torsade de pointes","Anaphylaxie, Ödeme, Haarausfall","Malignes neuroleptisches Syndrom","Harnverhalt, allergische Lungenentzündung (Alveolitis)"],"unbekannt":["Serotoninsyndrom","Extrapyramidale Störungen (z. B. Akathisie)","Suizidgedanken und suizidales Verhalten","Erhöhtes Risiko für Knochenbrüche"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme bis zur Geburt können beim Neugeborenen Entzugs- und Anpassungsstörungen auftreten (Atemprobleme, Zittern, Trinkschwäche, Krampfanfälle).","stillzeit":"Clomipramin geht in die Muttermilch über; Stillen wird während der Behandlung nicht empfohlen.","hinweise":["Die stimmungsaufhellende Wirkung setzt meist erst nach 2–4 Wochen ein, Nebenwirkungen wie Mundtrockenheit und Müdigkeit dagegen früh.","Nicht abrupt absetzen (Übelkeit, Kopfschmerzen, Unruhe, Schlafstörungen), sondern schrittweise nach ärztlicher Anleitung reduzieren.","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden.","Vor und während der Behandlung EKG und Blutdruck, bei Bedarf Blutbild und Leberwerte kontrollieren; Haut vor starker Sonne schützen."],"darreichung":["Dragées","Retardtabletten"]},"clonazepam":{"wirkmechanismus":"Dämpft die Erregbarkeit von Nervenzellen und verhindert so Krampfanfälle; wirkt zudem beruhigend und muskelentspannend. Clonazepam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt die hemmende Wirkung des Botenstoffs GABA, indem es die Öffnungshäufigkeit des Chloridkanals erhöht. Es wird in der Leber unter Beteiligung von CYP3A4 abgebaut und hat eine lange Halbwertszeit (etwa 30–40 Stunden).","nebenwirkungen":{"unbekannt":["Müdigkeit, Schläfrigkeit, verlangsamte Reaktionen (besonders zu Behandlungsbeginn)","Muskelschwäche, Schwindel, Gang- und Koordinationsstörungen (Ataxie)","Konzentrations- und Gedächtnisstörungen","Paradoxe Reaktionen (Unruhe, Reizbarkeit, Aggression, Halluzinationen), besonders bei Kindern und älteren Menschen","Vermehrter Speichel- und Bronchialschleim bei Säuglingen und Kleinkindern","Atemdepression (besonders bei Injektion)","Abhängigkeit und Entzugssymptome bis zu Krampfanfällen beim abrupten Absetzen","Zunahme der Anfallshäufigkeit bei bestimmten Epilepsieformen"]},"schwangerschaft":"Nur bei zwingender Indikation nach ärztlicher Abwägung; bei Einnahme in der Spätschwangerschaft drohen beim Neugeborenen Trinkschwäche, Muskelschlaffheit, Atemprobleme und Entzugssymptome.","stillzeit":"Geht in die Muttermilch über; Stillen wird nicht empfohlen bzw. nur unter ärztlicher Überwachung des Kindes auf Schläfrigkeit und Trinkschwäche.","hinweise":["Nicht abrupt absetzen – Gefahr von Entzugssymptomen und Krampfanfällen; schrittweise nach ärztlicher Anweisung ausschleichen.","Kein Alkohol; Fahrtüchtigkeit ist besonders zu Beginn deutlich eingeschränkt.","Bei längerer Anwendung kann sich die Wirkung abschwächen und eine Abhängigkeit entstehen."],"darreichung":["Tabletten","Tropfen (Lösung zum Einnehmen)","Injektionslösung"]},"clonidin":{"wirkmechanismus":"Senkt den Blutdruck, indem es im Gehirn die Signale des sympathischen Nervensystems an Herz und Gefässe drosselt. Clonidin stimuliert Alpha-2-Rezeptoren und Imidazolin-Rezeptoren im Hirnstamm; dadurch sinken die Ausschüttung von Noradrenalin, der Gefässwiderstand und die Herzfrequenz. Die zentrale Wirkung erklärt auch Müdigkeit und Mundtrockenheit. Nach plötzlichem Absetzen kann der Sympathikus überschiessend reagieren (Rebound-Hochdruck).","nebenwirkungen":{"sehrHaeufig":["Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Schwindel","Müdigkeit, Sedierung","Mundtrockenheit"],"haeufig":["Depression, Schlafstörungen","Kopfschmerzen","Verstopfung, Übelkeit, Erbrechen","Schmerzen der Speicheldrüsen","Erektionsstörungen","Erschöpfung"],"gelegentlich":["Albträume, Wahnvorstellungen, Halluzinationen","Kribbeln (Parästhesien)","Sinusbradykardie","Raynaud-Syndrom (Weissfinger)","Juckreiz, Hautausschlag, Nesselsucht","Unwohlsein"],"selten":["AV-Block","Verminderter Tränenfluss","Darmlähmung (Pseudoobstruktion des Dickdarms)","Gynäkomastie (Brustvergrösserung beim Mann)","Haarausfall","Erhöhter Blutzucker"],"unbekannt":["Verwirrtheit","Verminderte Libido","Akkommodationsstörungen (Probleme beim Scharfsehen)","Bradyarrhythmie"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; Clonidin gelangt zum Kind und kann beim Neugeborenen Blutdruck und Puls senken.","stillzeit":"Geht in die Muttermilch über; Anwendung in der Stillzeit nicht empfohlen.","hinweise":["Nie abrupt absetzen – sonst drohen starker Blutdruckanstieg, Herzrasen und Unruhe; immer über einige Tage ausschleichen.","Alkohol verstärkt die Müdigkeit; Fahrtüchtigkeit kann besonders zu Beginn eingeschränkt sein.","Langsam aufstehen, um Schwindel durch Blutdruckabfall zu vermeiden."],"darreichung":["Tabletten","Injektionslösung"]},"clopamid":{"wirkmechanismus":"Fördert die Ausscheidung von Salz und Wasser über die Niere und senkt dadurch den Blutdruck. Clopamid hemmt im frühen distalen Nierentubulus den Natrium-Chlorid-Kotransporter, sodass mehr Natrium, Chlorid und Wasser ausgeschieden werden; dabei gehen auch Kalium und Magnesium verloren, während Calcium zurückgehalten wird. Bei Dauerbehandlung trägt eine Abnahme des Gefässwiderstands zur Blutdrucksenkung bei.","nebenwirkungen":{"unbekannt":["Hypokaliämie (Kaliummangel), Hyponatriämie (Natriummangel), Magnesiummangel","Hyperurikämie (erhöhte Harnsäure), Gichtanfälle","Hyperglykämie (erhöhter Blutzucker), erhöhte Blutfette","Schwindel, Blutdruckabfall beim Aufstehen, Müdigkeit","Magen-Darm-Beschwerden, Appetitlosigkeit","Lichtempfindlichkeit der Haut, Hautausschlag","Potenzstörungen","Blutbildveränderungen (Thrombozytopenie, Agranulozytose), Pankreatitis"]},"schwangerschaft":"Nicht empfohlen: Thiazid-Diuretika können die Durchblutung der Plazenta vermindern und beim Neugeborenen Elektrolytstörungen und Blutplättchenmangel verursachen; nur nach strenger ärztlicher Abwägung.","stillzeit":"Geht in die Muttermilch über und kann die Milchbildung hemmen – nicht empfohlen.","hinweise":["Morgens einnehmen, damit der vermehrte Harndrang die Nachtruhe nicht stört.","Kalium, Natrium, Nierenwerte, Blutzucker und Harnsäure regelmässig kontrollieren.","Haut vor starker Sonne schützen.","Das Kombinationspräparat (mit dem Betablocker Pindolol) nicht abrupt absetzen."],"darreichung":["Tabletten (Kombinationspräparat)"]},"clopidogrel":{"wirkmechanismus":"Verhindert, dass Blutplättchen verklumpen und Gerinnsel in den Arterien bilden. Clopidogrel ist eine unwirksame Vorstufe (Prodrug), die in der Leber vor allem über das Enzym CYP2C19 in einen aktiven Metaboliten umgewandelt wird. Dieser blockiert den ADP-Rezeptor P2Y12 der Blutplättchen irreversibel und hemmt damit deren Aktivierung. Die Hemmung hält für die ganze Lebensdauer der Plättchen (7–10 Tage) an. Bei genetisch langsamer CYP2C19-Aktivität entsteht weniger Wirkstoff, die Wirkung ist dann schwächer.","nebenwirkungen":{"haeufig":["Blutergüsse (Hämatome), Hautblutungen","Nasenbluten","Magen-Darm-Blutungen","Durchfall, Bauchschmerzen, Verdauungsbeschwerden","Nachblutung an Punktionsstellen"],"gelegentlich":["Hirnblutung (teils tödlich)","Verminderung von Blutplättchen und weissen Blutkörperchen, Eosinophilie","Kopfschmerzen, Schwindel, Kribbeln","Magen- und Zwölffingerdarmgeschwüre, Gastritis, Übelkeit, Erbrechen, Verstopfung","Augenblutungen","Hautausschlag, Juckreiz","Blut im Urin"],"selten":["Neutropenie, auch schwere (Mangel an weissen Blutkörperchen)","Drehschwindel","Blutungen im hinteren Bauchraum (retroperitoneal)","Gynäkomastie (Brustvergrösserung beim Mann)"],"sehrSelten":["Thrombotisch-thrombozytopenische Purpura (TTP)","Agranulozytose, aplastische Anämie, Panzytopenie, schwere Thrombozytopenie","Erworbene Hämophilie A","Anaphylaktoide Reaktionen, Serumkrankheit, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Akutes Leberversagen, Hepatitis, Pankreatitis","Schwere, auch tödliche Blutungen","Interstitielle oder eosinophile Pneumonie, Bronchospasmus"],"unbekannt":["Insulin-Autoimmunsyndrom mit schwerer Unterzuckerung","Kounis-Syndrom (allergisch ausgelöste Brustenge)","Kreuzallergie mit anderen Thienopyridinen"]},"schwangerschaft":"Keine ausreichenden Erfahrungen beim Menschen; vorsichtshalber in der Schwangerschaft nicht anwenden, ausser nach strenger ärztlicher Abwägung.","stillzeit":"Im Tierversuch Übergang in die Muttermilch; während der Behandlung nicht stillen.","hinweise":["Nicht eigenmächtig absetzen – besonders nach Stent-Einlage drohen Stentverschluss und Herzinfarkt.","Vor Operationen und Zahnbehandlungen die Einnahme angeben; ein Pausieren (meist 7 Tage vorher) nur nach ärztlicher Anordnung.","Als Magenschutz eignet sich eher Pantoprazol als Omeprazol oder Esomeprazol.","Bei Fieber, Schwäche, Verwirrtheit, Gelbsucht oder punktförmigen Hautblutungen sofort ärztliche Hilfe holen (TTP)."],"darreichung":["Filmtabletten"]},"clorazepat":{"wirkmechanismus":"Wirkt angstlösend, beruhigend, muskelentspannend und krampfhemmend. Clorazepat ist eine Vorstufe (Prodrug): Schon im Magen wird es zu Nordazepam (Desmethyldiazepam) umgewandelt, dem eigentlichen Wirkstoff. Nordazepam verstärkt an GABA-A-Rezeptoren die hemmende Wirkung des Botenstoffs GABA. Wegen seiner sehr langen Halbwertszeit (bis zu mehreren Tagen) reichert es sich bei regelmässiger Einnahme an.","nebenwirkungen":{"haeufig":["Müdigkeit, Schläfrigkeit, Benommenheit (auch am nächsten Tag)","Schwindel, Gangunsicherheit (Ataxie)","Verlangsamte Reaktionen, Konzentrationsstörungen","Muskelschwäche"],"unbekannt":["Anterograde Amnesie (Gedächtnislücken)","Paradoxe Reaktionen (Unruhe, Aggressivität, Halluzinationen), v. a. bei älteren Menschen","Atemdämpfung","Abhängigkeit; Entzugssymptome und Rebound-Angst beim Absetzen","Stürze und Knochenbrüche bei älteren Menschen","Hervortreten einer bestehenden Depression","Hautreaktionen und andere Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme gegen Ende der Schwangerschaft oder in hohen Dosen können beim Neugeborenen Atemprobleme, Muskelschwäche, Unterkühlung (Floppy-Infant-Syndrom) und Entzugssymptome auftreten.","stillzeit":"Geht in die Muttermilch über und kann sich beim Säugling anreichern; nicht stillen.","hinweise":["Kann abhängig machen: so kurz wie möglich anwenden und nach längerer Einnahme nicht abrupt absetzen, sondern ausschleichen.","Keinen Alkohol trinken; Fahrtüchtigkeit ist beeinträchtigt, auch noch am Folgetag.","Ältere Menschen: erhöhte Sturzgefahr, besonders nachts."],"darreichung":["Kapseln","Tabletten"]},"clotiapin":{"wirkmechanismus":"Beruhigt und dämpft psychotische Symptome wie Wahn und Halluzinationen. Clotiapin ist ein Dibenzothiazepin-Neuroleptikum und chemisch mit Clozapin und Quetiapin verwandt. Es blockiert Dopamin-D2- und Serotonin-5-HT2-Rezeptoren sowie Histamin-H1-, Alpha-1-adrenerge und Muskarinrezeptoren; daraus erklären sich die ausgeprägte Sedierung, der Blutdruckabfall und anticholinerge Wirkungen.","nebenwirkungen":{"unbekannt":["Starke Müdigkeit, Benommenheit, Schwindel","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Herzrasen","Mundtrockenheit, Verstopfung, Harnverhalt, Sehstörungen (anticholinerge Wirkungen)","Gewichtszunahme","Bewegungsstörungen (Zittern, Muskelsteifigkeit, Sitzunruhe), Krampfanfälle","Blutbildveränderungen (Leukopenie, Agranulozytose)","Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen, Schläfrigkeit und Entzugssymptome auftreten.","stillzeit":"Stillen wird nicht empfohlen.","hinweise":["Wirkt stark beruhigend: nicht Auto fahren, besonders zu Beginn, und keinen Alkohol trinken.","Langsam aufstehen – Gefahr von Schwindel und Stürzen durch Blutdruckabfall.","Bei Fieber, Halsschmerzen oder Fieber mit Muskelsteifigkeit sofort ärztliche Hilfe holen."],"darreichung":["Tabletten"]},"clotrimazol":{"wirkmechanismus":"Hemmt das Wachstum von Pilzen, indem es den Aufbau ihrer Zellmembran stört. Clotrimazol blockiert das pilzeigene Enzym Lanosterol-14-alpha-Demethylase (ein Cytochrom-P450-Enzym) und damit die Bildung von Ergosterol, dem wichtigsten Baustein der Pilzzellmembran. Die Membran wird durchlässig; in niedriger Konzentration wirkt Clotrimazol wachstumshemmend (fungistatisch), in hoher abtötend (fungizid). Es wirkt gegen Dermatophyten, Hefen und Schimmelpilze sowie gegen einige grampositive Bakterien (z. B. Erreger des Erythrasmas). Auf Haut oder Schleimhaut aufgetragen gelangt nur sehr wenig Wirkstoff ins Blut.","nebenwirkungen":{"unbekannt":["Haut: Rötung, Brennen, Stechen, Juckreiz, Reizung, Schuppung, Bläschen, Schwellung","Scheide: Brennen, Juckreiz, Rötung, Schwellung, Beschwerden, Ausschlag","Unterleibsschmerzen, vaginale Blutungen","Allergische Reaktionen bis zu Kreislaufkollaps (Synkope, Blutdruckabfall), Atemnot, Nesselsucht"]},"schwangerschaft":"Kann nach ärztlicher Rücksprache angewendet werden (sehr geringe Aufnahme ins Blut). Vaginaltabletten in der Schwangerschaft ohne Applikator einführen.","stillzeit":"Anwendung möglich; nicht im Brustbereich auftragen bzw. die Haut vor dem Stillen gründlich reinigen.","hinweise":["Hautpilz: nach Abklingen der Beschwerden noch etwa 2 Wochen weiterbehandeln, um Rückfälle zu vermeiden.","Scheidenpilz: abends tief in die Scheide einführen; die Behandlung nicht während der Menstruation durchführen. Den Partner bei Beschwerden mitbehandeln.","Latex-Kondome und Diaphragmen sind während und bis mindestens 5 Tage nach vaginaler Anwendung nicht sicher.","Nicht in die Augen bringen und nicht einnehmen; Handtücher und Wäsche häufig wechseln und heiss waschen."],"darreichung":["Creme","Lösung","Paste","Vaginaltabletten","Vaginalcreme"]},"clozapin":{"wirkmechanismus":"Lindert psychotische Beschwerden auch dann, wenn andere Antipsychotika nicht wirken, und verursacht dabei kaum Bewegungsstörungen. Clozapin blockiert Dopamin-Rezeptoren (v. a. D4, schwächer D2) sowie stark Serotonin-5-HT2A-Rezeptoren. Zusätzlich hemmt es Histamin-H1-, Muskarin- und Alpha-1-Rezeptoren, was Müdigkeit, Verstopfung und Blutdruckabfall erklärt. Es wird hauptsächlich über CYP1A2 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Sedierung","Schwindel","Tachykardie (Herzrasen)","Verstopfung","Hypersalivation (vermehrter Speichelfluss, v. a. nachts)"],"haeufig":["Leukopenie, Neutropenie, Eosinophilie","Gewichtszunahme","Krampfanfälle, Muskelzuckungen","Kopfschmerzen, Zittern, Muskelsteife, Sitzunruhe","Orthostatische Hypotonie, Ohnmacht, Bluthochdruck, EKG-Veränderungen","Übelkeit, Erbrechen, Mundtrockenheit, Appetitlosigkeit","Erhöhte Leberwerte","Harninkontinenz, Harnverhalt, meist harmlose Temperaturerhöhung zu Beginn"],"gelegentlich":["Agranulozytose (lebensbedrohlicher Mangel an weissen Blutkörperchen)","Malignes neuroleptisches Syndrom","Sprachstörungen","Stürze"],"selten":["Myokarditis und Perikarditis (Entzündung von Herzmuskel oder Herzbeutel), Herzrhythmusstörungen","Kreislaufkollaps","Erhöhter Blutzucker, Diabetes","Venöse Thromboembolie","Aspiration, Lungenentzündung (teils tödlich)","Verwirrtheit, Delir, Unruhe","Hepatitis, Pankreatitis","Anämie"],"sehrSelten":["Kardiomyopathie, Herzstillstand, plötzlicher unerklärter Tod","Atemdepression bis Atemstillstand","Darmlähmung, Darmverschluss","Fulminante Lebernekrose (akutes Leberversagen)","Thrombozytopenie","Diabetische Ketoazidose, schwere Hyperglykämie","Spätdyskinesien","Priapismus, interstitielle Nephritis"],"unbekannt":["QT-Verlängerung","Herzinfarkt"]},"schwangerschaft":"Begrenzte Erfahrungen; nur nach sorgfältiger Abwägung. Bei Einnahme im letzten Drittel sind beim Neugeborenen Bewegungsstörungen und Entzugssymptome möglich; beim Wechsel von anderen Antipsychotika kann sich die Fruchtbarkeit normalisieren – wirksam verhüten.","stillzeit":"Clozapin geht in die Muttermilch über. Nicht stillen.","hinweise":["Blutbild in den ersten 18 Wochen wöchentlich, danach mindestens monatlich; bei Fieber, Halsschmerzen oder grippeähnlichen Beschwerden sofort ärztliche Kontrolle.","Verstopfung früh behandeln und melden – Gefahr einer lebensbedrohlichen Darmlähmung.","Rauchbeginn, Rauchstopp oder eine Änderung des Kaffeekonsums ärztlich mitteilen.","Nach einem Unterbruch von mehr als 2 Tagen nicht mit der alten Dosis weiterfahren, sondern neu einschleichen."],"darreichung":["Tabletten"]},"cobimetinib":{"wirkmechanismus":"Bremst das Wachstum von Melanomzellen, deren Wachstumssignal durch eine BRAF-Mutation dauerhaft eingeschaltet ist. Cobimetinib hemmt reversibel und selektiv die Kinasen MEK1 und MEK2 im MAPK-Signalweg und verhindert so die Aktivierung von ERK. Zusammen mit dem BRAF-Hemmer Vemurafenib wird der Signalweg an zwei Stellen blockiert, was die Wirkung verstärkt und Resistenzen verzögert.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen","Hautausschlag, akneartige Hautentzündung, Hyperkeratose (Hornhautverdickung)","Lichtempfindlichkeit (Photosensibilität)","Seröse Retinopathie (Flüssigkeit unter der Netzhaut), verschwommenes Sehen","Fieber, Schüttelfrost","Bluthochdruck, Blutungen","Anämie (Blutarmut)","Erhöhte CK-, Leber- und Nierenwerte"],"haeufig":["Abnahme der Herzleistung (verminderte Auswurffraktion)","Pneumonitis (Lungenentzündung ohne Infektion)","Dehydratation (Flüssigkeitsmangel)","Hyponatriämie, Hypophosphatämie, Hyperglykämie (erhöhter Blutzucker)","Plattenepithelkarzinom und Basaliom der Haut, Keratoakanthom"],"gelegentlich":["Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen müssen während und bis 3 Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung und bis 2 Wochen nach der letzten Dosis nicht stillen.","hinweise":["Einnahme im Zyklus: 21 Tage täglich, danach 7 Tage Pause; mit oder ohne Essen.","Konsequenter Sonnenschutz (Kleidung, Sonnencreme mit hohem UV-A- und UV-B-Schutz).","Grapefruit und Grapefruitsaft meiden.","Regelmässige Kontrollen: Herzfunktion, Augen, Haut, Leberwerte und CK."],"darreichung":["Filmtabletten"]},"codein":{"wirkmechanismus":"Dämpft den Hustenreflex im Hirnstamm und lindert Schmerzen. Codein ist selbst nur ein schwacher Agonist am μ-Opioidrezeptor; seine schmerzstillende Wirkung beruht vor allem auf Morphin, das in der Leber über das Enzym CYP2D6 aus einem kleinen Teil der Dosis gebildet wird. Wie viel Morphin entsteht, hängt vom CYP2D6-Erbgut ab: ultraschnelle Metabolisierer bilden gefährlich viel Morphin, langsame Metabolisierer kaum.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen (v. a. zu Beginn)","Obstipation (Verstopfung)"],"haeufig":["Kopfschmerzen","Schläfrigkeit, Benommenheit"],"gelegentlich":["Schlafstörungen","Kurzatmigkeit","Mundtrockenheit","Juckreiz, Hautrötung, Nesselsucht","Ohrensausen (Tinnitus)"],"selten":["Schwere allergische Reaktionen, einschliesslich Stevens-Johnson-Syndrom"],"unbekannt":["Atemdepression (gefährlich abgeflachte Atmung), v. a. bei hohen Dosen oder ultraschnellem CYP2D6-Stoffwechsel","Abhängigkeit und Entzugserscheinungen bei längerer Einnahme","Blutdruckabfall, Ohnmacht","Euphorie oder Verstimmung","Krampf der Gallenwege"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung und kurzfristig. Einnahme kurz vor der Geburt kann beim Neugeborenen Atemdämpfung, längere Einnahme Entzugssymptome verursachen.","stillzeit":"Kontraindiziert: Codein und Morphin gehen in die Muttermilch über; bei ultraschnellem Stoffwechsel der Mutter ist eine lebensgefährliche Atemdämpfung beim Säugling möglich.","hinweise":["Beeinträchtigt die Fahrtüchtigkeit; keinen Alkohol trinken.","Nur kurzfristig und nur bei trockenem Reizhusten anwenden, nicht bei Husten mit viel Schleim.","Kann abhängig machen – nicht länger und nicht höher dosiert einnehmen als verordnet.","Bei Atemnot, starker Schläfrigkeit, sehr engen Pupillen oder Verwirrtheit (Zeichen einer Überdosierung) sofort den Notruf (144) wählen."],"darreichung":["Tabletten","Tropfen","Sirup","Brausetabletten (Kombipräparat)"]},"colchicin":{"wirkmechanismus":"Hemmt die Entzündung im Gelenk, indem es weisse Blutkörperchen daran hindert, einzuwandern und Entzündungsstoffe freizusetzen. Colchicin bindet an Tubulin und hemmt den Aufbau der Mikrotubuli; dadurch werden Beweglichkeit, Zellteilung und Aktivierung der neutrophilen Granulozyten sowie das NLRP3-Inflammasom gebremst. Es senkt die Harnsäure nicht. Abgebaut und ausgeschieden wird es über CYP3A4 und P-Glykoprotein; die therapeutische Breite ist sehr gering.","nebenwirkungen":{"haeufig":["Durchfall","Übelkeit, Erbrechen","Bauchschmerzen"],"unbekannt":["Knochenmarkschädigung mit Agranulozytose, Thrombozytopenie oder aplastischer Anämie","Periphere Neuropathie (Nervenschädigung)","Myopathie (Muskelerkrankung), Rhabdomyolyse (Muskelzerfall)","Magen-Darm-Blutungen","Leberschäden","Haarausfall, Hautausschlag","Störung der Spermienbildung, Ausbleiben der Regelblutung"]},"schwangerschaft":"Kontraindiziert; einzige Ausnahme ist das familiäre Mittelmeerfieber, bei dem die Behandlung nach ärztlicher Abwägung weitergeführt werden kann.","stillzeit":"Geht in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Die verordnete Höchstdosis beim akuten Anfall nicht überschreiten; schon geringe Überdosen können tödlich sein. Für Kinder unerreichbar aufbewahren.","Bei Durchfall, Übelkeit oder Erbrechen (erste Vergiftungszeichen) Einnahme stoppen und ärztlichen Rat einholen.","Keinen Grapefruitsaft trinken.","Bei Langzeitbehandlung Blutbild sowie Nieren- und Leberwerte regelmässig kontrollieren."],"darreichung":["Dragées (überzogene Tabletten)"]},"colecalciferol-vitamin-d3":{"wirkmechanismus":"Stellt dem Körper Vitamin D zur Verfügung, das er für die Aufnahme von Calcium und gesunde Knochen braucht. Colecalciferol ist eine Vorstufe: In der Leber wird es zu 25-Hydroxyvitamin D (Calcifediol, dem Speicher- und Messwert im Blut) und in der Niere zu 1,25-Dihydroxyvitamin D (Calcitriol, der aktiven Form) umgewandelt. Calcitriol steigert über den Vitamin-D-Rezeptor die Aufnahme von Calcium und Phosphat im Darm, fördert die Mineralisierung des Knochens und bremst die Ausschüttung von Parathormon. Weil Vitamin D im Fettgewebe gespeichert wird, wirkt es lange nach und kann auch wöchentlich oder monatlich gegeben werden.","nebenwirkungen":{"gelegentlich":["Hyperkalzämie (erhöhtes Calcium im Blut)","Hyperkalziurie (erhöhtes Calcium im Urin)"],"selten":["Juckreiz, Hautausschlag, Nesselsucht"],"unbekannt":["Bei Überdosierung: Übelkeit, Erbrechen, Verstopfung, Appetitlosigkeit, starker Durst, vermehrtes Wasserlassen, Muskelschwäche, Verwirrtheit","Nierensteine und Verkalkungen in Niere und Gefässen bei langdauernder Überdosierung"]},"schwangerschaft":"In den empfohlenen Dosen erlaubt und bei Mangel sinnvoll; Überdosierungen vermeiden, da eine anhaltende Hyperkalzämie dem Kind schaden kann.","stillzeit":"In üblichen Dosen erlaubt; Vitamin D geht in die Muttermilch über, ersetzt aber nicht die Vitamin-D-Gabe an den Säugling.","hinweise":["Am besten zu einer Mahlzeit einnehmen, da fetthaltige Speisen die Aufnahme verbessern.","Hoch dosierte Wochen- oder Monatsdosen nicht mit täglichen Präparaten verwechseln und nicht mehrere Vitamin-D-Präparate kombinieren.","Bei hohen Dosen, Nierenkrankheit oder gleichzeitiger Calciumeinnahme Calcium im Blut kontrollieren lassen.","In der Schweiz wird für Säuglinge und Kleinkinder in den ersten 3 Lebensjahren eine tägliche Vitamin-D-Gabe empfohlen."],"darreichung":["Tropfen","Kapseln","Tabletten","Ampullen (hoch dosiert)"]},"colesevelam":{"wirkmechanismus":"Senkt das LDL-Cholesterin, indem es im Darm Gallensäuren bindet. Colesevelam ist ein nicht resorbierbares, wasserunlösliches Polymer mit hoher Bindungskapazität für Gallensäuren, die so mit dem Stuhl ausgeschieden werden. Die Leber bildet aus Cholesterin neue Gallensäuren und vermehrt ihre LDL-Rezeptoren, wodurch das LDL-Cholesterin im Blut sinkt. Zusammen mit einem Statin verstärken sich die Wirkungen.","nebenwirkungen":{"sehrHaeufig":["Blähungen","Obstipation (Verstopfung)"],"haeufig":["Kopfschmerzen","Übelkeit, Erbrechen, Bauchschmerzen, aufgeblähter Bauch","Durchfall, Dyspepsie (Verdauungsbeschwerden), veränderter Stuhl","Anstieg der Triglyceride im Blut"],"gelegentlich":["Schluckbeschwerden (Dysphagie)","Muskelschmerzen (Myalgie)","Erhöhte Leberwerte (Transaminasen)"],"unbekannt":["Darmverschluss (v. a. bei Vorerkrankungen des Darms)","Pankreatitis (Bauchspeicheldrüsenentzündung)"]},"schwangerschaft":"Wird nicht ins Blut aufgenommen, kann aber die Aufnahme fettlöslicher Vitamine vermindern. Nur nach ärztlicher Abwägung anwenden.","stillzeit":"Geht nicht in die Muttermilch über; Anwendung nach ärztlicher Abwägung möglich, auf ausreichende Vitaminversorgung achten.","hinweise":["Mit einer Mahlzeit und ausreichend Flüssigkeit einnehmen; Tabletten ganz schlucken.","Andere Medikamente, deren Aufnahme vermindert werden kann, mindestens 4 Stunden vorher einnehmen.","Starke Bauchschmerzen oder anhaltende Verstopfung ärztlich melden."],"darreichung":["Filmtabletten"]},"colestyramin":{"wirkmechanismus":"Bindet im Darm Gallensäuren, die dann mit dem Stuhl ausgeschieden statt wieder aufgenommen werden. Colestyramin ist ein nicht resorbierbares Anionenaustauscherharz; der Gallensäureverlust unterbricht den enterohepatischen Kreislauf. Die Leber bildet deshalb aus Cholesterin neue Gallensäuren und vermehrt ihre LDL-Rezeptoren, sodass das LDL-Cholesterin im Blut sinkt. Bei Gallestau vermindert die Bindung der Gallensäuren den Juckreiz, bei gallensäurebedingtem Durchfall deren abführende Wirkung im Dickdarm.","nebenwirkungen":{"unbekannt":["Obstipation (Verstopfung), bis zur Kotstauung","Völlegefühl, Blähungen, Bauchschmerzen, Übelkeit, Sodbrennen","Durchfall, Fettstühle (Steatorrhö)","Mangel an fettlöslichen Vitaminen (A, D, K) mit Blutungsneigung","Hyperchlorämische Azidose (Übersäuerung des Blutes), v. a. bei Kindern","Darmverschluss","Hautausschlag, Juckreiz","Anstieg der Triglyceride"]},"schwangerschaft":"Wird nicht ins Blut aufgenommen, kann aber die Aufnahme von Vitaminen vermindern. Nur nach ärztlicher Abwägung und mit ausreichender Vitaminversorgung anwenden.","stillzeit":"Geht nicht in die Muttermilch über; ein Vitaminmangel der Mutter kann aber das Kind betreffen. Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Pulver nie trocken einnehmen, sondern in Wasser, Saft oder Suppe einrühren.","Andere Medikamente mindestens 1 Stunde vorher oder 4–6 Stunden nachher einnehmen.","Viel trinken und ballaststoffreich essen – Verstopfung ist die häufigste Nebenwirkung.","Bei Langzeittherapie Vitamine (A, D, K, Folsäure) und Blutgerinnung kontrollieren lassen."],"darreichung":["Pulver zur Herstellung einer Suspension (Beutel)"]},"concizumab":{"wirkmechanismus":"Löst eine körpereigene Bremse der Blutgerinnung, sodass auch ohne Faktor VIII oder IX genügend Thrombin entsteht. Concizumab ist ein humanisierter monoklonaler IgG4-Antikörper, der an die Kunitz-2-Domäne des Tissue Factor Pathway Inhibitors (TFPI) bindet und dessen Hemmung von Faktor Xa aufhebt. Dadurch wird die Thrombinbildung über den Gewebefaktor-Weg verstärkt – unabhängig vom fehlenden Faktor und von Hemmkörpern.","nebenwirkungen":{"haeufig":["Reaktionen an der Injektionsstelle (Rötung, Bluterguss, Juckreiz)","Überempfindlichkeitsreaktionen","Nesselsucht, Hautausschlag, Juckreiz","Erhöhte Gerinnungsmarker im Blut (D-Dimere, Prothrombinfragmente)"],"gelegentlich":["Thromboembolische Ereignisse (z. B. Thrombosen, Herzinfarkt, Lungenembolie)"]},"schwangerschaft":"Keine Erfahrungen; Anwendung nicht empfohlen. Frauen im gebärfähigen Alter sollen während der Behandlung und einige Wochen danach zuverlässig verhüten.","stillzeit":"Unbekannt, ob Concizumab in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Wird täglich mit dem Fertigpen unter die Haut gespritzt; in den ersten Wochen wird der Concizumab-Spiegel gemessen und die Dosis angepasst.","Bei Durchbruchblutungen Faktor- oder Bypassing-Präparate nur in der niedrigsten wirksamen Dosis anwenden und das Vorgehen mit dem Hämophilie-Zentrum absprechen.","Zeichen einer Thrombose (Brustschmerz, Atemnot, Beinschwellung, Lähmungen, Sehstörungen) sofort ärztlich abklären lassen."],"darreichung":["Injektionslösung im Fertigpen"]},"corifollitropin-alfa":{"wirkmechanismus":"Regt mit einer einzigen Injektion eine Woche lang die Reifung mehrerer Eibläschen (Follikel) an. Corifollitropin alfa ist ein gentechnisch hergestelltes FSH, an dessen Beta-Kette ein Teil des hCG-Moleküls (C-terminales Peptid) angehängt ist; dadurch wirkt es etwa doppelt so lange wie FSH. Es bindet an den FSH-Rezeptor und ersetzt in den ersten 7 Tagen der Stimulation die täglichen FSH-Spritzen.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Übelkeit","Müdigkeit","Beckenschmerzen und -beschwerden","Brustbeschwerden (Schmerzen, Spannen)","Ovarielles Überstimulationssyndrom (OHSS)"],"gelegentlich":["Schwindel, Hitzewallungen","Blähbauch, Erbrechen, Durchfall, Verstopfung","Rückenschmerzen","Stieldrehung eines Eierstocks (Ovarialtorsion), vorzeitiger Eisprung","Schmerzen an der Einstichstelle","Reizbarkeit, Stimmungsschwankungen","Erhöhte Leberwerte"],"unbekannt":["Überempfindlichkeitsreaktionen (z. B. Hautausschlag)","Thromboembolie"]},"schwangerschaft":"Nicht angezeigt in der Schwangerschaft.","stillzeit":"Nicht angezeigt in der Stillzeit.","hinweise":["Wird einmalig zu Beginn der Stimulation unter die Haut gespritzt; ab Tag 8 folgt bei Bedarf tägliches FSH.","Regelmässige Ultraschall- und Hormonkontrollen sind nötig, um eine Überstimulation zu vermeiden.","Bei starken Bauchschmerzen, Blähbauch, Übelkeit, Atemnot oder deutlich weniger Urin sofort ärztliche Hilfe holen."],"darreichung":["Injektionslösung in Fertigspritze"]},"covid-19-impfstoff-mrna":{"wirkmechanismus":"Gibt den Körperzellen eine Bauanleitung für das Spike-Protein des Coronavirus, gegen das das Immunsystem dann Abwehr aufbaut. Die modifizierte mRNA ist in Lipid-Nanopartikel verpackt, wird in Zellen am Injektionsort und in Lymphknoten abgelesen und innerhalb weniger Tage abgebaut. Sie gelangt nicht in den Zellkern und verändert das Erbgut nicht. Das gebildete Spike-Protein löst Antikörper und T-Zell-Antworten aus.","nebenwirkungen":{"sehrHaeufig":["Schmerzen und Schwellung an der Einstichstelle","Müdigkeit, Kopfschmerzen","Muskel- und Gelenkschmerzen","Schüttelfrost, Fieber","Übelkeit, Erbrechen, Durchfall","Lymphknotenschwellung in der Achsel"],"haeufig":["Rötung an der Einstichstelle, auch verzögert nach einigen Tagen","Hautausschlag"],"gelegentlich":["Überempfindlichkeitsreaktionen (Juckreiz, Nesselsucht)","Schlaflosigkeit, Appetitlosigkeit","Starkes Schwitzen, Nachtschweiss","Schwindel"],"selten":["Akute Gesichtslähmung (Fazialisparese)","Gesichtsschwellung bei Personen mit kosmetischen Hautfüllern"],"sehrSelten":["Myokarditis und Perikarditis (Herzmuskel- und Herzbeutelentzündung)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Erythema multiforme (Hautreaktion)","Ausgedehnte Schwellung der geimpften Gliedmasse","Starke Menstruationsblutungen","Kribbeln oder Taubheitsgefühl"]},"schwangerschaft":"Kann während der Schwangerschaft angewendet werden; grosse Beobachtungsstudien zeigen kein erhöhtes Risiko für Mutter oder Kind.","stillzeit":"Kann während der Stillzeit angewendet werden.","hinweise":["Nach der Impfung 15 Minuten (nach früherer schwerer allergischer Reaktion 30 Minuten) unter Beobachtung bleiben.","Bei Brustschmerzen, Atemnot oder Herzklopfen in den Tagen nach der Impfung sofort ärztliche Hilfe holen.","Die Impfstoffe werden regelmässig an neue Varianten angepasst; Impfempfehlung (meist im Herbst) für die eigene Situation in der Apotheke oder ärztlich klären."],"darreichung":["Injektionsdispersion in Durchstechflasche oder Fertigspritze"]},"crisantaspase":{"wirkmechanismus":"Entzieht Leukämiezellen einen Baustein, den sie zum Überleben brauchen. Crisantaspase ist das Enzym Asparaginase, das die Aminosäure Asparagin im Blut zu Asparaginsäure und Ammoniak abbaut. Leukämische Lymphoblasten können Asparagin kaum selbst herstellen; ohne Nachschub stoppt ihre Eiweisssynthese, und sie sterben ab. Weil das Enzym aus einem anderen Bakterium (Erwinia chrysanthemi) stammt, kann es nach einer Allergie gegen E.-coli-Asparaginase meist weiter eingesetzt werden.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen","Anämie, Thrombozytopenie, Neutropenie (auch mit Fieber)","Erhöhte Leberwerte und Bilirubin","Überempfindlichkeitsreaktionen (z. B. Ausschlag, Nesselsucht)","Hyperglykämie (erhöhter Blutzucker)","Bauchschmerzen","Müdigkeit, Fieber"],"haeufig":["Pankreatitis (Bauchspeicheldrüsenentzündung)","Thrombosen","Blutungen","Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Schwere Leberschädigung bis zum Leberversagen"]},"schwangerschaft":"Nicht anwenden, ausser wenn unbedingt nötig. Wirksame, nicht-orale Verhütung während und bis 3 Monate nach der letzten Dosis.","stillzeit":"Während der Behandlung nicht stillen; die Dauer der Stillpause danach ärztlich festlegen.","hinweise":["Starke Bauchschmerzen, Gelbfärbung der Haut, Schwellung oder Schmerzen in einem Bein, starker Durst oder häufiges Wasserlassen sofort melden.","Blutzucker, Leberwerte, Gerinnung und die Asparaginase-Aktivität im Blut werden regelmässig kontrolliert."],"darreichung":["Injektionslösung (intramuskulär)"]},"crizotinib":{"wirkmechanismus":"Blockiert gezielt veränderte Wachstumssignal-Enzyme in Lungenkrebszellen. Crizotinib hemmt die Rezeptor-Tyrosinkinasen ALK (einschliesslich Fusionsproteinen wie EML4-ALK), ROS1 und MET (HGF-Rezeptor). Tumoren, deren Wachstum von diesen Kinasen abhängt, werden so gebremst.","nebenwirkungen":{"sehrHaeufig":["Sehstörungen (Lichtblitze, verschwommenes Sehen, Doppeltsehen)","Übelkeit, Erbrechen, Durchfall, Verstopfung, Bauchschmerzen","Wassereinlagerungen (Ödeme), Müdigkeit","Erhöhte Leberwerte","Appetitlosigkeit, Geschmacksstörung","Nervenstörungen (Neuropathie), Schwindel","Langsamer Puls (Bradykardie)","Mangel an weissen und roten Blutkörperchen, Hautausschlag"],"haeufig":["Interstitielle Lungenerkrankung, Pneumonitis","QT-Verlängerung im EKG, Ohnmacht (Synkope)","Herzschwäche","Speiseröhrenentzündung, Verdauungsbeschwerden","Nierenzysten, erhöhtes Kreatinin","Tiefes Phosphat im Blut","Verminderter Testosteronspiegel"],"gelegentlich":["Leberversagen","Magen-Darm-Durchbruch (Perforation)","Akutes Nierenversagen"]},"schwangerschaft":"Nicht anwenden, ausser es ist zwingend notwendig. Frauen und Männer müssen während und mindestens 90 Tage nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Zweimal täglich unabhängig von den Mahlzeiten einnehmen; keine Grapefruit und kein Johanniskraut.","Sehstörungen sind häufig – Vorsicht beim Autofahren und Bedienen von Maschinen.","Leberwerte, Blutbild, Puls und EKG regelmässig kontrollieren lassen.","Neue Atemnot, Husten oder Fieber sofort melden."],"darreichung":["Hartkapseln"]},"cromoglicinsaeure":{"wirkmechanismus":"Verhindert, dass bestimmte Abwehrzellen (Mastzellen) bei Kontakt mit einem Allergen Histamin und andere Entzündungsstoffe freisetzen. Cromoglicinsäure stabilisiert die Zellmembran der Mastzellen, vermutlich über eine Hemmung des Calciumeinstroms, und unterdrückt so die allergische Sofortreaktion. Sie wirkt nur vorbeugend und nicht bei bereits bestehenden Beschwerden; die volle Wirkung tritt oft erst nach einigen Tagen regelmässiger Anwendung ein. Aus dem Darm wird sie kaum aufgenommen und wirkt deshalb vor allem örtlich.","nebenwirkungen":{"unbekannt":["Vorübergehendes Brennen, Stechen oder Fremdkörpergefühl im Auge, kurzzeitig verschwommenes Sehen","Übelkeit, Hautausschlag und Gelenkschmerzen (Kapseln)","Überempfindlichkeitsreaktionen bis Anaphylaxie"]},"schwangerschaft":"Langjährige Erfahrung ohne Hinweis auf Schädigung; besonders im ersten Drittel dennoch nur nach ärztlicher Abwägung.","stillzeit":"Geht kaum in die Muttermilch über; Anwendung nach ärztlicher Rücksprache möglich.","hinweise":["Regelmässig anwenden, am besten schon vor Beginn der Pollensaison – die Wirkung setzt erst nach einigen Tagen ein.","Kapseln vor den Mahlzeiten einnehmen; der Inhalt kann in heissem Wasser aufgelöst und mit kaltem Wasser verdünnt getrunken werden."],"darreichung":["Augentropfen","Kapseln"]},"crovalimab":{"wirkmechanismus":"Blockiert einen Teil des Komplementsystems, das bei PNH die ungeschützten roten Blutkörperchen zerstört. Crovalimab ist ein humanisierter monoklonaler IgG1-Antikörper, der an das Komplementprotein C5 bindet und dessen Spaltung in C5a und C5b verhindert; so entsteht kein zellzerstörender Membranangriffskomplex. Als Recycling-Antikörper löst er sich im Endosom vom C5 und kehrt über den neonatalen Fc-Rezeptor ins Blut zurück, was eine Gabe unter die Haut alle 4 Wochen erlaubt. Er bindet an einer anderen Stelle von C5 als Eculizumab und wirkt auch bei der seltenen C5-Variante R885H.","nebenwirkungen":{"sehrHaeufig":["Infusionsbedingte Reaktionen","Infekte der oberen Atemwege"],"haeufig":["Fieber","Kopfschmerzen","Hautausschlag","Gelenkschmerzen","Harnwegsinfekte","Reaktionen an der Injektionsstelle","Immunkomplex-Reaktionen (Typ-III-Überempfindlichkeit) nach Umstellung von einem anderen C5-Hemmer"],"unbekannt":["Meningokokken-Infektionen (Hirnhautentzündung, Blutvergiftung)"]},"schwangerschaft":"Nur nach strenger Nutzen-Risiko-Abwägung; Erfahrungen fehlen. Der Antikörper kann die Plazenta passieren.","stillzeit":"Keine Daten; über Stillen ist ärztlich zu entscheiden.","hinweise":["Patientenkarte mitführen. Bei Fieber, starken Kopfschmerzen, Nackensteifigkeit oder Hautflecken sofort den Notfall aufsuchen.","Meningokokken-Impfung mindestens 2 Wochen vor Beginn, sonst vorbeugende Antibiotika.","Nach Umstellung von Eculizumab oder Ravulizumab Gelenkschmerzen, Ausschlag oder Fieber melden."],"darreichung":["Injektions- bzw. Infusionslösung"]},"cyanocobalamin":{"wirkmechanismus":"Ersetzt fehlendes Vitamin B12, das für die Blutbildung und die Nerven unentbehrlich ist. Cyanocobalamin wird im Körper in die aktiven Formen Methylcobalamin und Adenosylcobalamin umgewandelt. Diese sind Coenzyme der Methioninsynthase (Bildung von DNA-Bausteinen zusammen mit Folsäure, Abbau von Homocystein) und der Methylmalonyl-CoA-Mutase (wichtig für die Myelinscheiden der Nerven). Normalerweise wird B12 mit Hilfe des Intrinsic Factor im Dünndarm aufgenommen; aus hoch dosierten Tabletten gelangt rund 1 % auch ohne Intrinsic Factor ins Blut, weshalb sie auch bei perniziöser Anämie wirken können.","nebenwirkungen":{"sehrSelten":["Anaphylaktische Reaktionen (schwere allergische Reaktion, v. a. nach Injektion)"],"unbekannt":["Überempfindlichkeitsreaktionen der Haut (Juckreiz, Ausschlag, Nesselsucht)","Akne, akneähnlicher Ausschlag","Magen-Darm-Beschwerden wie Übelkeit oder Durchfall","Schmerzen und Rötung an der Injektionsstelle","Hypokaliämie (Kaliummangel) zu Beginn der Behandlung einer schweren Blutarmut"]},"schwangerschaft":"In üblichen Dosen zur Behandlung eines Mangels erlaubt; Vitamin B12 ist in der Schwangerschaft wichtig.","stillzeit":"Erlaubt; Vitamin B12 geht in die Muttermilch über, was bei Mangel der Mutter auch für das Kind wichtig ist.","hinweise":["Bei perniziöser Anämie oder nach Magenentfernung ist die Behandlung meist lebenslang nötig – nicht eigenmächtig absetzen.","Zu Beginn der Behandlung Blutbild und Kalium kontrollieren lassen.","Bei Vitamin-B12-Mangel nie nur Folsäure einnehmen: die Blutarmut bessert sich, die Nervenschäden schreiten aber fort."],"darreichung":["Filmtabletten (hoch dosiert)","Injektionslösung"]},"cyclophosphamid":{"wirkmechanismus":"Hemmt die Teilung schnell wachsender Zellen, vor allem von Krebs- und Immunzellen. Cyclophosphamid ist ein Prodrug: Es wird in der Leber (vor allem über CYP2B6, daneben CYP2C9, CYP2C19 und CYP3A4) zu 4-Hydroxycyclophosphamid aktiviert, das in den eigentlichen Wirkstoff Phosphoramid-Lost und das blasenreizende Acrolein zerfällt. Phosphoramid-Lost vernetzt die DNA-Stränge (Alkylierung) und löst so den Zelltod aus. Durch die Wirkung auf B- und T-Lymphozyten unterdrückt es zudem stark das Immunsystem.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung mit Mangel an weissen Blutkörperchen (Leukopenie, Neutropenie)","Geschwächte Immunabwehr (Immunsuppression)","Haarausfall (Alopezie), meist vorübergehend","Blasenreizung (Zystitis) mit mikroskopisch nachweisbarem Blut im Urin","Fieber"],"haeufig":["Infektionen, Fieber bei Neutropenie","Blasenentzündung mit Blut im Urin (hämorrhagische Zystitis)","Schleimhautentzündungen","Erhöhte Leberwerte","Gestörte Spermienbildung","Schüttelfrost, Schwäche, Müdigkeit"],"gelegentlich":["Lungenentzündung, Blutvergiftung (Sepsis)","Thrombozytopenie und Anämie","Überempfindlichkeitsreaktionen","Appetitlosigkeit","Herzmuskelschäden (Kardiomyopathie, Myokarditis), Herzinsuffizienz","Nervenschäden (periphere Neuropathie)","Störungen des Eisprungs"],"selten":["Hyponatriämie (Natriummangel) durch vermehrte ADH-Ausschüttung (SIADH)","Herzrhythmusstörungen","Schwindel, Krampfanfälle","Hautausschlag","Ausbleiben der Monatsblutung, fehlende Spermienbildung (Unfruchtbarkeit)"],"sehrSelten":["Venenverschlusskrankheit der Leber","Stevens-Johnson-Syndrom und toxische epidermale Nekrolyse","Anaphylaktischer Schock"],"unbekannt":["Übelkeit und Erbrechen (dosisabhängig)","Zweittumoren wie akute Leukämie, myelodysplastisches Syndrom oder Blasenkrebs","Interstitielle Lungenerkrankung, Lungenfibrose","Tumorlyse-Syndrom","Hämolytisch-urämisches Syndrom (Blutzerfall mit Nierenversagen)"]},"schwangerschaft":"Fruchtschädigend; darf nur bei lebensbedrohlicher Erkrankung der Mutter angewendet werden. Frauen müssen während und bis 12 Monate nach der Behandlung zuverlässig verhüten, Männer bis 6 Monate danach.","stillzeit":"Kontraindiziert; der Wirkstoff geht in die Muttermilch über.","hinweise":["Am Behandlungstag und danach reichlich trinken und die Blase häufig entleeren; Tabletten morgens einnehmen – schützt vor Blasenentzündung.","Regelmässige Kontrollen von Blutbild, Urin, Nieren- und Leberwerten; Blut im Urin, Fieber oder Atemnot sofort melden.","Vor Behandlungsbeginn über Möglichkeiten zum Fruchtbarkeitserhalt (Einfrieren von Spermien oder Eizellen) sprechen.","Grapefruit und Alkohol meiden."],"darreichung":["Dragées (überzogene Tabletten)","Pulver zur Herstellung einer Injektions- oder Infusionslösung"]},"cyproteron":{"wirkmechanismus":"Blockiert die Wirkung der männlichen Geschlechtshormone und drosselt zugleich deren Bildung. Cyproteronacetat verdrängt Testosteron und Dihydrotestosteron kompetitiv von den Androgenrezeptoren in den Zielorganen (Prostata, Haarfollikel, Talgdrüsen, Gehirn). Durch seine starke gestagene Wirkung hemmt es ausserdem über die Hirnanhangsdrüse die Ausschüttung von LH und FSH, wodurch der Testosteronspiegel sinkt. Bei Frauen hemmt es so auch den Eisprung.","nebenwirkungen":{"sehrHaeufig":["Verminderte Libido und Erektionsstörungen (Männer)","Reversible Hemmung der Samenbildung (Männer)"],"haeufig":["Leberschäden einschliesslich Gelbsucht, Hepatitis und Leberversagen","Gewichtszunahme oder -abnahme","Depressive Verstimmung, vorübergehende Unruhe","Müdigkeit, Hitzewallungen, Schwitzen","Atemnot (Dyspnoe)","Gynäkomastie (Brustvergrösserung beim Mann)"],"gelegentlich":["Hautausschlag"],"selten":["Überempfindlichkeitsreaktionen"],"sehrSelten":["Gutartige und bösartige Lebertumoren","Blutung in die Bauchhöhle (bei Lebertumoren)"],"unbekannt":["Meningeom (Hirnhauttumor), besonders bei langer Anwendung hoher Dosen","Thromboembolische Ereignisse (Thrombose, Embolie)","Anämie (Blutarmut) bei Langzeitbehandlung","Osteoporose","Bei Frauen: Zwischenblutungen, Brustspannen, Hemmung des Eisprungs"]},"schwangerschaft":"Kontraindiziert: Cyproteron kann bei männlichen Feten zu einer Verweiblichung führen. Frauen müssen während der Behandlung zuverlässig verhüten (in der Regel mit einer kombinierten Pille); eine Schwangerschaft vor Beginn ausschliessen.","stillzeit":"Kontraindiziert – etwa 0,2 % der Dosis gehen in die Muttermilch über und können beim Säugling antiandrogen wirken.","hinweise":["Leberwerte vor Behandlungsbeginn und regelmässig während der Therapie kontrollieren lassen; bei Gelbsucht, dunklem Urin oder Oberbauchschmerzen sofort ärztlichen Rat einholen.","Die niedrigste wirksame Dosis verwenden; bei Hautproblemen der Frau nach Besserung schrittweise reduzieren.","Müdigkeit und Konzentrationsschwäche können die Fahrtüchtigkeit beeinträchtigen; Alkohol schwächt die triebdämpfende Wirkung ab.","Neu auftretende Kopfschmerzen, Sehstörungen, Krampfanfälle oder Lähmungen ärztlich abklären lassen (Meningeom)."],"darreichung":["Tabletten"]},"cyproteron-ethinylestradiol":{"wirkmechanismus":"Dämpft die Wirkung männlicher Hormone auf Haut und Haarwurzeln und verhindert gleichzeitig den Eisprung. Cyproteronacetat blockiert die Androgenrezeptoren in Talgdrüsen und Haarfollikeln und vermindert über seine Gestagenwirkung die Androgenbildung in den Eierstöcken. Ethinylestradiol steigert in der Leber die Bildung des Bindungsproteins SHBG, wodurch weniger freies Testosteron im Blut zirkuliert, und stabilisiert den Zyklus. Zusammen hemmen beide den Eisprung.","nebenwirkungen":{"haeufig":["Übelkeit, Bauchschmerzen","Gewichtszunahme","Kopfschmerzen","Depressive Verstimmung, Stimmungsschwankungen","Brustschmerzen, Brustspannen"],"gelegentlich":["Erbrechen, Durchfall","Wassereinlagerungen","Migräne","Verminderte Libido","Brustvergrösserung","Hautausschlag, Nesselsucht"],"selten":["Venöse und arterielle Thromboembolien (Beinvenenthrombose, Lungenembolie, Herzinfarkt, Schlaganfall)","Unverträglichkeit von Kontaktlinsen","Überempfindlichkeitsreaktionen","Gewichtsabnahme, gesteigerte Libido","Ausfluss aus Scheide oder Brust","Erythema nodosum oder Erythema multiforme (entzündliche Hautrötungen)"],"unbekannt":["Blutdruckanstieg","Zwischen- und Schmierblutungen","Chloasma (bräunliche Pigmentflecken)","Meningeom (Hirnhauttumor)","Lebertumoren"]},"schwangerschaft":"Kontraindiziert. Vor Beginn eine Schwangerschaft ausschliessen; tritt eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Kontraindiziert – die Wirkstoffe gehen in die Muttermilch über und können die Milchmenge vermindern.","hinweise":["21 Tage lang täglich zur gleichen Zeit eine Tablette, danach 7 Tage Pause; nach Abklingen der Haut- bzw. Haarbeschwerden (meist nach 3–4 Zyklen) die Notwendigkeit ärztlich überprüfen lassen.","Bei Erbrechen oder starkem Durchfall innerhalb von 3–4 Stunden nach der Einnahme ist der Verhütungsschutz unsicher.","Warnzeichen einer Thrombose (schmerzhaft geschwollenes Bein, plötzliche Atemnot, Brustschmerz, plötzliche Seh- oder Sprechstörung) sofort ärztlich abklären lassen.","Nicht rauchen; vor geplanten Operationen oder längerer Ruhigstellung die Einnahme ärztlich besprechen."],"darreichung":["Dragées (überzogene Tabletten)"]},"cytarabin":{"wirkmechanismus":"Hemmt die Vermehrung sich rasch teilender Zellen, besonders von Leukämiezellen. Cytarabin wird in der Zelle zu Cytarabin-Triphosphat (Ara-CTP) aktiviert, das die DNA-Polymerase hemmt und als falscher Baustein in die DNA eingebaut wird. Dadurch bricht die DNA-Synthese ab; betroffen sind vor allem Zellen in der Synthesephase (S-Phase) des Zellzyklus.","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung (Mangel an weissen und roten Blutkörperchen und an Blutplättchen)","Infektionen bis zur Sepsis, Lungenentzündung","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Entzündungen und Geschwüre in Mund und Afterbereich","Leberfunktionsstörungen (erhöhte Leberwerte)","Haarausfall, Hautausschlag","Fieber","Bei Hochdosistherapie: Kleinhirnstörungen, Augenentzündungen, Lungenödem"],"gelegentlich":["Gelbsucht","Perikarditis (Herzbeutelentzündung)","Entzündung und Geschwüre der Speiseröhre","Nervenentzündung, Schwindel, Kopfschmerzen","Hand-Fuss-Syndrom, Hautgeschwüre, Juckreiz, Nesselsucht","Muskel- und Gelenkschmerzen","Nierenfunktionsstörung, Harnverhalt","Atemnot, Halsschmerzen"],"sehrSelten":["Herzrhythmusstörungen"],"unbekannt":["Cytarabin-Syndrom (Fieber, Muskel- und Knochenschmerzen, Ausschlag, Bindehautentzündung)","Anaphylaxie (schwere allergische Reaktion)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Darmnekrose, Darmdurchbruch","Herzmuskelschädigung bei Hochdosistherapie"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit, besonders im ersten Schwangerschaftsdrittel meiden, da Cytarabin fruchtschädigend wirken kann. Frauen und Männer müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Bei Hochdosistherapie werden zur Vorbeugung von Augenentzündungen kortisonhaltige Augentropfen gegeben.","Fieber, Halsschmerzen oder Blutungszeichen sofort melden; Blutbild wird regelmässig kontrolliert.","Keine Lebendimpfungen während der Behandlung."],"darreichung":["Injektions- und Infusionslösung"]},"cytomegalievirus-immunglobulin":{"wirkmechanismus":"Verleiht vorübergehenden Schutz gegen das Zytomegalievirus (passive Immunisierung). Das Präparat enthält menschliche Immunglobuline (vor allem IgG) aus dem Plasma von Spendern mit hohem Antikörperspiegel gegen CMV. Die Antikörper neutralisieren das Virus und unterstützen die geschwächte Abwehr, sodass eine Infektion seltener zu einer Erkrankung führt.","nebenwirkungen":{"unbekannt":["Grippeähnliche Reaktionen: Schüttelfrost, Fieber, Kopfschmerzen, Übelkeit, Erbrechen","Gelenk- und mässige Rückenschmerzen","Blutdruckabfall, selten plötzlicher Kreislaufkollaps","Allergische Reaktionen bis zum anaphylaktischen Schock","Aseptische Meningitis (nicht-infektiöse Hirnhautentzündung)","Hämolytische Anämie (Blutzerfall)","Anstieg des Kreatinins bis akutes Nierenversagen","Thromboembolien (Herzinfarkt, Schlaganfall, Lungenembolie, tiefe Venenthrombose)"]},"schwangerschaft":"Erfahrungen mit Immunglobulinen zeigen keine schädlichen Wirkungen auf Schwangerschaft und Kind; Anwendung nach ärztlicher Abwägung.","stillzeit":"Kann angewendet werden; Immunglobuline gehen in die Muttermilch über.","hinweise":["Wird als Infusion im Spital oder in der Praxis unter Überwachung gegeben; vorher ausreichend trinken.","CMV-Kontrollen im Blut nach Anweisung des Transplantationszentrums.","Lebendimpfungen erst 3 Monate später; Antikörpertests können vorübergehend verfälscht sein."],"darreichung":["Infusionslösung"]}});
